/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210706-6","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"区民委員会","time":"午前１０時００分～午前１１時２７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"第３９号議案、品川区手数料条例の一部を改正する条例","agenda":"第３９号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ品川区からＪ－ＬＩＳに移るのか、その目的について伺いたいと思います。あわせて、Ｊ－ＬＩＳとはどんな組織なのか、国との関係についてもご説明ほしいと求めました。","respondent":"木村戸籍住民課長","answer":"令和４年度末までに国民全員にマイナンバーカードを交付するという国の目標がございまして、チェック体制、それから発行体制の強化を目指してです。Ｊ－ＬＩＳはそういう組織です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"マイナンバーカードの普及は、個人情報を全員一元化させ、個人情報漏えいの危険も繰り返し言われております。マイナンバーの推進は行うべきではないと、意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、再交付申請のとき、１件につき８００円という手数料の額は変わらないということでよろしいのでしょうか。９月以降は歳入歳出外現金になるということなのですけれども、大体何件くらいで、総額幾らくらい見込んでいらっしゃるのか尋ねました。","respondent":"木村戸籍住民課長","answer":"手数料額ですが、変わらない予定でということなのですけれども、８月中に決定するです。基本的には変わらない予定です。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"それを、国の法改正でしようがないではないですかと言われるかもしれないけれども、少し考えなくてはいけないという形にはならなかったのですよね。このようにしますというような、この一文だけになっていていいのかなという思いが少しあるのですけれども、その辺についてはいかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"ただ、実際に制度であったり、運用であったりという部分は一切変わりませんので、私どもが責任を持って交付を続けてまいるというところではあります。全体としては、大きな変更はございませんので、ご理解いただければと思います。","id":"exchange-004"},{"speaker":"藤原委員","kind":"確認","question":"今の答弁の確認ですが、より一層個人情報は、国の目が入ることによって守られていきますという理解でよろしいのか尋ねました。","respondent":"木村戸籍住民課長","answer":"今回の改正による変更に関しましては、いわゆる個人情報の取扱いの部分での変更というのは特にございませんので、今まで同様にしっかりやっていくという形です。","id":"exchange-005"},{"speaker":"中塚委員","kind":"意見","question":"マイナンバーを強化・加速させるべきではないと思いますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"}]},{"id":"topic-02","title":"令和２年陳情第６２号、目黒川沿いに設置されている喫煙所撤去に関する陳情","agenda":"令和２年陳情第６２号、目黒川沿いに設置されている喫煙所撤去に関する陳情","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ポイ捨て禁止の条例がありますけれども、たばことして扱っているのかどうか、その点を確認させてほしいと求めました。加熱式たばこの健康被害は、私はあると思っているのですが、その点についてもご説明ほしいと求めました。","respondent":"森田生活安全担当課長","answer":"加熱式たばこについてのご説明です。受動喫煙のリスクについては、科学的根拠は十分ではなく、さらなる研究が必要とされております。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"加熱式喫煙所になったとはいえ、健康被害をもたらすものなので、結論めいたことを言ってしまうけれども、撤去すべきだと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"課長に伺うのか、委員長に伺うのか、撤去をお願いしますという内容です。どういう流れで、趣旨採択でとは思っていたのですけれども、もう陳情代表者が承諾をしているわけですよね。","respondent":"森田生活安全担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"藤原委員","kind":"確認","question":"こういう形で、していただいたから、この裏面にある再開後のイメージ図みたいにしていきますという形で報告してくれたということでいいのでしょうか。改めて確認します。","respondent":"森田生活安全担当課長","answer":"そのとおりです。引き続き、やっていきたいと思います。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"これは直接委員会等で質問はしておりませんので、改めて伺うのですけれども、その辺についてはいかがでしょうか。これからこういうことは出てくるわけですから、現実どうなっているのか、説明を求めました。","respondent":"森田生活安全担当課長","answer":"喫煙所のたばこ会社の協力ですが、今回の本村橋喫煙所につきましては、フィリップモリスから敷地の中の看板等、喫煙の灰皿も含めて、受けたという形になっています。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"あちらのほうにも幾つかあると思うのですが、そういったところとの品川区の考え方の違いを、まず伺いたいのです。準じていてしかるべきだと思うのですけれども、しないという考え方について、改めて伺いたいのですけれども。","respondent":"森田生活安全担当課長","answer":"たばことして認識されておりますので、我が品川区も今の現状、加熱式たばこと分けてというのは考えてはおりません。加熱式たばこの科学的根拠等が解明されるなどしてくれば、また調査・研究を進めてまいって、分けるということもあるかと私は考えております。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"そこについての明確なルールをもう一回伺いたいのと、電子たばこについては、あくまで電子たばこについては対象になっていないではないですか。そもそも加熱式たばこを規制するという理由について、すみません、私の質問が分かりづらいかもしれないのですけれども、伺いたいのですが。","respondent":"森田生活安全担当課長","answer":"それが１点です。先ほど説明させていただきましたが、紙たばこは取り締まるという考えでは、また調査・研究を進めていきたいと考えています。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"品川区の加熱式たばこに対する取締りのルールのよりどころというのを、まず伺いたかったので、そこに関しては分かりました。これは大崎駅西口の加熱式たばこ専用喫煙所が区内で初めてだったのかどうかということと、そこについて伺えますか尋ねました。","respondent":"森田生活安全担当課長","answer":"大崎駅西口の加熱式たばこの喫煙所につきましては、区内で初めての加熱式専用の喫煙所です。今設置してある箇所の状況や、他に選定できる箇所があれば、随時進めていきたいとは考えております。","id":"exchange-014"},{"speaker":"くにば委員","kind":"質問","question":"吸うところがなくなるわけですから、ポイ捨てが増える可能性もありますし、結局その煙害という被害が発生してしまうのではないかという懸念。それとも、そういったトラブルであるとか、その他何かトラブルとか課題はなかったのかという部分を伺いたいです。","respondent":"森田生活安全担当課長","answer":"設置当初は紙たばこを吸う方もいらっしゃいましたが、またその喫煙所が経過によって、現在は加熱式たばこの方だけになっているようなところです。ここには、目黒川の反対側に花房通り沿いの喫煙所もございまして、紙たばこの方はそちらへというご案内も入れする予定です。","id":"exchange-015"},{"speaker":"くにば委員","kind":"質問","question":"花房通りのほうに喫煙所があるというのは、前回、昨年この陳情について我々で議論したときに、そのときの課長に、近隣にないと伺ったのです。ポイ捨てであるとか、問題がなくなってくると思うのですが、そこの２点についてお伺いしたいのですけれども。","respondent":"森田生活安全担当課長","answer":"花房通りにつきましては、ちょっと遠いところではあります。火種や煙や臭いの問題も考えますと、あそこでは加熱式たばこが一番よいのではないかということで、結論を出したところです。","id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"伺ったニュアンスで感じたので、例えば大井町駅の城南信金の近くの喫煙所に関しては、かなり苦情が来ていたと思うのです。そういった、加熱式たばこに今後転換したほうがいいのではないかということは、どのようにお考えになられているのか伺いたいです。","respondent":"森田生活安全担当課長","answer":"臭いが出ないというものの設置を根本的には考えておりますが、設置の場所的に、加熱式に転換をするなどもやっております。様々なことも検討しているところでございまして、その解決の折には、何かしらの代替の喫煙所となるものを設置したいということでは考えております。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問・要望","question":"ほかのところでもトラブル、煙害が発生しているところに関して、同様の措置というのをどんどん推進していただきたいと個人的に考えております。所感を述べて、以上にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"その中で、その場所で過料を徴収したという事例はあったのですか。これから先、整えていただきたいという、これは要望で終わりにします。","respondent":"森田生活安全担当課長","answer":"本村橋の喫煙所の周辺の徴収については、実際にあります。件数については、手元の資料ですと、８件あります。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"紙たばこも含めての受動喫煙対策というのを、さらに大胆に品川区にはやっていただきたいということを、ぜひ要望したいと思います。吸う方のマナー向上に対して、どのように品川区は取り組んでいかれるのかというところを、２点お伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"生活安全パトロール隊につきましては、引き続き本村橋周辺のパトロールを、指導等を継続的にやってまいります。パトロール隊の広報や、引き続き行いまして、周辺で喫煙される方々に対しましても啓発をしてまいりたいと思います。","id":"exchange-020"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"品川区が大胆に、この喫煙所の設置というところに向けては、もう少し予算をつけながらやっていただきたいというのが要望としてあります。ちょっと関連したことになりますが、今後の方向性といいますか、どういうところを区が検討されているのかという状況を教えてほしいと求めました。","respondent":"森田生活安全担当課長","answer":"まずは密閉型をという考えはありましたが、場所的なところもあり、できなかったというところもあります。民間の場所につきましても、補助を出せるようにしましたので、民間の場所においても喫煙所ができるような形で進めていきたいとも思っています。","id":"exchange-021"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ぜひ、たばこ会社の協力もたくさんいただきながら、取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いいたします。トラブルが起こる、喫煙所を密閉型・加熱式への転換というお話がありましたけれども、区民の方へのマナーの啓発も引き続きお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問","question":"理由を述べさせてもらいます。加熱式専用にしたということは、いろいろ苦慮されたということだと思いますので、改めて趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"道路を含め、公共の場での喫煙は規制が必要だと思います。健康被害についても、引き続き深刻なものがありますので、加熱式たばこであっても撤去すべきだと思いますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"くにば委員","kind":"意見","question":"結論を出すで、採択でお願いします。ここに喫煙所というのは置くべきではないというのが一つあったのですが、区内でも同様のトラブルであるとか被害がなくなることを願っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-03","title":"議題順を変更いたしまして、(2)区民斎場「なぎさ会館」エレベーター工事に伴う休館","agenda":"議題順を変更いたしまして、(2)区民斎場「なぎさ会館」エレベーター工事に伴う休館","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"私が感じるのは、長期間にわたって休館するわけですけれども、この期間は、休館だから全く使えないわけです。まず教えていただきたいのですが、その辺について、どのようになるのか説明を求めました。","respondent":"木村戸籍住民課長","answer":"現在の想定件数ですけれども、１２件という形になります。それから、実際にはご案内のとおり、臨海斎場あるいは桐ヶ谷斎場をご案内するという形になると思います。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"できないというのは、やれない、葬儀ができないということですか。４か月で１２件しかないということはないと思うのですが。","respondent":"木村戸籍住民課長","answer":"言葉足らずで申し訳ございません。お使いになられた稼働率が２１.６％ということで、休館日数５９日ということで計算しますと、空いているときが多いです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"１２件、そんなにやってほしい火葬ができなくなってしまうとか、亡くなられてから何週間も火葬することができないという状況にはならないということですね。","respondent":"木村戸籍住民課長","answer":"ご認識のとおりです。","id":"exchange-029"},{"speaker":"藤原委員","kind":"意見","question":"１２件というと、４か月で１２件という形に、何かありますかとの意見を述べました。","respondent":"木村戸籍住民課長","answer":"現在、検討を進めてまいっているところです。引き続き、それは行ってまいります。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問","question":"新しいものに関してなのですけれども、こちらの耐用年数は大体どのぐらいになるのでしょうか。どういったところが変わってくるのかというのと、日常点検のコストみたいなところにも変わるのであれば、その変更点を説明するよう求めました。","respondent":"木村戸籍住民課長","answer":"申し訳ございません。それから、保守のコストに関しましては、基本的にそれほど変わりはないです。","id":"exchange-031"},{"speaker":"横山委員","kind":"確認","question":"もう１点なのですけれども、安定性のところにも関わるかもしれませんが、地震等の災害の際に、どのような対応のものになるのでしょうか。避難がしやすいものとか、今は新しい機能がいろいろあるかと思うのですけれども、その辺りだけ確認したいと求めました。","respondent":"木村戸籍住民課長","answer":"基本的には、一番近い階とはいっても、それほど移動する階もないのですけれども、そこに止まって、通報が飛んで、人が来るという、今、エレベーターのベースにあるような新しい部分は、全部網羅する予定です。","id":"exchange-032"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"撤去で１月１７日から１月３１日ということで、１２月の１か月間というのは作業がないと思われるのですが、確認させてください。使い勝手のところでの改修みたいなものというのは、何か計画があるのか、その辺を教えてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"新設工事のために休館する、撤去工事のために休館する、この間に関しましては、音とか振動が伴わない部分ということで、通常どおり開館をします。それから、使い勝手の部分ですけれども、現時点では何か改修を行うという予定はございません。","id":"exchange-033"}]},{"id":"topic-04","title":"令和２年国勢調査の速報値","agenda":"令和２年国勢調査の速報値","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"品川区は７７.０％ではないですか。今、最初の説明で、人口がこのぐらい、世帯数はこのぐらいだと説明してくれたけれども、この回答率で、正確なものというのは出てくるのか尋ねました。","respondent":"川島地域活動課長","answer":"失礼いたしました。残りの２３％というのは、職員が調査をして回答させていただいて、全て足すと１００％になるです。","id":"exchange-034"},{"speaker":"藤原委員","kind":"確認","question":"それを確認したくて、あれだけの予算を使って国勢調査するわけですから、人口だけを調べる調査ではないのです。もう一つ確認は、私も何回も伺ってしまいますが、実際に５０万円等の形で科されるということはされないわけです。","respondent":"川島地域活動課長","answer":"たしか５０万円の罰金という形で、１００％という形で回答させていただいて、しっかりした数字を報告しているものです。","id":"exchange-035"}]},{"id":"topic-05","title":"しながわ区民公園屋外水泳場への予約システム導入","agenda":"しながわ区民公園屋外水泳場への予約システム導入","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ伺いたいのですけれども、１組何人とか、それはどういう設定になっているのか。そういうのはどうなのかなとは思うのですけれども、１組何人なのか、そこの説明をいただけますか尋ねました。","respondent":"中元スポーツ推進課長","answer":"すみません、ご説明が不足しておりました。１組５人までということで、枠についても１日１枠、システムでチェックをします。","id":"exchange-036"},{"speaker":"西村委員","kind":"確認","question":"１点だけ、すみません。ホームページを見ていればよかったのですけれども、ウェブを使えない方とか、その他の申込方法の確認を求めました。","respondent":"中元スポーツ推進課長","answer":"ウェブが使える環境にない方は、電話番号を、広報紙やホームページにも載せてございまして、電話での受付もさせていただいてあります。","id":"exchange-037"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"新妻副委員長","kind":"質問","question":"１点だけお伺いします。ここに掲載されている１２件というのは、どういう条件で載せられているのかお伺いします。","respondent":"篠田文化観光課長","answer":"こちらは、観光振興協議会水辺部会で整理いたしまして、基本的には全部載っているということで認識しています。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2902#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25608,"voices":127}},{"id":"r03-20210706-7","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"厚生委員会","time":"午前１０時００分～午後 ３時２６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"第４０号議案、品川区手話言語条例","agenda":"第４０号議案、品川区手話言語条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとアンケート調査もされたということですけれども、「身体障害者手帳の交付を受けている聴覚障害の方（約８００人）」とあるのです。回答数が１４３人ということなのですけれども、８００人の方、絞った理由を聞かせてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"２、やはり手話をお使いいただいていると区のほうでも考えておりましたので、障害の程度が重い人ほど手話を使っているということが判明したです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"アンケートですけれども、そうすると、この２７６人というのは、手帳の１級、２級、３級の方に絞ったということではないのですか。そこを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"抽出の方法ですけれども、無作為抽出です。こちらの回答ですが、一定程度の母数があれば明らかになるものがありますので、調査の母数としては、これで有効であるというふうに判断しております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"環境整備をどう進めていくのかという実施計画、推進計画、そういったものが必要だと思うのです。「この条例の施行後３年を目途として、こういうモデル等は参考にされたのかどうか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"全日本ろうあ連盟の条例のモデルは承知しております。４つの団体と協議するにあたり、２年間にわたるかなり長い話し合いの中で、条例案として提案をさせていただいたところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"ということは、条例には入れ込んでいないけれども、実施計画なり推進計画をつくるべきだと思うのです。どういうふうに区が進めいくのかということが、そうした推進計画をつくるべきだと思うのですけれども、そこら辺は検討されているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"さらに理解促進を進めるということで、今後も定期的に理解促進を進める方策について一緒に話をしていきましょうということで合意がとれております。計画については、作成する考えはございません。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"想像以上に波及効果があらわれて、理解も大きく進んで、区民が独自で動き出すというようなことなども書かれているのです。普及させていくために環境整備を推進するという区の責務があるわけですから、方針、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"今後も４つの団体とは丁寧に話し合い、計画ありきではなく、ご本人たちの思いを条例の前文にも反映しています。やはりご本人たちのご意見は尊重していきたいと考えておりますので、計画については策定する考えはございません。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"手話の普及を進めるということにつながると思ったので、ぜひ計画等の検討をとは思ったのですが、その考えはないということです。でも、計画なしにどうやって進めていくのかと思うところですので、意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私は前文のところにも入れていただいたほうがいいのではなかったかというふうな思いがあるのですけれども、その点についてはいかがでしょうか。説明を求めました。","respondent":"松山障害者福祉課長","answer":"これまでの手話の歴史的な背景を前文のところに入れたほうがいいのではないかというご指摘です。こちらの第４０号議案の中で、手話言語条例の第１条（目的）の前の前文のところには、前文に思いを反映させていただいたところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その団体の皆さんからどのような課題ですとか、要望で出されたのかというところは、何かまとまったものがあるのでしょうか。具体的に課題や要望がどのようなことが出されたのかということについてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"団体の方々とのヒアリングの内容ですけれども、結論としては、この条例にどのように文言を採用し、反映していくかというところが一番のところです。４月から１日増やしましたけれども、あとは日常的に、もう既に具体的に進める方策も一緒に話をしています。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうふうなところでの具体的にどうしていくのかというのは、そしてその中で具体的に定期的に要望を聞きながら具体化をしていくということも。そういうことをしていかないと、なかなか具体化が進んでいかないのではないかというふうな思いがしているのですけれども、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"区の責務として、この条例を基に進めていく、実効性のあるものを行っていくという区の姿勢は変わるものではありません。この４つの団体と話し合って進めていくということは変わりませんので、この条例に基づいて同じような形で進めていきたいと考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"この４つの団体とは、それと同じような形で定期的に話し合いを進めて具体化をしていくということで確認させていただいてもいいでしょうか。その点についても伺います。","respondent":"松山障害者福祉課長","answer":"４つの団体と話を進めて、障害者理解、手話の理解を進めていくということは合意を得ているところです。それぞれの方の思いは尊重して進めていきたいと考えていますので、品川区ならではの、品川区をつくっていきたいと考えております。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"手話通訳派遣の依頼件数が２倍以上に増えたとか、そういうふうなところでも、ぜひ品川区でも実効性のあるものにしていってほしいと求めました。ちなみに、濱野区長がここに入られているのか、その点についても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"１点目ですけれども、年に２回は必ず実施してまいりまして、品川区聴覚障害者協会の会長とはメールでやり取りをしています。ですので、今後も４つの団体と引き続き定期的に行っていきたいと考えております。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"教えていただきたいのですが、アンケートの２ページのところで、どういうことで使用されていないのかというふうなところを教えていただきたいのと。そこの今の教育の分野ですとか、手話の現状というか、そこら辺のところがどうなっているのかということについて教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"３級の方は何かしら手話を使っている方が多いですけれども、４級以降、ほかの手段を使っているのではないかと推測されます。次に教育分野につきましては、所管が異なりますので、ここでは差し控えたいと思います。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"発展型と言えばいいのでしょうか、そこにいかずに、手話言語条例。ちょっと言い方は失礼ですけれども、ややゆっくりめで今回制定したわけですけれども、手話言語条例に限定されたところの説明を少しお願いします。","respondent":"松山障害者福祉課長","answer":"それぞれ別々につくっているところもあれば、一緒に包括的につくっているところもあります。４つの団体との協議の中では、今後、検討はしていきたいと考えております。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話にあったように、その制定に向けて、また検討をしていってほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"この２年間、私どもも会派として明晴学園にお話を伺いに行く等、これは大変に高い評価をまずはさせてほしいと求めました。そういうことが１つ重要ではないかという強い思いの中で、４点ぐらいお聞きしたかと思いますけれども、それぞれお話を伺えればと思います。","respondent":"松山障害者福祉課長","answer":"今まで４団体の方々と意見のすり合わせを丁寧に行ってきたわけなのですが、団体の方々もいろいろご苦労があったのではないかと考えています。区といたしましても、今後、積極的に、どうやって裾野を広めるかというところには全力を尽くしていきたいと考えております。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々の会派も団体の方々と何回もヒアリングをさせていただいて、区長要望も提出をして、何度もこの話はしてきたと考えています。その点だけ要望させていただいて、この議案については賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"私も賛成なのですけれども、１点、要望だけします。追加でもいいと思うのですけれども、ぜひそこは期待して、要望して賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"会議の運営上、予定表の順序を入れ替えまして、(4)第３６号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"会議の運営上、予定表の順序を入れ替えまして、(4)第３６号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"委託先をお聞きしたいのと、広報しながわ臨時号ということですけれども、これの内容。そういうことがされましたとか、広報しながわ臨時号の内容はどのような内容にすると考えているのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"それから３点目の広報しながわ臨時号の内容についてのご質問です。そのほかには障害者の福祉の特集号といたしまして、この条例に限らず、広く障害者理解を進めるような記事の掲載を考えております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"どういう方が不承認になるのかということを伺いたいのと、緊急小口資金の実績、人数と総額を教えてください。人件費もあると思うのですけれども、何人体制ぐらいのものなのか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"受付期間につきましては、まずはそちらに向けて対応していくということで、特に現時点で延長等の話について検討できる状況ではないです。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、ここは増額等も今後求めてほしいと求めました。そこのところを根拠ということですけれども、申請がさらに想定を超えてくる場合は、どのように対応されるのかということを伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"基本的には社会福祉協議会が対応されることで、審査基準は、貸付に関してはあまり公開されるものではないのかと思っているところです。再度補正予算等のご提案をする可能性もありますし、状況によって、また臨機応変に対応させていただこうと思っているところです。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ柔軟に対応してほしいと求めましたし、国に求めるべきことは、ぜひ求めてほしいと求めました。未遂してしまった人への相談とか声かけというのは、今まではなかったと、できてこなかったということなのかということを伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"こちらの事業委託は、専門家から成る集団で、既に荏原保健センターの退院支援事業などを委託している非常に専門性の高いＮＰＯになります。そこへの支援というのは、ほかの荒川区等では以前から救急病院との連携でこういった対応をしているということは存じておりましたが。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"そこの協力関係というのは考えているのかどうか、伺いたいと思います。伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"開始がかなり遅いものですから、他自治体なども対応している中で、今回こういうふうな額になっております。もちろん自殺対策としての区の当初予算で要求をして、当然、これについては続けていく予定で考えているところです。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"約３億６,０００万円ですけれども、人件費とか、回線を引く経費とか、どういうものにどれだけかかるのか。こちらの場合はすごくかかるのだなと思ったのですけれども、どういう算定の仕方で、何にどれくらいかかっているかということを伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"計算をしますと、大体３億５,０００万円ぐらいまで計算が積み上がっていくという形になっていきます。会場確保のお金も含め、全て含まれていて、１人頭大体３万５,０００円程度というふうな算出になります。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、人件費が高騰していると、１人３万５,０００円というのは、１日ということなのですか。そして、１００回線と５０回線、要するに、１５０回線分みたいな数え方でいいのか、そこを伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"私の説明が不適切ですみません。大変失礼いたしました。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問","question":"１点、すみません。その方法というか、情報共有とかのツールはどういうふうになるのか、説明を求めました。","respondent":"鷹箸保健予防課長","answer":"初めは１つか２つの病院に、そういう方がいらしたときに、直接そのＮＰＯに連絡するということで考えています。ネットを使うとか、そういうことも考えられると思いますけれども、まずはその方法で取組を始めたいというふうに考えているところです。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問・要望","question":"早さ、スピーディーなところも重要になってくると思いますので、ぜひ情報共有を。高齢者の包括システムのように、少しずつできていけばいいなと、そこを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１つお聞かせいただきたいのと、あと、そういうところとのここの連携がどういうふうになっていくのかについてもお聞かせほしいと求めました。どういう体制で継続的なサポートまでやっていけるのかということがイメージがつかないのですけれども、そこら辺の具体的なところも説明を求めました。","respondent":"鷹箸保健予防課長","answer":"ここのところを支援するにあたりまして、何十人もこれを支援するということは、今回は前段のこちらの自殺未遂者等支援については。１例でも２例でも取り組んで、その事例を共有するための会議を開いてといったようなイメージを今年度中には考えているところです。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"どういうサポートを受けられるかというふうなところが、本当に悩んでいる方に対してのサポートが行き届くような形で、ぜひ今後とも取組をお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校のほうもどうかということではなくて、そういうことについては、どのようにお考えか。高校は区ではやれないですけれども、万が一何かあったときにはみたいなことが、どのような形で連携していくのかということを説明するよう求めました。","respondent":"鷹箸保健予防課長","answer":"そして教育総合支援センター長も入っておりまして、５月の連休明け、これは教育委員会に以前から取り組んでいただいております。特に先生たちを対象としたゲートキーパー研修も以前から実施しておりまして、８月に実施しておりまして、募集をしているところです。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"賛成をいたしますが、それぞれ要望というか、意見だけ少し述べさせてください。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かれば伺いたいのと、モノクロラミンの消毒というのが、そういう清掃の衛生措置の基準が強くなったと考えていいのでしょうか。施行されてから、その年齢を超えて公衆浴場を利用した場合というのは、注意されたりするということなのか尋ねました。","respondent":"鈴木生活衛生課長","answer":"それから、区内の温泉に関しましては、昨年度末時点での軒数になりますが、区内の温泉利用施設は、８軒です。それから性的な犯罪被害の防止という観点でふさわしいと考えられたものであって、今、全体の流れの中で合わせた改正をすると考えておるものです。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"年齢制限のところは、守られない場合に、公衆浴場が注意するということになるのですか。注意というか、何がされるのかというのをお聞きしたいのですが。","respondent":"鈴木生活衛生課長","answer":"具体的に文言でご説明しますと、規定には具体的な例が、表現が出ていなかったものです。これによって公衆浴場の方に何かの権限が与えられるわけではありませんので、基本的には、注意をいただくということになると考えております。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"第４２号議案のほうの混浴の年齢のところなのですけれども、７歳以上に引き下げることはいいのですが、どのようにお考えか尋ねました。","respondent":"鈴木生活衛生課長","answer":"実は特別区の生活衛生課長会に都から課長がいらっしゃって、説明があったときに、やはり同様の質問が出ました。区の側から直接、強制的にというか、制度的にお願いするということは現在考えていないです。","id":"exchange-033"},{"speaker":"若林委員","kind":"確認","question":"新規の増設、増築等については、修繕も含めて適用するという経過措置です。それを１つお聞きしたいのと、構造物の確認とか、その２点だけ尋ねました。","respondent":"鈴木生活衛生課長","answer":"１点目の、既に設置されているものについては、今度は基準に合うものに換えていただくという形になります。実際に設備の設置をする前に、この規定に沿ったものを設置してくださいというような指導をする形になりますので、こちらについても。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、今まで愛成会で働かれていた方というのは、運営事業者が変わることで、皆さんがほかへ行ってしまうということなのでしょうか。そこを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"その辺りも十分配慮いたしまして、現指定管理者、それから次期指定管理者が一緒になりまして、引継ぎを丁寧に行っていく予定です。いずれにしましても、ご利用者が安心して継続してサービスを利用できるような体制ということで、引継ぎを行う予定です。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"これがどういうことなのかというのを見極めながら、安定しているのかというのを、一人ひとり考えて研究しているという姿勢があるわけです。運営事業者そのものの姿勢や理念等も違ってきますので、そこは完全に保証できるとはならないと思うのですけれども、そこはいかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"集団のプログラムの中で取り組める方は取り組んでいますし、その人その人に合わせた支援が現在も行われているところです。そのように個々の一人ひとりに寄り添った支援が行われており、福栄会におきましても、同様に障害者一人ひとりに寄り添った支援が行われているです。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったことをどのように考えられているのでしょうか。ですので、継続を望まれているし、再考を強く求められていると思うのですけれども、そこはどのようにお考えか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"同じ説明になってしまうかもしれないのですが、個別性を重視した利用者中心の支援が共に行われているということで認識をしております。次期指定管理者になった際も、同様にサービスを継続していくです。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に当事者、そして、家族だからこその言葉だと私は思いました。そこをどう保障できるのかというのをしっかりと示してほしいと求めましたし、そういうやり方を、区としてはそこをお考えか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"その中で、個々のご利用者様の具体的な支援ですとか、支援方針というものも引き継いでいきます。そうした中で、利用者がどのようなことを望んでいるのか、どういう思いがあるのか、そういったことも含めまして引き継いで丁寧に行ってまいります。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どういうことに困られていて、どういうことを求めていてという、今からでも改めて再び考え直すということをしてほしいと求めました。そこの現状を教えていただきたいのですが。","respondent":"築山障害者施策推進担当課長","answer":"１点目ですけれども、障害児者総合支援施設の設置目的である、取り組んでまいります。現状ですが、児童担当の医師のみとなっておりますけれども、大人の再診については受けているということを聞いております。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"それは、非常勤の先生がいらしているということなのでしょうか。それとも、障害児担当の先生が一緒に診られているということなのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"１点目のご質問ですけれども、現指定管理者も次期指定管理者も、同様に利用者に寄り添った支援が行われているという認識をしております。支援といたしましては、両方とも利用者に寄り添った支援が行われているという認識です。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"日精看のほう、区として望ましい体制として、院長は障害児が担当だということをお聞きしていますし、そうしたら、やはり大人の担当の先生も必要だと区は考えているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"日精看の部分でいいますと、上の児童学園の部分の連携というところで、協力をしてもらっているところです。診療等につきましては、これは日精看の判断で職員の配置等をされているものと認識しております。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"区としては、ニーズに合った良質なサービスという、そのニーズというのをどのように考えられているのか。大人の担当の医者も必要だと考えている、それがニーズと捉えているのか、そこを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"区の支援というところでいきますと、日精看が運営するにあたって、区のほうも補助という形で支援をしております。精神障害の方の、福祉的な視点での通いの場というのも不足している部分がありますので、拡充していく必要があると考えています。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"デイケアのところというのは、やはり日精看の部分でのニーズというのを、もっと把握していく必要があるのではないかと私は思うのです。訪問看護、当事者と協議する場をつくって良質なサービスをつくっていく必要があると私も思うのですけれども、そこら辺はどのようにお考えか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"どのような施策が必要なのかを考えていっているところですので、障害者団体の方を交えて、そういったご意見を聞きながら進めていきたいと考えております。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１つ伺いたいのが、日精看なのですけれども、同じグループの中で日精看も誘われて来たという経過があったと思うのです。グローとゆうゆうと愛成会が福栄会に、今までどおり残って支援を続けていくということになるのか、その点についてお聞かせほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"現在、行政財産の使用許可ということで、日精看にお貸ししています。それを受けて区が許可をするかどうか判断をするということで、１年単位で行っておりますので、日精看の経営判断もあることなのかと考えております。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"日精看がまた１年ごとの契約という形でしていくということで、３つのグループが福栄会に変わることによって、そういう方向性というのは全く決まっていないということなのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"日精看の事業は、指定管理とは別ですので、今回のプロポーザルとは関係はございません。継続するかどうかにつきましては、日精看の経営判断によるものなのかと捉えております。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この違いという点については、区としてはどう捉えられているのでしょうか。そのことが私は問われていると思うのですけれども、その点についてはどう考えられているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"受けている利用者の人数、職員の配置体制が違うというように、条件が異なった中でのアンケート結果なのかという認識です。最初からご説明していますとおり、利用者に寄り添った支援、両者共に利用者中心に取り組まれているという認識です。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうことで考えられているということでしょうか。体制上の問題が普通に表れたと考えられているということか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"支援につきましては、同じ説明になりますけれども、支援の考え方は共に利用者中心の考えになっておりますので。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"同じ体制であれば、同じような形で、例えば、今のぐるっぽの体制で福栄会が同じような形でやれば、今のぐるっぽの質は担保できると考えているのかということなのですけれども、この点はいかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"今の愛成会の体制は、立ち上げ期ということで、定員に応じた職員配置をしております。福栄会になった場合も、同様に定員に応じた職員配置になりますので、体制は適正な配置で実施をしていくことになります。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私も具体的にこの陳情を出された方から伺ったのですけれども、一番初めにサービスを受けるときも、書類がとても膨大だとおっしゃっていました。質をどう担保していくのか、これだけ満足度が違うということが歴然と出てきたわけですから、その点ではいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"寄り添った支援というのは、また、指導していく。当然ながら必要な方に対して、必要なサービスをしていくということは、区としてはお願いしています。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"やはり区としてもしっかりと受け止めて、そういう中身をどうつくっていくかというところに向き合うことが本当に大事だと私は思います。この３者がそういう形で期待に応える中身をやっていただいていると思うのですけれども、そういう形で、そういう選択肢としてはいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"生活介護につきましては、また特別支援学校の卒業生の動向を見ながら、今後、つくっていく形になろうかと思います。その際につきましては、やはり公募という形を取らざるを得ないかと考えております。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、やはり現在の指定管理者をぜひ継続、これだけ当事者の方たちが継続を求めているわけですから、継続をすべきだということで、指定管理者そのものに対しても反対をしましたけれども、改めてこういう陳情が次々と上がってくる中で、ぜひ再考していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、委員長からのお話でありましたが、理由は陳情第２５号、２９号、３４号、一括してお話をさせてほしいと求めました。第２５号については、不採択でありますけれども、理由としては……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"石田（秀）委員","kind":"意見","question":"それで、結果として３年の指定管理となったということであります。あれでありますけれども、個々のものについては、我々としては不採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"現３事業所の評価は確認をしておりますが、既に議決もされたという経緯の中で、今回の陳情者の方にお話を伺いました。実際に１０月からはすばらしい見事なサービスの質の現状、また、事業所へのご指導をしっかりお願いしたいということは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"せお委員","kind":"質問・要望","question":"先ほど説明会を利用者に実施するということも伺いましたし、その中で、まず説明会ではしっかりと丁寧な説明をしていただきたいと思っています。やはりこれだけ声が上がるということは、ここの現場にいる職員にできるだけ残っていただく努力を必ずしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"変わらないでほしい、残してほしいという。引き続き、丁寧な説明等だけではなくて、やはり担保できる体制を取っていくことが必要だと思いますので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問","question":"結論を出すで、不採択でお願いします。サービスの継続に関して安心して利用できるように、個性や特性を重視されるということをご説明で伺いましたので、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１２年間福栄会に通われた、昨年からぐるっぽに通ったという経験が、本当に全てを語られているという思いがしています。当事者の思い、願いを最優先に、改めて今からでも考え直してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"結論を出すで、採択でお願いします。さらなる支援を区がしていくべきだと思いますし、この陳情にあるように、良質なサービスをつくっていくことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして、「入浴設備のあるシルバーセンターをつくってほしい」というのが５７％というところでは、一足早く造ってほしいという思いだと思います。生きがいづくりというのを支援する場があっていいのではないかと、余計に私は思うのですけれども、そこら辺はどのようにお考えか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"前回、規模等も考えたときに、既存の施設が他地区に比べて決して不足している状況ではないのかというところでご説明はさせてもらっております。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりシルバーセンターの設備というのはないわけですから、備品がないわけですから、実施が必要ではないかと思うのです。それが今はこれだけの高齢化が進む地域になっているというところでは、もう検討を始めていいのではないかと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"先ほどもご説明させていただきましたが、こういった高齢者に特化したシルバーセンターというのはなかなか検討するのが難しいかというところです。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういうソフトの面も必要だと思うのですけれども、やはり高齢者が優先されるというのですか、ゆうゆうプラザもそうですよね。対策というのも、ほかの地区ではそうなっているわけですから、そういう通いの場なんかも確保するということが前提で進んでいるわけですから。","respondent":"菅野高齢者地域支援課長","answer":"例えば、いろいろな場所もあれば、そこはゆうゆうプラザ等を前提とした施策ではないということでご説明をさせていただきたいと思います。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"では、ソフトの面からという通いの場、身近な地域の皆さんでというのは、八潮は大きく進んでいる状況なのでしょうか。そしてまた、さらにもっともっと取り組んでいくという状況なのか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"こちらは昨年度から取り組んでおりまして、リハビリテーションの専門職の方とともに通いの場の条件整備等をして、地域の方に働きかけていく施策です。こちらがいかんせん、住民主体のものなので、こちらとしては働きかけを頑張っていくという次第になります。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区の施設の改修計画のときというのは、どんなときになるのか。老朽化したものを改修するということになると思うのですけれども、おおよそいつ頃みたいなことは、分かっていたら教えていただきたい。","respondent":"菅野高齢者地域支援課長","answer":"八潮地区における他の施設の改修計画というところなのですが、改修の計画というのは区全体で立てるものなので、こちらの所管として、この施設が何年頃にということは、今、この段階ではお話はできないというところです。","id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"質問","question":"当時１万４,０００人弱の人口だったけれども、行政の部分も相当入れ込んできて、大変ご苦労いただいてきているところがあるということです。整備できることは整備していこうというお答えは、まさに私はそのとおりだと考えていますので、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この「会」の皆さん、また、高齢者の皆さんの声だと思います。それも含めて、生きがいづくりとして使えるシルバーセンターまたはゆうゆうプラザというものを造っていくという検討を始めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3600#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":63386,"voices":231}},{"id":"r03-20210706-8","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"建設委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"審議の支障がない程度で、動画撮影、頭撮り以外でも認めるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"この事故が起こった原因を分析して、再発防止に力を尽くしてほしいと求めました。その原因と再発防止について伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"運転手のほうが１つ先の信号の右折、前方の車両のほう見ることができなく、そのときに追突したというものです。今後、このような事故を検証しまして、再発防止に向けて指導徹底のほう行っていきたいと考えております。","id":"exchange-002"}]},{"id":"topic-02","title":"第４３号議案、品川区立環境学習交流施設条例","agenda":"第４３号議案、品川区立環境学習交流施設条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そして、今回この施設、指定管理者制度を活用するということなのですが、なぜそれを活用しようと考えたのか、その理由を伺いたいと思います。区の直営の施設としてもできるのではないかと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"今回これを設置するに当たりまして、緑豊かな公園内において設置を進めするという点で、講座などを通じまして広めてまいりたいという考えです。まずは１つ目の理由、優先順位として１年を通じて利用できることということで、それに伴って配置を変更したというようなところです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"確認","question":"変更点については、遊具とじゃぶじゃぶ池以外にはないということでいいのかというところを確認します。","respondent":"河内環境課長","answer":"全体的に温室効果化ガスの対応など、急速充電器の設置につきまして変更といたしました。トイレの中のユニバーサルベッドなど、そういった障害者の方への対応につきまして、転回スペースなどを見つめ直したという点が大きな変更点です。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこはしっかりと受け止めていただいて、住民の皆さんに説明をしていってほしいと求めましたが、いかがか尋ねました。","respondent":"河内環境課長","answer":"周辺環境などの配慮、いろいろな面で進めているところですが、理解促進へ向けまして、しっかりと周知をしていきたいというふうに考えております。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかりと説明をしていってほしいと求めましたし、あとこの施設はやはり公園内ということで、公園の雰囲気を壊さないように、なじむようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"そもそも論から入りたいのですけれども、この環境学習交流施設というものは、いつ頃にどのような観点で出てきたものなのかをまず確認したいのです。というのは、根拠のようなものがあるのかどうか、それで品川区の位置づけというものはどのような位置づけで進めようとしているのか説明を求めました。","respondent":"河内環境課長","answer":"先ほどご説明したとおりで、私は財務が得意など、こういった実際的にリアルに交流される施設についての建設が計画されたというようなところです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"ですから、もうこの施設、要はそのような施設をつくることによっての効果ということを期待できるものの、非常に難しいだろうと思っています。地域の方のご意見もあったということですから、ではリピートできないといけないということがあるので、それと目的がいろいろあると思うのです。","respondent":"河内環境課長","answer":"この設置される館と、その授業の中で振り返り、自分で考えるというようなことを進める予定です。もちろん環境講座の中でフードドライブなども積極的に取り上げる予定でおりますけれども、環境に関係するような食とともに、今進めているところです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"今のなのでしょうか、あそこに行くとおいしいものが買えるとか、だから物販もぜひ考えていただきたいのです。結構皆さん興味を持ってくれるのかなと思うので、ぜひ開発してほしいと思うのですけれども、いかがか尋ねました。","respondent":"河内環境課長","answer":"このように苦労をして育てて作っているのだという点は触れる予定ではありますが、工夫をしながら検討を重ねていければと考えています。今後の研究材料とさせていただきながら、そういったアプローチもあろうかというところで、今後検討させていただければという考えでおります。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"ですから、指定管理者制度を導入するということなのですけれども、広い考え方というか、広い発想の方々にお願いしたいと思います。そこはあまりやってはいけないなどではなくて、ぜひリピーターということで、継続できるようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"それともう１点なのですが、環境施設なので、やはり環境に配慮した施設であるべきだと思うのです。ＣＯ２を削減するお手本になるような施設であるべきだと思うので、何か工夫などを施してあるのか、その点を説明するよう求めました。","respondent":"河内環境課長","answer":"８月の発表に向けまして、進めてまいりたいというところで、現在進行中のところです。この条例がきちんと決まって、正式名称が決まった後の発表という段取りで計画を考えているところですので、よろしくお願いいたします。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問","question":"もう１点質問いたします。体験するのに農作物を耕す、それと同じような考えで、品川の風土というものをどこまで活かせるのかと、その点を説明するよう求めました。","respondent":"河内環境課長","answer":"ご案内のとおり、大都市圏に属している中での自然環境や、環境に対する答えをいろいろ出していく必要があるかというふうに認識しております。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の資料を見ても取り入れていらっしゃるということは十分確認できますが、このＳＤＧｓという理念に沿ったいろいろなプログラムというのですか。連携、今後ＳＤＧｓということをこの環境館の中でどのように位置づけ、運営をしていくのかということでの見解を最初にお伺いしたいと思います。","respondent":"河内環境課長","answer":"今回私どものコンテンツの中では、これがどこに当たるのかなども併記しながら進めるという点を非常に注意しながら進めているところです。現在進めているプログラムですが、これがＳＤＧｓのここに当たるのだというようなところで進めるということで、現在やっているところです。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ指定管理者を選定するに当たって、そういった観点を十分に考慮しながら進めてほしいと求めました。これが十分でないと、その台数がどれぐらいかと、その台数はどのような根拠でその台数とされたのかというところを確認したいと求めました。","respondent":"河内環境課長","answer":"現在設定されているのが、４０台収納可能です。瞬間的に、時間ごとにきちんと対応できる台数というところを見込みながら、４０台という台数を設定したものです。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問・要望","question":"４０台で、これだと経験値的に大丈夫だというところなのですか。地域センターなどのところで経験値的に、これぐらいあれば、もう一歩踏み込んで確認させてほしいと求めました。","respondent":"河内環境課長","answer":"今後利用実態が増えるか減るかなどの傾向をとらえまして、近隣の駐輪場の協力などといったものも考慮しながら進めたいというふうに考えてはあります。今後不足が生じないように、運用なども併せていろいろ進めてまいりたいというふうに考えているところです。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いしたいと思います。もしくは、今、環境保全活動や地域活動というところをどのぐらいのレベル感で捉えているのかというところを少し教えてほしいと求めました。","respondent":"河内環境課長","answer":"支援、また予約などもなかなかできかねる、難しい状況であると聞いております。例えば環境団体につきましては２０団体程度行いたいと思っており、そういったものを広げていくといったところのレベル感でと考えています。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"なるべく幅広くというか、ハードルを下げて、最初はやはりスタートしていくということなので、それはぜひお願いしたいと思います。キャッシュレス等の対応、ぜひ電子決済等を行っていけるようにということも、最後に１つ確認させてほしいと求めました。","respondent":"河内環境課長","answer":"現状ですが、現在、現金取扱いということでスタートしていく。そういった需要の高まりなどを受けまして、きちんとそういったものの整備を視野に、今後も運営を進めてまいりたいというふうに考えているところです。","id":"exchange-017"},{"speaker":"芹澤委員","kind":"提案","question":"図面のどこにあるのでしょうかということが１点と、ＺＥＢで５０％削減、エネルギーの創出がどれぐらいでということを教えてほしいと求めました。周辺の自治体、この２３区の中で環境に特化した、このような施設というものはどれぐらいあるのか尋ねました。","respondent":"河内環境課長","answer":"時間軸で環境を捉える体験型展示などで年間３万人程度の来場者を見込むということで計画をスタートしておりますが。展示物や啓発、方向性などが似通っているというところもございまして、参考にしながら進めたところです。","id":"exchange-018"},{"speaker":"大沢副委員長","kind":"意見","question":"簡潔に。担当としてどのような認識を持ち、どのような評価をされて、ここへ導入をされたのかを聞かせてくださいとの意見を述べました。","respondent":"河内環境課長","answer":"丹青社の認識です。未来に向かってというところを残すためには、こういった取組も必要かというところを評価いたしまして、丹青社として進めたという経緯です。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"賛成です。近隣住民にしっかりと話をして、理解してもらうように力を尽くしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"第３６号議案、令和３年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３６号議案、令和３年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"区の職員ということなのですが、いつ、どのような条件のときに使うのか、それとも常にこのようなことというのはあるのですか。例えばここのエリアは見ましょうとか、何かそのような計画があって使うということなのか、どのような条件なのか尋ねました。","respondent":"河内環境課長","answer":"改修あるいは解体する事業者の方から、この現場につきましては疑わしいが、例えばアスベストはないと断言してくることもあります。対策上、どの程度の危険認識度があるのかという点をやはり現場で確認する必要がありますので、こういったものを効果的に使いながらという点で。","id":"exchange-021"},{"speaker":"西本委員","kind":"確認","question":"どのようなきっかけ、例えば建築確認か何かあって、そこで解体も含めて申請があるということで、そこでリンクするのか、それとも事業者の方々が何かありそうですなどというものがあって、それで申込みがあって、職員の人が行って確認して、それで指導するという形なのか。","respondent":"河内環境課長","answer":"それから、事業者の方で解体や改修をご予定されている方が、直接窓口にお見えになります。そういったところの現場をきっかけにして、こういったものを使っていくというようなところです。","id":"exchange-022"}]},{"id":"topic-04","title":"令和３年陳情第２１号、区民住宅の住替えに関する陳情","agenda":"令和３年陳情第２１号、区民住宅の住替えに関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"こうした要望が出てきた下で、柔軟な対応が必要なのではないかと思うのですが、申し込めない理由は何か伺いたいと思います。陳情の中に、区はこうした方が区外へ転出をしてもよいと考えているのか伺います。","respondent":"竹田住宅課長","answer":"それから交換ということですが、交換には今回は該当しないというふうに考えております。品川区に長く住み続けていただきたいと考えておりますので、別の形でご支援できればというふうに考えているところです。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"お子さんが育って手狭になってきたという理由であっても、住宅交換で合意すればできるということを確認させてほしいと求めました。それと住み続けたいというところで、ほかのことで対応したいということですが、どのような対応をされるのか伺います。","respondent":"竹田住宅課長","answer":"基本的に公共住宅の方針というものは、ほかの自治体も似たような、品川区の公共住宅の考え方としては現在ご説明した内容で進めていきたいと思います。陳情者の方とは具体的にお話ししながら、どのような支援ができるのかというように考えていきたいと考えています。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこうした要望が実際に住民から出てきていますので、柔軟な対応をしていくべきだと思います。区はほかの対応でということですが、この住替えも含めて、ぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"西本委員","kind":"確認","question":"ここの場所は、具体的に間取りというものはどのぐらいなのでしょうか。大体何でしょうか、一般的な話でいいのですが、どのぐらいになっているのか尋ねました。","respondent":"竹田住宅課長","answer":"今回陳情された方の間取りですが、２ＬＤＫの６３.１２m2のお部屋です。それから家賃の考え方ですけれども、一昨年に見直しを行って、一部賃料のほうを下げさせていただいたところです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"家賃を下げたということですか。でも品川区の中だと普通なのかなと思うのですけれども、その辺は一般的にどうなのか尋ねました。","respondent":"竹田住宅課長","answer":"２年ほど前に近郊の家賃相場のほうを調査しまして、近郊よりも一部高くなっている部分については、少し下げさせていただいたところです。それから、今回の陳情者がお住まいの区民住宅の場合、２ＬＤＫですと大体１１万７,８００円から１４万５,７００円ほどになってあります。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"ですから、住宅事情はこの方だけではなくて、品川区に住む以上は問題が多いと思うのです。お気持ちは非常に分からないではないのですが、いろいろな配慮が必要かと思いますが、お願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"この住まいということは本当に生活していく上で基本中の基本なので、大変に大きい選択、判断というものを求められるところだと思います。よりよい姿というものを検討していただきたいとは思いますけれども、この個々の陳情については、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"大沢副委員長","kind":"質問","question":"要綱には該当しないということ、あと税により成り立っている公の住宅において、ほかにも様々な恩恵を被っている部分もある。ほかにおいてやはり公平性を害する、混乱を生じるという危険性もありますので、これについては承服できないので不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。やはり入居時に小さかったお子さんが大きくなって手狭になるということは、生活している上であることですので、もっともだと思いますので採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいということと、不採択でお願いします。申し訳ないのですが、気持ちは分かりますけれども、今回は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"この４件の陳情はそれぞれの方が自分の思い入れで出していますので、一括ではなく、一つ一つ審査してほしいと求めました。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"効率的なということはコロナ禍ではあるかもしれませんが、やはりその中でも陳情を出してきていただいていますので、一つ一つ審査をしていただきたいと思うので、ぜひ各委員の意見も聞いていただいて、採決をしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"第３１号についてなのですが、これは大井町で生まれ育った方が出されたものです。ここに心の叫びを聞いてほしいということも書かれておりますが、区はこうした声を聞き、反映すべきだと考えますけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"今ちょっとご説明させていただきましたが、建物をお持ちの方々が、それをどのように変えていくかということを話し合っていただいているところです。やはりまずはお聞きしながら一緒に考えていくということが、区としても取り組んでいくことだというふうに認識しています。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"１項目めでは、再開発を望んでいるかどうかということを調査してほしいということで、区はこの住民の意向を調査したことというのはあるのか伺います。基本的人権が脅かされるということで、区は再開発で地権者や住民の基本的人権は守られていると考えているのか伺います。","respondent":"多並都市開発課長","answer":"予算につきましても今のお答えと一緒で、またその状況を見ながらということになるのですけれども、現時点ではまだ決まっていないというところです。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"今は住民で考える、勉強している段階だというお話ですけれども、そうした中で再開発をやりたい人、やってほしくない人がいるわけです。実際にどうなのかということを区として調査してほしいということですから、そこの合意形成を図っていくためにも、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"それをやるかやらないかの調査ではなくて、まずは今の土地、建物をお持ちの方々がどのような考え方で今皆さんが思っていらっしゃるかと。もしお尋ねがあれば、そのようにいろいろ、皆さんのお話が進むような形では今後支援していきたいと思っているところです。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"そういった調査はしないということですか。必要に応じて調査するということでしたので、どのような状況になったら調査をするということなのか尋ねました。","respondent":"多並都市開発課長","answer":"いわゆる検討のお話をいただいている状況、その中で、どう進めていけばいいかということでかなりお困りになることもあるかと思います。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"修復型のまちづくりは私も主張してきたことですので、そうした考えを持つべきだと思いますけれども、いかがでしょうか。伺います。","respondent":"多並都市開発課長","answer":"答えの１つに修復型はもちろんありますけれども、１つにしていくということですか、区としては支援していきたいと思います。直していくような、それを１人ではなくて皆さんで考えて進めて改善していくという方法をご提示しながら、区としては思うところです。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"古きよき街並みというのでしょうか、そういった危険性というのですか、ぜひそうした方向で進めてほしいと求めました。伺います。","respondent":"多並都市開発課長","answer":"まずは今あるまちの課題、それをどうしていくかということで、一番いい方向に皆でそれを改善していく方法を考えていこうと。やはり区としては一番重要だと思っていまして、そのお話し合いが円滑に進むように支援することが区の役割ということで、そのような形で。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"これ全部、４つに関しては不安なのです。どの陳情も不安から来ているものだと私は思うので、その辺の交通整理はある程度示すこともできるのではないかと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"今の段階的なまちづくりの進め方という点ですけれども、まず区のまちづくり方針の中でも、今回大井町にも書かせていただいております。方針の説明会や、今委員からお話があったようなご心配事があるということで、やはりそこが一番重要な点かなと。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"その特徴をどう活かしていったらいいの、今回も４つの陳情が出ているわけなのですけれども、まちづくりというのは夢のある話だから。そのようになってしまっていると思うので、そうならないような状況にしてあげられるといいのかなと思うのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"今おっしゃったように、夢という言い方はあれですけれども、建て替えて、皆さんで大きく建て替えようという思いの方もいらっしゃいます。","id":"exchange-042"},{"speaker":"芹澤委員","kind":"質問・要望","question":"どこの意見を推進しているというような誤解をまず区が持たれないようにしていただきたいということは、引き続きこれはお願いをしたいと思います。区がどうしても再開発をさせるというようなものではないと理解をしていますので、採択ということは難しいかなという思いで不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"区の見解もありましたとおり、肩入れするなどということでもなく、支援をしていくという姿勢に徹していっていただきたいということが思いであります。やはり一切手をつけないでほしいという、ここに今の段階で、これについては不採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"大沢副委員長","kind":"意見","question":"地域の方たちが話し合って解決するべきものと考えますので、議会の介入、先ほども申し上げましたように不適切であると考えます。以上によりまして、これは不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"のだて委員","kind":"意見","question":"調査をすることは重要ですし、コロナ禍の下で再開発の予算をコロナ対策に使うということは我が党も主張してきました。基本的人権に配慮してほしい、地域のつながりを壊さないでほしいということはもっともなことですので、採択したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、趣旨採択でお願いしたいと思います。今回出された４つの方々に関しましては、その不安なお気持ちだけは私はしっかり受け止めさせてほしいと求めましたので、趣旨採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"塚本委員","kind":"意見","question":"本日結論を出すで、結論は不採択です。理由は先ほどと同じで、現時点で議会としての一定の方向性なり何なりというものを示すべきものではないですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"結論を出す、不採択でお願いいたします。これは後の第３２号、第３３号にも関係してまいりますが、第３０号で述べた理由により不採択としてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。私も求めてきた修復型のまちづくりをしてほしいということと、生活基盤を奪うＣ地区の開発をやめてほしいというものですので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。やはり当たり前の願いであり、それを脅かすのがＣ地区の再開発をやめてほしいということですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"}]},{"id":"topic-05","title":"および(5)の陳情２件につきまして、関連する内容のため、一括して議題に供します。 進め方といたしましては、２件の陳情","agenda":"および(5)の陳情２件につきまして、関連する内容のため、一括して議題に供します。 進め方といたしましては、２件の陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"陳情第２０号のところで、この陳情は、国側の騒音軽減策として出した３.４５°の着陸降下角、飛んでいる便数を明らかにしてほしいというものです。実態を明らかにすることは重要だと思いますので、ぜひこの機数を明らかにしていただきたいと思うのですが、区としては問合せなどはしたのか尋ねました。","respondent":"鈴木都市計画課長","answer":"区の考え方としましては、その声については、全て国に届けてあります。区としてはほかの声と同様に、国のほうにしっかり届けて、その辺の数字を示していただくように求めていきたいというところは考えとしてはあります。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"ここに設置すればできると思うのですけれども、区の考えを伺いたいのと、実際にこの東大井集会所では飛行機の高度は何ｍなのか伺います。ここに設置を検討したことというのはあるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"こちらの集会所での測定局の設置の検討状況についてですが、ルート直下、これは基本的に国の環境省のマニュアルに基づいていろいろ検討をしています。いろいろ検討もしましたが、大がかりなクレーンでの設置ということと、やはり設置場所の施設については。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり直下のところで測ってほしいというのは住民の願いだと思いますので、そこは東大井区民集会所でもぜひ設置をしてほしいと求めました。そういったこともあるので、ぜひこの東大井集会所にもつけていただきたいと思うのですがいかがでしょう。","respondent":"鈴木都市計画課長","answer":"同じ近傍に立会小学校という設置に適したところがございましたので、そこと同じような位置にある、総合的な判断をしたと。設置の容易性ですとか定期点検の容易性ですとか、これからこの集会室のほうに立会小学校にプラスして設置するという考えは区としてはございません。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として今、考えはないということですが、やはりこうした騒音測定器、多くつければ住民の実際の被害実態、より細かく分かると思いますので、実際にここに設置してほしいという陳情も出されているわけですから、ぜひ設置するようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"芹澤委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。ある程度データももう品川区のほうで把握されていらっしゃるということですので、わざわざ問い合わせるほどでもないのかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"塚本委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。今、それに応じて今後も適切に対応していただくということがあるということで、この陳情については不採択ということでお願いをいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"区の意見、議会の意思も十分に伝えられていると思いますので、ここから新たな議会からの発信は必要ないと思います。以上によって、不採択としてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すということで、採択をお願いします。できるだけ情報は収集してということで、こう思うのは当たり前なのではないかなと思いますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。そのポイントの選定も今、総合的に判断してというお話がありましたので、さらに追加でというのは必要ないかと理解をしていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"どこに設置するかということについては、個々にここに設置してほしいという思いはそれぞれいろいろな方々がお持ちかとは思いますけれども。適切な場所に設置していただくということでお願いをしたいと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"本日結論を出していただいて、不採択でお願いします。住民の方たちのお考えも分かりますけれども、一つ一つ要望として受け入れることは不可能であると考えますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで採択を主張します。やはり、より住民の被害実態を明らかにするということで、騒音測定器を設置していくべきだと思いますので、採択しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、採択でお願いします。ポンプ所のところは中間地点ということもあって、もちろん要望どおりに全部設置するのは不可能なことではあるのですけれども、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-06","title":"令和３年陳情第２７号、品川道踏切にエレベーターの設置を希望する陳情","agenda":"令和３年陳情第２７号、品川道踏切にエレベーターの設置を希望する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"陳情にもありますけれども、開かずの踏切としてよく知られているということですが、遮断時間というのが分かりましたら教えてほしいと求めました。こうした区民への支援が必要だと思うのですけれども、いかがか尋ねました。","respondent":"溝口道路課長","answer":"１日のうちの約５時間閉鎖しているというのが、今、踏切の遮断時間という状況になっているものです。高齢者の方、そういった方はそちらを使っていただいて東西に渡っていただく、そういった形でのサービスを考えているところです。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"遮断時間が５時間にわたり４０分以上あるということで、ぜひスペース確保していく方法を考えていただきたい、検討してほしいと求めました。いかがでしょう。","respondent":"溝口道路課長","answer":"これまでも当踏切、当歩道橋にエレベーターを設置というお話はいただいてきているところです。さまざま検討しながら進めていきたいですので、エレベーターを設置していったらいいのか、併せて検討していきたいと考えているところです。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＪＲとも協議していただいて、設置できるように力を尽くしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"少しは危険性を回避できるのかなという思いがあって、ここの歩道橋の持ち物、それから管理というのは品川なのでしょうか。ＪＲも関わってくるとなると、ＪＲがやるとは思えない部分があるのですけれども、管理者というか、権限はどちらにあるんでしょう。","respondent":"溝口道路課長","answer":"大井町歩道橋の管理につきましては、品川区の道路課のほうで維持管理をさせていただいている橋梁です。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"であるならば、具体的に考えていただかないといけないなと。自転車のほうもスロープをつけてここを通れるようになってくると、かなり滞留が少なくなるのではないかなと思うのですが、いかがか尋ねました。","respondent":"溝口道路課長","answer":"一番はやはり東側のところ、すぐに道路と接するような状況になるので、なかなか階段を延長するというのが難しい状況になっているところです。エレベーターを設置し、また、それが一番現実的というふうに考えているところです。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ工夫もかなり厳しいなという自覚はあるのですが、いろいろと技術もこれから発展するかと思うので、ぜひ検討をしていただきたいなと思います。そして喫煙所、それを全部総合的に考えてほしいと求めましたが、いかがか尋ねました。","respondent":"溝口道路課長","answer":"すみません。１００年、よりよい形にしていくというのが大事だと考えていますので、そういったものを併せて検討していきたいと考えているところです。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"１点教えてほしいのですけれども、この歩道橋にかかる東海道線と京浜東北線、このダイヤですね。これだけしまっているよというお話は伺ったのですけれども、うまく時間帯をそろえて、何かそういうことというのはある程度できるものなのか尋ねました。","respondent":"溝口道路課長","answer":"最近の調査では４４分に変わっている、ダイヤ改正等をしながら、工夫しながらやってきていただいているという実情はあるのだとは思っております。そういった要望ですとか、打ち合わせ、そういったものは適宜行っていきたいと考えているところです。","id":"exchange-071"},{"speaker":"芹澤委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。再開発とか、そういうところも広い視野でご検討いただきたいという思いを含めて、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"できることならつけたいということもよく分かりました。さらに何とか強く要望するというところについては、やはりやや無理があるかなと感じておりますので、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"大沢副委員長","kind":"質問","question":"しかしながら、今後のまちづくりの中で、可能であれば検討していくというようなご答弁もいただきました。ここのところのエレベーターを設置ということの断言については、願意に沿うことはできないと思いますので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。区議会としても後押しをしていくということが必要だと思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問・要望","question":"ここは非常に危なくて、皆さんからの何とかしてほしいという要望はたくさんいただいております。なので、可能なことがあるならばチャレンジをしていただきたいなと思っていますので、ご検討のほど、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-07","title":"令和３年陳情第２６号、しながわ区民公園北側ゾーン改修計画に関する陳情","agenda":"令和３年陳情第２６号、しながわ区民公園北側ゾーン改修計画に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"こうした細かな声を区としては聞いているかどうか、伺いたいと思います。利用者へのアンケート調査あるいは説明会を要望しますということでなっておりますが、アンケートなどを行ってほしいと、いかがか尋ねました。","respondent":"高梨公園課長","answer":"例えばパラソルの設置であったりとかという形で、日陰の設置についてはソフト面を含めて対応を進めていきたいというふうに考えているところです。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"完成形が３０年後だと、その樹木が育ってきたというのが結局３０年後にしか完成にならないと。３０年経つと、完成した姿が短過ぎるというのですか、具体的に３０年後を見据えた更新としている部分がありましたら伺いたいと思います。","respondent":"高梨公園課長","answer":"公園としての機能、防災に対応する再整備というような部分で、どうしても園路を広げる関係で木を切らなければいけないといったようなこともあります。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"３０年後を目指してと、より理解を得ていくということが必要だと思いますので、そこをぜひやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"本多委員","kind":"質問・要望","question":"教えていただきたいのですけれども、事前に日頃の樹木の管理がどうなっているのか教えていただきたいのですけれども、そういう管理はどうなっているのか説明を求めました。","respondent":"高梨公園課長","answer":"どうしても、見た目では健全のように見えるのですけれども、風等で倒木してしまうというようなことがあります。特に今回はそういった年数が経っている木を中心に、また樹勢の弱っているところ等を見ながら伐採等をしていく、そのような計画としています。","id":"exchange-080"},{"speaker":"本多委員","kind":"質問・要望","question":"これからの公園のあり方ということで、防災機能も向上させていくということですから、点検もしっかりしてほしいと求めました。万人に共通することだと思いますので、その点、改めて教えてほしいと求めました。","respondent":"高梨公園課長","answer":"それをまた真摯に皆さんにご説明をして、一定の方向をしっかりと示していくといったことが区に求められているところだと思います。これからもしっかりと説明をし、ご理解を得ていきたい、このように考えているところです。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"今期初めてなのかと思うのですが、その際のときにもいろいろ、若干こういう意見が出ましたという報告があったと思うのです。結構強めの要望があるのだなというのは私は認識があまりなかったので、実際、その説明会のときにはどんな感じだったのかをお願いしていいか尋ねました。","respondent":"高梨公園課長","answer":"１枚目の右下のほうに、説明会の主な意見と回答ということでお示しをさせていただいているところですが、やはり一番多かったのが。説明会の中では、今回、北側では切らないでほしいといったようなご意見が多かったといったところです。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"もう一つ質問としては、２回アンケートをしたというのは、何かそういう要望があったからですか。もうちょっと詳しく調べてみたいとかと、何かあって２回されたのか尋ねました。","respondent":"高梨公園課長","answer":"所管といたしましても、真摯に向き合ってまいりたいというふうに考えているところです。そのまま説明会で決定というのではちょっと乱暴であろうということで、その賛否についてご意見を伺おうとして第二回アンケートを実施したところです。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"１回で終わってしまうのだろうと思うのですけれども、２回された。全部の要望にお応えできればいいのでしょうが、そこはご理解を求めていくしかないのかなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"大沢副委員長","kind":"意見","question":"陳情する権利というのはしっかりと担保されなければいけないし、ある意味、表現というのも自由をしっかりと尊重されなければいけない。サッカー場は要りません、北口を２つにする必要はありません、これについてどういうふうにお考えになりますかとの意見を述べました。","respondent":"高梨公園課長","answer":"あらゆる状況で役に立つ公園であるべきだというふうに考えてありますので、あと災害車両の出入口である北口の設置、区民公園であるためには必要な改修であるというふうに考えているところです。","id":"exchange-085"},{"speaker":"大沢副委員長","kind":"意見","question":"それともう１点、高齢者の心と体を健康に保つための公園にシフトすべきと、いろいろな公園があろうかと思います。もう既に年齢層、種類によって公園事業は区のほうで行われているということで私は認識をしておりますけれども、それで間違いないですねとの意見を述べました。","respondent":"高梨公園課長","answer":"位置づけとしては区内の区民の方が皆さんでお使いいただく公園というふうに考えてありますので、また幅広い用途で使っていただく公園であるべき、このように考えているところです。","id":"exchange-086"},{"speaker":"芹澤委員","kind":"質問・要望","question":"説明会の要望ということでありますけれども、かなり丁寧にご説明、ご議論があったのかなというふうに理解をしています。引き続き広報はしていただきながら、非常時も含めて、あってよかったと思える公園をぜひ造ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"塚本委員","kind":"意見","question":"先ほど来、言われておりますけれども、皆が使う公園ということで、たくさんの意見がある。なすべきことが遅滞するということもまた、アンケートを２回取り、区の計画どおり進めていただければというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。公園の改修やサッカー場は必要だと思いますが、いろいろな意見が出ている下で、再度、アンケート、説明会は必要だと思いますので、趣旨採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問","question":"やはり、十分に、本当に丁寧にしていると思うのです。これからも皆さんにご理解いただけるように、それでも１００％は理解できないところもあるので、諦めずに丁寧な説明をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"区域内全員を転出させる前提の計画を問題だと思わないのかとの質問に、区は、個々の選択の自由と答弁をしました。この個々の選択の自由とはどういう意味か、選択できないと思いますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4324#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":64985,"voices":266}},{"id":"r03-20210706-9","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"文教委員会","time":"午前１０時００分～午後 ０時３１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"学校連携観戦プログラムの中止を求めるという趣旨のご質問があったと思うのですけれども、それともどういうことなのか、再度確認をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"第４４号議案、学校教育職員の給与に関する条例の一部を改正する条例","agenda":"第４４号議案、学校教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"配置の先ですね、条例上の文言でこういうのは規定しているのでしょうかというのを確認したいのが１点目です。２点目は、もう少し説明してほしいなと思いまして、義務教育学校はほかの分離校にはない特別な位置づけがされているということなのか尋ねました。","respondent":"工藤指導課長","answer":"そういったところで、一貫教育そのもののいわゆる連続性などを担保する上では、中心的な存在というふうに私ども認識しています。一貫教育そのものというのは連携校でも十分行っているところで、そういった意味では、配置を義務教育学校に想定しているというところになります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"その中身について２点だけ伺いたいのですが、この２点について、それぞれ伺いたいと思います。私は、そういう点で一貫教育というのは見直すべきなのではないかと思っているのですけれども、いかがか尋ねました。","respondent":"工藤指導課長","answer":"本区の一貫教育の中では、６年生のこれまでの教育効果に加えながら、各学校が工夫して様々な取組を行っているところです。担任との関係性を一定程度継続しつつ、教科担任において様々な教員の目が行き届くという面で効果があると認識しておりますので、進めているです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"今、区教育委員会のお考えは聞かせていただきましたけれども、納得できるものではないのですが、今後、私も、小中一貫教育について、子どもにとって何が最善なのかという観点で、現場の方や当事者のお子さんとも話しながら、さらに研究・提案をしていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"資料としてつけていただいているＡ３のものなのですけれども、この中に組織図というところがあります。その下の権限・役割のところで書き分けがなされておりますけれども、指揮命令系統が重複する部分はあるのかどうか、伺ってもよろしいか尋ねました。","respondent":"工藤指導課長","answer":"これは平成２８年に義務教育学校になるまで継続したのですけれども、基本的に学校運営について支障はなかったと私どもも認識しています。６級職が併存いたしますけれども、校長、統括副校長の職務権限・役割を明確にしながら進められると考えております。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"そう考えると、固有教員の方たちのキャリアプランを考えたときに、やはりリーダーシップを一番発揮できるのは校長だと思うのです。いや、それでもやはり校長になりたいのだと思った場合に、どういう選択肢があり得るのかというところをお示しほしいと求めました。","respondent":"工藤指導課長","answer":"そういった県費負担の教職員になるという必要も生じてまいりますので、学校教育職員、これはあらかじめ国にも確認をしています。手だても考えたところですけれども、まずもっては定数１であるという、そういったものが必要になるということがあります。","id":"exchange-006"},{"speaker":"松本委員","kind":"意見","question":"最終的な人事権は都が持っているというのは、これは普通の民間企業で考えると、すごく不思議な状態だと思うのです。これは多分条例で、やろうと思えば最終的にはできると思うのですが、その辺りは可能かどうかというところをお願いいたしますとの意見を述べました。","respondent":"工藤指導課長","answer":"私ども、人事権の移譲に関しましては、様々な機会を捉えて都教育委員会に申入れをしているということがあります。まずもってそれが、まだかなわない部分はありますけれども、そういった声は都教育委員会に届けているです。","id":"exchange-007"},{"speaker":"吉田委員","kind":"確認","question":"基礎的なところを伺いたいのですけれども、に採用されたのが２７名ということで、何人ぐらいいらっしゃるのですか。その辺、確認したいと求めました。","respondent":"工藤指導課長","answer":"それぞれ退職や採用を繰り返しておりますので、令和３年度につきまして２７名いるです。職層につきましては、５級職の副校長、また、主幹教諭、主任教諭、教諭というふうに、各職層の中で、それぞれいるところです。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"都費の校長だと、区独自の教育について何か不都合があるのかというところを確認させてほしいと求めました。現場の先生方とか現在の校長先生方とか、そういう方たちの見解も、言っていい範囲で教えてほしいと求めました。","respondent":"工藤指導課長","answer":"特に滞りがあるわけではありませんが、副校長ではなし得ない、そういった中心的な役割を担っていただきたいと考えているところです。６級職、実現に向けて、期間としてはかなりかけて行ってきたものです。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。そういう方たちとは意見交換とか、例えば今こういう制度を考えていますぐらいのご報告はあるのか、その辺についても説明を求めました。","respondent":"工藤指導課長","answer":"考えているという案内は、特に広くこれを周知して、今こういう制度をつくっているという案内をしているというところはございません。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"義務教育学校になるというときも、生活者ネットワークとしては、今回も同じような混乱が起きるのではないかということを懸念しております。ごめんなさい、お答えになりにくいかもしれないですけれども、もしお答えいただけることがあれば説明を求めました。","respondent":"工藤指導課長","answer":"この条例で承認いただきましたら、教育委員会規則のほうで様々職務等を定める予定ですので、そのように進めるところです。そういった意味で、特段の混乱であるとか心配というところを今持ち合わせているところではございません。","id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"議会からの様々な質問とか提案など含めて、いろいろな議員から指摘・提案があった中で、質疑を確認している中で思ったのですけれども。それを教えていただきたいということと、学校ですから、教えていただきたいなと思いますとの意見を述べました。","respondent":"工藤指導課長","answer":"現状、勤務の中では、仮になのですけれども校長と合わせて学園長という呼称を使うなどといったことを私ども検討しています。業務分担等も含めて、それはまた学校に任せることでなく、教育委員会も相談に乗りながら進めたいと考えているところです。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"今この委員会質疑で確認する以上に、ご協力の度合いもさらに増すであろうなと想像するので、ぜひその辺りは十分やっていただきたいなと思いました。再度、今伺った大きく２点ですか、教えてほしいと求めました。","respondent":"工藤指導課長","answer":"そういったものも可能になると思いますので、一定程度、連携の中で役割をしっかり明確に分担しながらと考えているところです。そういった分担をきちんと行いつつ、児童・生徒と関わる時間というのはこれまでよりも設けられるのではないかと考えますので、したいと考えています。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"１点だけ、統括副校長の役割の中で地域連携というのはとても大事になってくると思います。そういった観点において、周知の説明であったり、そういうお考えを教えてほしいと求めました。","respondent":"工藤指導課長","answer":"スケジュールにありますように、現状でいうと有資格者が１名おりますけれども、選考を実施すると。しっかり行いたいと思いますし、配置が見込まれるという状況におきましては、十分な説明は学校も通じて行っていきたいと考えているところです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"提案","question":"進めるべきではないと思いますけれども、先ほど子どもたちと向き合う時間がという質疑もありましたが、そうした提案も何度かさせていただきました。賛成の理由としては、同じ職場で区費教員と都費教員の待遇は本来同じであるべきだし、賛成したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"今回のことについても、議論の経過とかを伺うと、もう少しきちんと議論してからこれを実施されたらどうかと思います。今、私も伺いましたので、そういうことをきちんと説明されてから始められても決して遅くはないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"第３６号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３６号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"食材を配る対象者は何世帯何人になり、１世帯につきどのような食材が何回届けられるのか、伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"配布の時期としては、夏休み頃に需要があるかなというところで、そのときに合わせて配布しようと考えています。８世帯で１０万円ですので、夏休み頃にセットして１回配布ということを考えております。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"これを基に制度をつくるとかいうことではなく、単発で行うということでしょうか。その２点、これをきっかけに何かするとかそういうことではないのでしょうかということを伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"こちらにつきましては、しあわせ食卓事業とは別のものと考えています。寄附者のご意向で、場所も指定されていたというところで、今回寄附をいただいて、その意向に沿って、単発で配布ということで考えてあります。","id":"exchange-018"}]},{"id":"topic-04","title":"令和３年陳情第３６号、区立子どもの森公園の工事に関する陳情","agenda":"令和３年陳情第３６号、区立子どもの森公園の工事に関する陳情","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークとしても同様に、やはり審査に当たって、陳情者の方の気持ちを理解する上でも、最初に意見陳述をぜひしていただきたい、その上で審議をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"松本委員","kind":"確認","question":"申合せ確認事項に記載があるのは、きちんとご意見を伺った上で、今の段階で意見陳述が必要ではないかと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、説明会５回ということでありましたけれども、工事着手までに行われたそれぞれ説明会の参加人数を教えていただきたいというのが１点です。影響の大きさを考えるに、広く意見を聞きながら建設を進めるべきではなかったかなと思うのですけれども、掲載しなかった理由を伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"１点目の説明会の参加人数についてお答えいたします。令和元年８月に行いました同じく任意の事業説明会につきましては、約１２０世帯に周知いたしまして、２名の方がいらっしゃいました。","id":"exchange-021"},{"speaker":"安藤委員","kind":"提案","question":"ですから、提案はしたのですけれども、もっと強くご提案すればよかったなと思います。今お伺いしますとトータルでも３７名ということで、大事なのは、当事者にそれが伝わったかどうかだと思いますとの意見を述べました。","respondent":"加島児童相談所移管担当課長","answer":"計画地の選定に当たってこれまでどのようなところを検討したのかといったことのご意見、ご質問をいただいたところです。公園に建てることについて、有識者の皆様からは特段否定的なご意見はございませんでした。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"この公園をどうするかということに関して、そこら辺の意見は何かなかったのかなということをお伺いしたいというのが１つ。１９７１年、昭和４６年にオープンしたのですが、伺いたいと思います。","respondent":"高梨公園課長","answer":"ほか、令和６年度の下水道工事完了までに少し間がありますので、それまでの間に意見の収集方法等について検討してまいりたいと考えているところです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"どれがいいですかと聞いたみたいですけれども、原始林公園が３割を占めて、現在の公園の原型が造られたと。ちょっと伺いたいのは、このようなもともとこういう公園だったのだよという経緯を区として認識された上で選定されたのか、伺いたいと思います。","respondent":"加島児童相談所移管担当課長、高梨公園課長","answer":"工事仮囲いに、それから下水道工事が終了いたしましたら公園再整備を予定していますということを内容としてご案内させていただいているところです。そのほか、すべての子どもたちが区として大切であるという認識の下に… 子供の森公園の経緯を踏まえたかどうかといった点についてお答えしますが、様々な用途の公有地を区として取得してきたところです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"そういった点で、区は今回反省すべき点がなかったのかなというのを伺いたい。今後の施策を進める上で活かすべき点をどのように考えているのかというのも併せて伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"あちらについても現在計画地と予定している程度の敷地面積がありますので、そちらの検討をしたところですけれども。区といたしましては、条例等の定めにのっとって、これからもしっかりと対応してまいりたいと考えているところです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、今回の件で反省すべきところはなかったのかなというシンプルな質問なのです。しかし、区としてはないのか、伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"それ以前には任意の事業説明会を２回開催いたしまして、近隣の方にもこういった児童相談所設置の整備の計画について、ご理解を求めてきたところです。区としては、今後も条例等に基づき、しっかりと対応してまいりたいと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"これは建築物を建てるわけですから、子どもの所管としてどうなのかなというか、それで子どもの最善の利益が本当に守れるのかと私は思います。部長とか、答弁できれば、答弁をお願いしたいと思うのですけれども、いかがでしょう。","respondent":"加島児童相談所移管担当課長","answer":"平成３０年６月に建設・文教委員会等でも議会報告させていただきまして、そこから区として説明会も開催し、周知を図ってきたところです。今後、それ以外にも今回任意の事業説明会を開催してまいりましたので、区としては適切に対応してきたものと認識しております。","id":"exchange-027"},{"speaker":"松本委員","kind":"質問","question":"前提として、進めている責任については、当然ながら行政のみならず議会にもあるという前提で質問に入りたいと思います。ポスティング等の対象というのが、どういう根拠で、どの程度だったのかというところをもう１回ご説明ほしいと求めました。","respondent":"加島児童相談所移管担当課長","answer":"それから９月の計画説明会・３月の工事説明会につきましては、建物の高さの２倍の範囲にお住まいの方々に周知をさせていただきました。工事説明会につきましても同様の扱いです。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"今回、利用者との関係ではなかなか対象としては狭くなってしまって、それで任意で開いていただいたというところがあると思っています。影響が大きいと思われるところということなのですが、影響が大きいと思われるというところをどういうふうに検討されたのか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"平成３１年１月に開催いたしました説明会のときは、まだ基本設計の最中でしたので、建物の大きさ等が定まっていたわけではございません。ほとんどお知らせが行き届かないのではということを考えまして、近隣の集合住宅、大きなところも含まれるような形で周知を図ったところです。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"我々も確認する上で、委員会の中とかで議論するときに、そこはきちんと考えていかなければならなかったのだなと思います。特に大きな公園ですから、今日は所管もいらっしゃっていただいていますので、周知の在り方については引き続き考えていただきたいなと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのときの要望で１つ確認したいのですけれども、ここは保育園の子たちも来ていると思います。今までのご答弁の中では保育園へこういう情報提供をしましたということはなかったのですけれども、その辺についてはどうだったのか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"保育支援課に子供の森公園を園庭として利用申請している園を確認いたしまして、そちらに建築計画、それから工事の計画について周知を図っております。その際の先方のご反応ですけれども、ご理解をいただいたと区としては認識しております。","id":"exchange-031"},{"speaker":"吉田委員","kind":"確認","question":"それをさらに広げるというようなことはなかったのか、検討はされなかったのか、その辺についても確認したいと思います。その辺について、この範囲でいいと判断された理由とかがあったら、説明を求めました。","respondent":"加島児童相談所移管担当課長、小林施設整備課長","answer":"まず基本設計段階で一度任意の説明会を開催させていただきまして、その後、２回目の事業説明会を行ったところです。その後、設計の煮詰まりとともに計画説明会の開催という運びとなりましたので、現在… その中には、３月から工事に着手しますよという内容と、また、工事の期間中はこの範囲が工事エリアになりますよという掲示もしています。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう意味でいえば、私たちももうちょっときちんと確認しながら、さらに意見を言っていくということが必要だったのだなと思います。過去に、今回についても同様のことが起きてしまったということについては、ぜひ当事者の方たちの声は今後も活かしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"説明会を５回開かれたというお話の中で、７名、２名、１３名、１５名と、私としてはだんだん増えているのかなと感じています。住民の方がだんだん後半になってそうやって認識を持ったのか、周知にちょっと特徴があって人が増えたのか、そういったのはどうお考えか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"平成３１年１月に任意の事業説明会を開催させていただきました際には、令和元年８月以降の個別要望による任意の事業説明会においては、あわせまして。","id":"exchange-034"},{"speaker":"松澤委員","kind":"意見","question":"町会に下ろしていく、だから周知がだんだん増えていって、人数が増えたという認識ですね。新しく公園が生まれ変わろうとしておりますが、この再整備に向けて子どもたちと一緒に話を聞く、その部分に関してお話しいただけたらと思いますとの意見を述べました。","respondent":"高梨公園課長","answer":"近隣の方、新しい怪獣公園としてどのような公園がふさわしいのかといったところを検討し、皆様とお話合いをしながら決めていきたいなと思います。しっかりと設計を進める中で、こちらの再整備についても同じように進めていきたい、このように考えているところです。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問・要望","question":"こういう話があったときに地盤の人に声をかけていくという、引き続き徹底した周知に協力してやっていきたいと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"つる委員","kind":"質問・要望","question":"それをいかに駆使していくかというところも、至極大変なのですけれども、非常に求められている部分を指摘されたのかなという理解ではあります。１点、設置していただいたのか、教えていただいていいか尋ねました。","respondent":"小林施設整備課長","answer":"それから建物がどのような用途なのかというのを掲示する看板ですが、それにつきましては、令和２年８月に掲示しております。それで申し上げますと、約１年弱ぐらいは掲示をしたと認識しております。","id":"exchange-037"},{"speaker":"つる委員","kind":"質問","question":"条例の範囲の中で一生懸命やってきたと伺いましたけれども、教えてほしいのが、というのはあるのでしょうか。できない、やっていけないこと。","respondent":"小林施設整備課長","answer":"先ほどからお話のあります紛争予防条例の所管部署ではないのであれなのですけれども、広報してはいけないというような、駄目な規定というのは基本的にないと認識しております。","id":"exchange-038"},{"speaker":"つる委員","kind":"質問・要望","question":"利用者の方たちの声だとかいうことをきちんと伺いながら、広報広聴の所管にトスをしていくという流れはつくっていただきたいなと、そう思いました。いろいろ申し上げてしまいましたけれども、広報広聴の所管ではないのでご答弁は結構ですので、ぜひ要望として参考にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"私の確認する限りですと、恐竜が写っていて、恐竜がいるよということをまだうたっている。これは要望として言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"安藤委員","kind":"意見","question":"陳情審査の結論を出す上でも、陳情者の方の意見陳述を聞きたいと思います。そういう思いは極力尊重しなければいけない、そういう議会にならなければいけないと思っていますので、ぜひ意見陳述をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"原則的なところで、議員として陳情の中身をより理解するためにも、意見陳述はぜひやってほしいと求めました。ですので、今回も意見陳述を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"申合せのところからきちんと考えるべきで、先ほど６月２５日に説明会があって、提出された時点からはいろいろと動きがあったと考えています。やはりきちんと意見を聞いた上で考えるべきと思いますし、聞かないというのは、これはきちんとご意見を伺うべきと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"つる委員","kind":"意見","question":"陳情が先月１７日に受理されていて、先月２４日付でも補足資料ということで私も頂戴しております。いいかなというところで、あえて陳述をいただかなくとも、こちらの資料で非常に理解させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"松澤委員","kind":"意見","question":"私も再資料、この資料のほかに新しくもらった資料熟読させていただきました。その思いの中で十分伝わったのではないかと、資料を読み込む中で私も十分理解できたと考えていますので、意見陳述はなしでいいと思いますとの意見を述べました。","respondent":"あくつ委員長","answer":"令和３年陳情第３６号、意見が分かれましたので、採決を行いたいと思います。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"今の委員長の決定の理由、委員長がそういうふうに判断した理由を伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"安藤委員","kind":"意見","question":"それは理由になっていないといいますか、今までの質疑を聞いて、どこをどう判断して、委員長としてあえて意見陳述をやりたいという方の意見陳述を聞かないという判断をしたのかというのを聞いていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"松澤委員","kind":"質問・要望","question":"この陳情の中では、周知・広報をしていただきたいというお話の中で、いろいろ理事者のお話も聞きました。求められる周知・広報の在り方、子どもたちの話を聞くということも含めて、広報の在り方という部分に対しては強く要望してまいりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ積極的な工夫を、いろいろできる範囲の中でやっていただきたいなというところ、これはあります。ただ、しっかりと説明については工夫と努力を惜しみなくやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"そういう意味でも採択すべきだと思います。工事は進んでいるのですけれども、発注者は区なのですから、そのような中で必要があれば工事を止めることが必要なこともあるかもしれないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり受け止める側がどう受け止めるかということをもう少し工夫されるべきというのは、一致したご意見なのではないかなと思いました。そういう意味で、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"松本委員","kind":"質問","question":"きちんと具体的にこういうのではどうですかというレベルまで本当は言わなければならないのに、では全区民ですかという話にもなり得るところで。これを停止するという意見を述べるのは、議員として無責任ではないかと私は思いますので、本件については不採択と考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5036#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":42095,"voices":154}},{"id":"r03-20210706-5","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"総務委員会","time":"午前１０時００分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げたとおり、取り上げる順番を変更し、議案審査(3)から行います。 それでは、(3)第４５号議案 三ツ木保育園改築工事請負契約","agenda":"冒頭に申し上げたとおり、取り上げる順番を変更し、議案審査(3)から行います。 それでは、(3)第４５号議案 三ツ木保育園改築工事請負契約","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これは園庭が狭くなるのですか。周辺への建築に関しての周知あるいは合意というところがどうなっているのかということ、その２点についてお伺いしたいと思います。","respondent":"小林（剛）施設整備課長","answer":"そういった方に周知をいたしまして、その後、ご意見を頂いている方が１件あります。そういうところのご意見を頂きまして、それらの意見につきましては、設計をしていく中で対応したところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"園庭が半分になるということですけれども、その点について、ここの内部、利用者の方とか、それから保育士の方とかから何かご意見があったりはしたのか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"園庭が狭くなってしまうというところに関しましては、代替の公園としまして、近くに西品川公園、品川中央公園、三ツ木公園等々がございまして、そちらを活用して、そこで外で遊んでいただくというような保育を工夫していくということで、ご理解を頂いているです。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"やはり遊べるスペースというのを確保されているのか、安全性という部分でお知らせいただければと思うのですが、いかがか尋ねました。","respondent":"小林（剛）施設整備課長","answer":"その中には、今お話のありました屋上緑化の経験もあったかと思いますので、屋上緑化ができない業者ではないと認識しています。つきましては、屋上で何か緑化でお子さんと遊ぶとかというところは、今回の計画の中では考えてございません。","id":"exchange-003"},{"speaker":"田中委員","kind":"確認","question":"例えば何か畑みたいなものを作って食育につなげていくとか、そういったものが用意されているのかというところを確認したいです。やはり遊ぶスペースというのをできるだけ確保してほしいということを思っていて、そういった設計なのか、ちょっと確認をしたかったです。","respondent":"初貝保育教育運営担当課長","answer":"園庭自体は１階のところにありますので、そういったお声を聞きながら、そこで食育等々にどういった形で取組むのかということを今後詰めていきたいと思っています。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"今のお話にもありましたとおり、今のこの感染症の関係もあって、遊ぶところで子どもたちが密にならないような工夫がとてもされているのです。何歳児がどこどこで遊ぶといった分けられるような工夫という観点も、これから入れていただきたいということを要望したいのですが、いかがか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"今現在も保育の中で、なるべく集団が大きくならないような形で工夫をしております。今後もコロナ対策で、なるべく小集団になるような形で、保育のほうで工夫をしてまいりたいと考えています。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"何か事故があったときですけれども、スロープ状の滑り台みたいな簡易に素早く避難できるような工夫も、この中にはされているのでしょうか。あくまで３歳児だろうが４歳児だろうが、その方に委ねるということなのでしょうか、説明を求めました。","respondent":"初貝保育教育運営担当課長","answer":"今ご指摘がありました避難路ですけれども、２方向避難は一応確保しています。４、５歳の園児になりますので、保育士がきちんと安全に避難できるように付き添って避難するということを想定しております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"ただ、素早く簡易に誘導するには、そういうスロープ状のものも保育園によっては設置されているとお聞きしていますが、ここにはないということですか。あくまで手で何人かを連れて下に下りて、また上に上がってきて下りてやるというような状況なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"おくの委員","kind":"意見","question":"民営化自体は元に戻すべきですけれども、老朽化しているのは改修すべきということで、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの屋上の利用だったり、食育とか遊ぶ場所の確保とかも十分に検討していただいて、なるべくそういう場所を確保していただきたいという要望も併せての賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"それから、桜並木で有名な道路ですけれども、その桜並木などの景観も含めて影響があるのかということが第１点、お伺いしたいと思います。それと関連しますけれども、先ほどの三ツ木保育園と同様、周辺への周知、合意の点で問題はないのかということもお伺いしたいと思います。","respondent":"小林（道）学校施設担当課長","answer":"かむろ坂および桜並木につきましては影響がないものと、まず手を付けるということは今考えておりません。計画説明会を去年やりまして、そして資料のみ持って帰った方が１名というところで、計画説明会をやって周知をしたところです。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"それから、この学校の設備でかむろ坂ホールというものができると伺ったのですけれども、ここの多目的室というところがそれを兼ねるのでしょうか。これは一体どのようなものなのか、それからどのような運営や利用形態を考えられているのか、もしできるのならそういうこともお伺いしたいと思います。","respondent":"小林（道）学校施設担当課長","answer":"１階にかむろ坂ホールというものがあるのですが、これはいわゆる多目的ホールで、地域に開放することを考えております。詳細はこれから検討に入るです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの質疑の中で気になった点をまずお伺いしたいのですけれども、通学時は大丈夫なのかというところを確認させていただきたいのと、あと。なので、雨水の利用とか、そういう部分についてはどのような契約がされているのかというところをお伺いできたらと思います。","respondent":"小林（道）学校施設担当課長","answer":"静電気防止に努めているものだとか、いろいろありますので、一番適したものを今後選定してまいります。雨水利用は今回も約３４ｔのピット、トイレの排水に利用するとか、そういうことで考えております。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"すごくメリットもあるけれどこういうデメリットもあるというのを逆に活用しての学習をしていただきたいということを要望したいというのと、あと。そういう防音対策ということがされているのか、そういう契約になっているのかというところも伺いたいのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"小・中一貫校ができたときに、総額で７０億円、８０億円ぐらいだったと思うのですが、やはり今これほどコスト的に上がっているのですか。ほとんど決まっている内容だと思うのですが、やはりＪＶという形で持っていかなくてはいけないのか、その辺について説明を求めました。","respondent":"小林（道）学校施設担当課長、東野経理課長","answer":"私のほうから、質問の３点のうちのまず２点をお答えします。バリアフリーだとかエレベーター設置だとかスロープ設置、手すり設置、もろもろの付加が入ってきているということ。 それから電気のほうですと７億円を超えるようなものという形になりますので、十分にＪＶ工事として取り扱うべきものとして考えております。その形で発注をしているものです。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど校庭の話があったので、ちょっと確認したいことがあります。そういったことはどのように検討されたのか確認したいのと、縦に大きくなったという話もあったので、そこについてもお聞かせほしいと求めました。","respondent":"小林（道）学校施設担当課長","answer":"校庭は今現在人工芝等と考えておりますので、これについては火には不向きというか利用はできません。火を利用するものについては、土ではございませんので利用ができないと。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"そこは所管がずれるのかもしれないですが、要望として。不動前駅周辺は思いのほか騒音の影響が大きかったので、そういうところをちょっと考えていただきたいと思うのですが、一言頂けたら。","respondent":"小林（道）学校施設担当課長","answer":"授業に影響するような計画というのはやはり避けなくてはいけないので、そこら辺は十分検討して、今回反映しています。","id":"exchange-016"}]},{"id":"topic-02","title":"第４６号議案 大井坂下公園改修工事請負契約","agenda":"第４６号議案 大井坂下公園改修工事請負契約","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ユニバーサルデザインということですけれども、障害のあるお子さんとは無関係に、普通の小学校から集まってもらったというようなことなのでしょうか。そこら辺、障害のあるお子さんを特に集めたとか、そういうところはどうなのか尋ねました。","respondent":"高梨公園課長","answer":"集まっていただいた方は、通常の小学校に通っている健常者のお子様に集まっていただきました。ただ、ワークショップの途中で品川特別支援学校の中学部の生徒さんに先生を含めて参加していただきまして、そちらのほうからもご意見を頂きながら。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"特別支援学校から中学部の方ということですけれども、もう少し詳しくどのくらい集まってどのような意見が出たか。そのワークショップは３・４年生の方が集まって、それぞれどのような意見が出たか、ざっとでいいですから教えてほしいと求めました。","respondent":"高梨公園課長","answer":"今回特別支援学校の生徒さん２名に参加していただいて、そのグループごとにアイデアを頂いたといった形で出していただいております。どうしても気持ちが高ぶって興奮してしまって、公園の中にクールダウンスペースとして、今回の公園改修にもそのアイデアを生かしています。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと伺いたいのが、この契約の中にはないですよねということを確認したいのと、この契約の相手方の方たちは。この座り心地だったりとかを確認できるのか、ユニバーサルベッドはきちんとされているのかということを確認したいと求めました。","respondent":"高梨公園課長","answer":"２番目に、現在の公園にある喫煙所の扱いについてですが、今回新しく改修した後の公園については、喫煙所を撤去するという方針で進めております。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"契約の相手方の方たちは、ぜひ完成をする前に、ぜひ完成する前に当事者の方たちがチェックする機会を設けていただきたいと強く求めます。ただ、そういった配慮というか、とにかくここでは吸わないようにということをどのように徹底していくのかというところも確認したいと求めました。","respondent":"高梨公園課長","answer":"その中で、特別支援学校から参加していただいた方の意見聴取等についても、学校の先生との話し合いの中で今後検討してまいりたいと考えております。今回大井坂下公園の喫煙所を撤去しても、ほかの公園に多くの喫煙者が流れるといった事象は起きないものと考えているところです。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ前もって、まだ直せる段階での当事者の参加というのはとても必要だと思うので、そこを求めたいと思います。これは最初に言った要望と重なりますけれども、そして障害児たちの参加というのをぜひしていただきたいということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから、多くの区民の方に親しまれているというのをすごく目の当たりにして、すごく明るく区民に好まれるいい公園ができたのかなと感じます。そういうものをやはり工夫しながら、改善しながら、よりいいものを目指して進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"当事者の参加というのを強く求めて、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"第５０号議案、防災ラジオ他の買入れ","agenda":"第５０号議案、防災ラジオ他の買入れ","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"品川区でもぜひ例えばこのようにしていただきたいと思っているのですけれども、その点いかがお考えかということを伺いたいと思います。もう一つ、平成２４年度にやられているときは、そこら辺をどのようになさったのかもお伺いしたいと思います。","respondent":"平原防災体制整備担当課長","answer":"１点目、具体的な金額を検討していくこととなりますけれども、他区の事例も踏まえまして検討してまいりたいと思います。一般の方が４,０００円、高齢者・障害者・住民税非課税世帯につきましては２,０００円という形であっ旋販売をさせていただいたところです。","id":"exchange-024"},{"speaker":"おくの委員","kind":"質問・要望","question":"そのようにしてほしいと求めました。そのように要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"そこのところを確認させていただきたいのと、どういった契約の条件を出していたのかというところを確認したいのですけれども、そこの部分について示すよう求めました。","respondent":"平原防災体制整備担当課長、東野経理課長","answer":"令和２年度からスマートフォンにおいて、防災ラジオを使ってそういったものの補完をしていきたいと考えています。その関係もありまして、高齢者・障害者、そういった価格の設定を今後考えてまいりたいと思ってあります。 契約条件ですが、こちらの概要書に書いてあるものを仕様書に充てておりまして、１台幾らですというようなもの、それから起動装置につきましても１台幾らでというようなものを合計したもので入札いただいたという形です。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"この防災ラジオにどういった機能を求めたとか、そういうものは条件の中になかったのでしょうか。そういう細かな部分を知りたかったのですけれども、ご説明いただけたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"防災課から購入したと思うのですが、そうするとそれはもう全く使わなくなる、使えなくなる方向で品川区は動くということでよろしいのでしょうか。せっかく買った方、何かうまく交換をして安く購入できるような仕組み作りも必要ではないかと思うのですが、その辺についてご見解を説明するよう求めました。","respondent":"平原防災体制整備担当課長","answer":"こちらにつきましては、国の省令改正に基づきましてデジタル波に変更されるのですけれども、そちらに伴いまして自動起動がされなくなってしまいます。","id":"exchange-028"}]},{"id":"topic-04","title":"第３７号議案、一般職の任期付職員の採用に関する条例の一部を改正する条例","agenda":"第３７号議案、一般職の任期付職員の採用に関する条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"人事に関することですから、ちょっと確認をさせてください。降給、給料が下がる場合も含まれているということですけれども、例えばどういうことなのか尋ねました。","respondent":"崎村人事課長","answer":"本年３月に特別区と、特別区の職員団体である特別区職員労働組合連合会とのほうでこちらの交渉を行いまして、妥結をしています。今回の制度変更については、降給をすることを前提としたものではないということだけご理解を頂ければと思います。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"ボーナスも出ますよ、様々な待遇がよくなるのですけれども、ほとんど国民の多くの方が対象にならないということなのですか。それとも総務省のほうで、そういう事業所に対してもこういう通達が行っているのか尋ねました。","respondent":"崎村人事課長","answer":"この任期付職員につきましては正規の職員、ただ任期があるということで、常勤職員と同様の仕事をする職員ということになります。今回そういった常勤職員が行う業務を担っている職員ということも鑑みまして、昇給を実施すべきということで、条例を改正するといったものです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう一般の非正規雇用の人も、そういう方たちもやはり上げてもらうように、私は区から総務省のほうにやはり進言してほしいと求めました。その辺、意見として、要望として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"たけうち副委員長","kind":"質問","question":"今実際にこの例に当てはまる方がいるとしたら、どのような方なのか。それから、もしくは今はいないけれども、今までこういう方がいたとか、何か具体的にこういう仕事の方というのを説明するよう求めました。","respondent":"崎村人事課長","answer":"平成３０年度、平成３１年度に合計１１名を採用した実績がありますが、昨年度末の任期満了に伴いまして現在はいないです。先ほど言いましたように一定の期間内で業務を終了することが見込まれるものですとか、一定の期間内に業務量の増大が見込まれるものについて。","id":"exchange-032"}]},{"id":"topic-05","title":"第３８号議案、品川区特別区税条例の一部を改正する条例","agenda":"第３８号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"その方の例えば所得とか、それから実際どういう生活をしているかとか、そういうことは把握できるのですか。それとも、いや、きちんとこの方はもう所得がない、いろいろな支援も受けて生活されているということまで詳しく把握できるのか尋ねました。","respondent":"提坂税務課長","answer":"年齢が３０歳以上７０歳未満ということでございまして、その辺の不公平感を解消する意味で、今回の改正を行うです。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"２９歳以下でも、いろいろなベンチャーをやったりして、あくまで不公平感の解消にできるだけ努めるという考え方でいればいいのでしょうか。それだけ説明を求めました。","respondent":"提坂税務課長","answer":"年齢要件とか、国外居住の親族の数とか、内容も随時見直しとかその辺を行いまして、この辺の制度も改正していくとかそういう可能性はありますので、その辺の国の動向を注視してまいりたいと考えています。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、資料の作り方としてもう少し丁寧に、今のご説明はすごく分かりやすかったので、分かりやすい資料を頂けたらということを要望したいと。もし一言ありましたらお願いします。","respondent":"提坂税務課長","answer":"基本的に委員会の資料はＡ４一枚で納まればベストなのですが、今回の場合はなかなか細かい内容があってＡ３にさせていただきました。その辺は口頭で捕捉するしかないのかなと思いますけれども、今頂いたご意見を承りまして、またよりよい資料を作るよう努めてまいります。","id":"exchange-035"}]},{"id":"topic-06","title":"令和２年度品川区一般会計予算繰越明許費繰越計算書","agenda":"令和２年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"小芝委員","kind":"意見","question":"まず７月４日の都議会議員選挙の投票日にＬＩＮＥで投稿された内容の中で、２つ立て続けにありましたので、またその改善をお願いしたいと思いますとの意見を述べました。","respondent":"堀越企画部長","answer":"速報性、ＳＮＳですとなるべく早めに出そうということで、確認はしておるのですけれどもこのような間違いが生じてしまったです。こういった間違いの事例を共有して、かつ迅速に区民の皆様に情報をお伝えするという形で、そのような姿勢で進めてまいりたいと思っているところです。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2202#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":30139,"voices":177}},{"id":"r03-20210707-6","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"区民委員会","time":"午前１０時００分～午後 ０時０３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"荏原第一地域センターの移転","agenda":"荏原第一地域センターの移転","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"１点だけ、旧荏原第一地域センターと、移転した新しい新荏原第一地域センターですけれども、ランニングコストというのか、維持管理費というのか、比較した場合どういう違いがあるのか、この点だけご説明いただけますかとの意見を述べました。","respondent":"川島地域活動課長","answer":"合計すると６６０万円余になっているのですが、令和３年度分の７月から３月末までのところで言いますと、２,３４０万円ほどかかると。令和４年度以降も大体年間２,０００万円ほどの維持管理費、その辺のところについては、区の支出も多くなっているところです。","id":"exchange-001"}]},{"id":"topic-02","title":"東京２０２０大会期間中の事業（予定）","agenda":"東京２０２０大会期間中の事業（予定）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"近隣住民への周知や説明、どういう対策を行っているのかの説明などはどのように行っているのか、お伺いしたいと思います。あわせて伺いますけれども、つまりは一般の方の入場はできないということでよいのか、確認したいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"不安の声がないように、払拭されるように、きちんと説明はしていきたいと考えています。同様に、オンライン配信自体は別の場所で収録をしますので、競馬場にも人が集まるということはないと認識しております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"先日の本会議で濱野区長は、「東京２０２０大会を成功させることが区の役割と認識」という答弁がありました。お伺いしたいのですけれども、なぜコロナの感染が広がり命のリスクを伴う中、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"いろいろな意見があると認識しております。品川区の火ということで、火を採る採火式というのは行う予定になっておりまして、みんなで一つになるというような形で進めていきたいと考えています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、命のリスクを伴うオリンピックの成功が、なぜ区の役割だと思うのかと伺いました。そして、国や東京都や関係者に、品川区としてオリンピックの開催の中止を申し出るべきだと思いますが、それぞれいかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"人の命かオリンピックかというこの二者択一というのは、今まで一度もそういうふうには考えたことはございません。きちんとそこを担保した上でオリンピックを成功させる、それが私たちの仕事ですので、中止を訴えるような考えは特にございません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"各種事業も、規模は縮小したとはいえ、人の流れが生まれていく。リスクを伴うオリンピックの開催は中止すべきだと述べて、終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"くにば委員","kind":"確認","question":"１点だけ確認させてください。この２番目のパラ・パワーリフティング、それは周辺住民に含まれるのかどうか、説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"周辺の定義ですが、練習場所所在地の地域センターの管轄になろうかと思います。町会長会議、または自治会長会議等でご連絡するというのが大体の流れですので、そういった形になろうかと思います。","id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"それは、周辺住民ではなく、周辺住民のある意味、長というか、集団の中のトップの人に説明する。それは、周辺住民に直接説明が行き届かないということか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"自治会長、町会長から周辺の住民にまたお知らせいただくということで、そのようなルートを使って、区の事業やご連絡というのは通常差し上げてありますので、同じようにさせていただきたいと思っています。","id":"exchange-007"},{"speaker":"くにば委員","kind":"質問","question":"その町会長、自治会長が、そこの中の人たちに周知をするというのは、きちんと区のほうからその周知をしなさいという命令で周知をするのでしょうか。例えば私は地元の自治会には加入していないのですけれども、加入していない周辺住民の方にも連絡は来るのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"緊急性のあるものでしたら、掲示板等に緊急で貼るような場合もあります。そこから周知していただくという方法を取りたいと考えていますので、こちらとしては周知のお願いをするというような位置づけになろうかと思います。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問","question":"私が質問したことにいまいち足りていないと思うのですけれども、端的に、自治会に加入していない方のところに連絡は行くのでしょうか。周知が徹底されるのは、区の責任で周知を徹底するべきだと思うのですけれども、その２点についてお伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"周知の仕方ですが、なかなかこれだけの区民がいる中で、その方１人ずつに全てお知らせするというのは難しい部分もあります。私どもは、そこはきちんと皆さんに安心して生活をしていただけるような形を取りながら、周知はしていきたいと考えています。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"区のほうで責任を持って周辺住民の方に、例えば工事とかがあるときは、普通に周辺住民の方たちにポスティングでお知らせが入るではないですか。そういった形が、例えば１つ、周辺住民の方に区が責任を持ってきちんと周知をするということだと思うのですけれども、もう一度答えるよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"現在のところ、ポスティングまでは検討しておりません。委員もおっしゃられたようなＳＮＳですとか、そういったものも使いながら、周知はしていきたいと思います。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"本当にそれは、先ほど、動線を分けるから直接接触はしないとおっしゃいましたけれども、直接の接触だけではないではないですか。ここにいる間は一切建物から出ず、区民には一切触れないという認識なのか、そこの２点をお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"周知の方法は、区民の皆様、特に八潮地域の皆様に心配がないような形は、いろいろ講じてはいきたいと考えています。区民とは全く接しないような方法で、事前キャンプにおいてはそういうふうにマニュアル上もなっていますし、そういうふうに徹底してやる予定です。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問・要望","question":"慎重に考えてすべきだと思っているのですけれども、では、それはお願いしますという要望にしておきます。例えば区民の方が利用できるところのトイレを使ってしまったら、トイレの例えば蛇口経由で感染が広がるということがあるではないか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そこに置いて、それで利用する方が取りに来るという形を取っていると認識しておりますので、同じようにさせていただこうかなと思います。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"すぐ向かいに住んでいる僕にも、必ず周知が届いてしかるべきであろうと思うので、周知徹底のほうは必ずお願いします。その徹底してやりますというのが、本当に徹底してできているかというと、実際にざるの部分があったりするので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"幾つか確認させてください。調整中ということですけれども、何か対象者に関しての情報で分かる部分がありましたら、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"実は２年前にも１回行いまして、そのとき、区民の方ですとか小学生とも交流をしまして、非常にいい交流ができたと考えています。なかなか在住・在勤の確認が難しいというところがありますので、ひょっとしたら、特に限らずになってしまう可能性もあります。","id":"exchange-014"},{"speaker":"横山委員","kind":"意見","question":"やはり選手の方も、しっかりこのパラリンピックに向けてずっと頑張って練習してきた中で、本来の力を発揮するのも本当に難しい状況だと思います。できる範囲で、無理のない形で、感染症対策に気をつけながら進めていっていたければと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう計画なのか、チラシでポスティングをすることを検討してほしいと求めましたが、いかがでしょうか。理解を得ながら進めていくというのが、これまで品川区もやっているところもあるわけですから、その点だけいかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"住民説明の方法です。そういった中では、公園を造るときのような住民説明会だとか、そういったことは今のところは考えてはいません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ポスティングは何で検討できないのですか。改めて実施してほしいと求めましたが、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"住民周知の方法については、事案に応じて様々な形があると考えています。今回の事前キャンプに関しましては、私どもとしては、自治会長や町会長に説明ということで、今のところ考えております。","id":"exchange-017"},{"speaker":"新妻副委員長","kind":"確認","question":"事前キャンプの件ですが、総合体育館、こみゅにてぃぷらざ八潮、これまでもサークル、団体で使っている方が多くいらっしゃると思うのですが、これらの方々への周知というのはどういうふうになっているのかというところを、１点確認したいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"どちらの施設も住民の方が、団体で定期的に使っているような方もいらっしゃると思います。そちらに関しましては、施設のほうで、もう既に貼り紙をしてありますとか、そういった形で周知はしています。","id":"exchange-018"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"周辺、また区民の方が心配なきように、またこの対策はお願いをしたいと思います。皆さんがやってよかったと思えるようなことは、ぜひまたご相談を進めてほしいと求めましたので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2904#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":16745,"voices":58}},{"id":"r03-20210707-7","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"厚生委員会","time":"午前１０時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順序を変更しまして、初めに、(3)新型コロナウイルス感染症の影響により収入が減少したこと等による第一号被保険者の介護保険料の減免","agenda":"会議の運営上、予定表の順序を変更しまして、初めに、(3)新型コロナウイルス感染症の影響により収入が減少したこと等による第一号被保険者の介護保険料の減免","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１つは介護保険料なのですけれども、介護保険料のほうの実績について教えてほしいと求めました。コロナで３割減少になった、さらにその３割減少になるということでないと対象にならないのかということについて説明を求めました。","respondent":"宮尾高齢者福祉課長、池田国保医療年金課長","answer":"以上が令和２年度の減免実績です。対象の額の考え方ですが、令和２年度の収入と令和３年度の収入を比較して、アの場合ですと１０分の３以上減額が見込まれる場合に対象となるです。 国民健康保険料の減免の考え方ですけれども、令和２年度の際に、令和３年度で特に継続してのコロナ減免というものはないです。あくまでも、コロナによって今年減少が見込まれるということで、対象となってまいります。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、３割以上減収になってしまって、同じ減少が続いているという状況でも対象にならないということになるのでしょうか。そこのところの確認をさせていただけますか尋ねました。","respondent":"池田国保医療年金課長","answer":"あくまでも令和２年度は令和２年度の収入ということで、減免の申請ということになります。令和３年度、今年の分のコロナ減免につきましては、今年の収入が、コロナの影響により、今現在、これから先、減った場合ということで該当になるです。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"こういう方でも、令和２年度で免除されたという収入がそのまま続くという方でも、減免の対象にはならないということなのでしょうか。この方には、令和２年よりもさらに３割減収にならないと減免の対象にならないということなのか尋ねました。","respondent":"池田国保医療年金課長","answer":"今お話があったように、昨年の収入から減少していない限りは対象にはならないです。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"コロナの影響でずっと同じような状況が続いているのに、今回の減免制度の在り方として問題なのではないかと思うのですけれども。同じ収入が続くにもかかわらず減免の対象にならないというのは、制度として問題なのではないかと思うのですけれども、その点はいかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"昨年、昨年の収入が減る見込みということで申請されている方でございまして、その少ない収入に対しての保険料が賦課されている状態です。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その３割減ったところでの収入のときは免除されたにもかかわらず、さらにそこから３割減らないと免除にならないというのは、いかがでしょうか。やはりコロナの前から３割減ったという状況がずっと続けば減免されるという制度であるべきなのではないかと思うのですけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"というのは、既に収入が減ったところで保険料が決定するわけです。令和３年度、令和２年度と引き続きやった場合の矛盾があるかというと、それはないかと考えております。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当にこれは国の制度ですから、今年度は１５万円もの国民健康保険料がかかってくるというのは、これはちょっと国のほうでも見直していただきたいと。区からもぜひ国にも、同じようにコロナの影響で３割減少が続くのであれば、ぜひ意見を上げていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"品川区成年後見制度利用促進基本計画のパブリックコメント実施結果","agenda":"品川区成年後見制度利用促進基本計画のパブリックコメント実施結果","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは１０月に発行されるということで、高齢者と障害者、それぞれ何人ぐらいずつ利用されているのかということを教えてほしいと求めました。その後どうしていくかなどというのが、１年ごとに出されていくということになっていくのかという、その辺のことを教えていただけたらと思います。","respondent":"寺嶋福祉計画課長","answer":"例えば年に１回、その中で決めていけるのかなと、柔軟に対応できるとは捉えております。しっかりその中で検討していって、今の段階では考えておりまして、策定委員会でもそのような意見が出ていたところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それからもう一つ伺いたいのが、本人が負担しない仕組みとするように検討してほしいというのを、区は「国の動向を注視しつつ。国でも検討されているとか、区でも検討されているということがあるのか、この点についても伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"お答えも頂いていない、見込みとしてこちらの方に、立ち上げ期はやっていただきたいと考えているところです。まさに今後、こういった形をつくった上で、どういったことができるのかというのを検討していくというのが課題だとは捉えています。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"ただ、区民の方々への周知などというところがなかなかだと思うのですが、パブリックコメントの３２件という意見の数がどうかということ。皆さん、どういうご意見というのは中を見たら分かるのですけれども、３２件という数字について、どういうふうにお考えか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"この時点で、まだ周知、普及啓発が行き届いていないのではないかという意味でのご指摘と受け止めました。今回、かなりの部数を作って普及啓発に努めようということも考えておりますので、委員会の中でも皆さん共通の意見であったということをお伝えします。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"意見","question":"非常に大事な仕組みをつくっていただいていて、すばらしいことなのですが、結局、見てみるとすごく複雑な仕組みで難しいので、今お話があったように、分かりやすいパンフレット等で周知を進めてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-03","title":"令和２年度品川区介護保険制度の運営状況","agenda":"令和２年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、１ページで高齢化率が２０.２％で同じなのですけれども、どう分析されているのかということについてもお聞かせほしいと求めました。令和２年度に初めて、認定率１８.５％ということで下がったのですが、区としてはどう捉えられているのかについてもお聞かせほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"ただ、高い水準で推移していくことを考えておりますので、高齢者対策はしっかりと推進していく必要があると認識しています。令和２年度だけの数字をもって、まだ今の時点では何ともというところがありますので、引き続き動向を注視してまいる必要があると考えております。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どんなところにどういう形で出ているのかということも、区としてどう考えられているのか、伺いたいと思います。１２ページの総合事業なのですが、例えば南大井文化センターで３６回あって２９人というのは、やったけれども人がいなかったということなのか尋ねました。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"令和２年度から令和３年度にかけては、コロナ前の水準に戻りつつあるというのが、傾向としてはあるところです。区としても、国の制度の趣旨を、しっかりと事業所に周知しています。参加人数は２９人というところのお答えなのですけれども、はつらつ健康教室は週１回で３か月間、全１２回が１クールとなっております。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"コロナの影響で介護報酬を２段階上げたところで請求してもいいという、地域の方々から、すごくありがたいという評価をお聞きしております。コロナの影響がこれからもしばらく続くと思いますので、様々現実に合わせて対応をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-04","title":"第6期品川区障害福祉計画・第2期品川区障害児福祉計画のパブリックコメント実施結果","agenda":"第6期品川区障害福祉計画・第2期品川区障害児福祉計画のパブリックコメント実施結果","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"障害者団体１３団体に２月にヒアリングを行われたということなのですけれども、主な意見についてご紹介いただけたらと思うのです。それと、１３団体からどんな意見が出されたのかというのをまとめられたものというのはあるのか、その点についても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"こちらにつきましては、ホームページで掲載しますので、ご覧いただけると考えています。全体的には、ご要望といったような、計画についてというより、日常的に日頃から感じていらっしゃることというのが主なご意見でした。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"どういう施設がどこにあるというのが落とされているのを見ても、また６ページにも、荏原地域は圧倒的に少ないという思いがするのです。そこの文言はつけていただいて、きちんとやっていただけたらという思いが私はあるのですけれども、そこの認識について伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"計画に荏原地区という文言を記載するかどうかというところにつきましては４回にわたりご検討いただきましたけれども、特にその記載というのは。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"若干増えた部分もあるのですけれども、その増えたところも補助金が一つも使われなかったということがあると思うのです。補助金を活用しながら、もっと増やすというところに持っていくにはどうしたらいいのか、その辺の区の考えをお聞かせいただけたらと思いますとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"グループホームの説明会も延期していたりという時期もありまして、早くオープンしたほうがいいということで、開設を頂いております。今後につきましても、グループホーム補助金につきましては、積極的に周知を図っていきたいと考えております。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと、どこをどういう形で回していくのかというところなのですけれども、去年の段階では私が質問をしたときにそういうご答弁をされていたのです。そういう点についても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"計画の６ページに記載していますが、文章の中の下から３行目です。こちらは新たに立ち上げまして、実績については、品川区障害福祉計画推進委員会で検証・分析を行ってまいりたいと考えております。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"３年間、継続して、実績というのをその次につなげていくという形でやっていくということになっていくのでしょうか。この点についてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"国で障害福祉計画推進委員会というような文言や方針があるのかというお尋ねですが、国のほうでは特にございません。どういう体制がよろしいのか、現在の策定委員会や地域自立支援協議会ではなく、別のところで検証したほうがいいだろうというところで考えたものです。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど成年後見のところでパブリックコメントについてお尋ねしたのですが、他区のパブリックコメントのコメントの数というのでしょうか、もし分かればお願いします。","respondent":"松山障害者福祉課長","answer":"あるいは５０件、７０件ぐらいが、大体平均となっております。他区に比べて品川区はかなり、ちょっと飛び抜けて多いという状況です。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご意見を大変たくさん頂いているということで、団体も含めて２３人ですか、それで６７３件という、今、２３区で比較して多いというご説明がありましたけれども、２３人の、団体を含めた方々から６７３件ということについて、どんな分析というか、状況か尋ねました。","respondent":"松山障害者福祉課長","answer":"６７３件のうち、お一人の方と１団体の方で６００件以上を占めておりまして、大体９割を占めております。多く頂くのは特に制限はないのですけれども、やはり公平性の観点から、できれば広く平均的な数のご意見を頂けるとありがたいと感じているところです。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"このようなご意見を伺いながら、今後３年間、計画の推進をきっちりと進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"これは具体的に、保育園、幼稚園、小学校、中学校というところと、どのような場で連携していくのか。この計画だと３年だと思うのですけれども、具体的にどういった場で連携や情報共有などをしていくのか、その辺を教えていただきたいです。","respondent":"松山障害者福祉課長","answer":"今まで、連携というのは、個別の案件ごとにスピードアップして、随時、行ってまいりました。これから具体的に少しずつ一歩一歩、進めていければと考えております。","id":"exchange-022"},{"speaker":"せお委員","kind":"質問・要望","question":"私は、本当はあまり連携という言葉は好きではなくて、当たり前なので、これから当たり前にそういったところが、部や課など関係なくスピーディーに情報共有できるようになってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-05","title":"令和2年度品川区障害福祉計画実績","agenda":"令和2年度品川区障害福祉計画実績","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"きちんと評価と、次につなげるというところで出していっていただきたいと思うのですけれども、その点を１つお聞かせほしいと求めました。具体的なところで伺いたいのですけれども、令和２年度のところが、様々すごく激減しているという感じなのです。","respondent":"松山障害者福祉課長","answer":"それをどう明確な課題を洗い出し、どう対策を講じていくかというところについては、そちらの推進委員会で議論をしていきたいと考えております。２点目の自立支援医療費の、令和２年度の自立支援医療費、前年度よりかなり減少しているです。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私はもう少し、周知だったり改善の手だてを取っていただきたいと思うのですけれども、その点を伺いたいと思います。各グラフの下に書かれているのですけれども、今は７月ですけれど、それでも３月までの実績を出すというのはなかなか困難ということなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"そのため、見込みも上げているというところがあります。感染症対策という体制がかなり強化されてまいりましたので、今年度につきましても、事業所と相談して状況を見ながら実施していくという予定です。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっと進んで１５ページの放課後等デイサービスなのですけれども、これは先ほどの計画書の中にも、報酬が下げられたではないですか。それからさらに、これから要望というのはかなり多いと思うのですけれども、品川区としてはどう考えられているのかについても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"国の報酬の考え方として、重度の方への対応については報酬を上げるというところが、国の大きな報酬改定の考え方だと認識しております。かなり円滑に移行は進んでおりますので、そのまま引き続き継続して進めていきたいと考えております。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"希望する人が希望する日数を受けられないという状況も伺っているのですけれども、さらに開設に向けての制度チェックをお願いしたいと思います。計画相談実人数は約８３０人ということなのですが、およその割合が分かったら、最後に説明を求めました。","respondent":"松山障害者福祉課長","answer":"更新のタイミングで移行の通知を出し、民間の事業所を選んでいただいているという状況ですので、ほぼ順調に移行しております。何％かというのは手元にはないのですけれども、来年の３月末までにはほぼ移行が可能ということになっております。","id":"exchange-027"}]},{"id":"topic-06","title":"新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","agenda":"新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これは、そこから遡ってというか、受けられますよという周知みたいなものというのはあるのでしょうか。それとも、そういう制度がありますというところで、自分が気づかない限りは受けられないという仕組みなのか、その点だけ説明を求めました。","respondent":"池田国保医療年金課長","answer":"昨年度は保健予防課から、感染症にて入院された方についての一覧表みたいなものを頂きまして、確認させていただいたこともあります。ただ、今年度につきましては、まだその辺までは至っておりませんというところが状況です。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それも、今年度もそういう形でされるということでいいのでしょうか。そういうところで、国保医療年金課から、傷病手当金が受けられますよという形での連絡が行くような仕組みになっているということでいいか尋ねました。","respondent":"池田国保医療年金課長","answer":"全件に配布しておりますので、最終的にＰＣＲ検査を受けて陰性になられる方、それから陽性になられる方といらっしゃるかと思います。こういった症状が起きて会社を休んで給料をカットされたという事実があって申請していただくということで、やらせていただいているところです。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"でも、アルバイトは２週間休んでくださいみたいな形で言われた方というのも、傷病手当金の対象になるということでいいのでしょうか。そういう人は自らが、アルバイトの就労日数を傷病手当金ということで申請できるということでいいのか尋ねました。","respondent":"池田国保医療年金課長","answer":"何日から何日と、フルではないかと思いますので、そこの部分の勤務の予定というものを勤務先で書いていただくということをやっていただきます。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"取りあえず２週間休んでおいてくださいみたいな、広報しながわ、ホームページというところで。本当に広報しながわなどでも分かる形での周知を、自ら気づいて申請ができるようにということでの周知を、ぜひお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]},{"id":"topic-07","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これからの見通しというのは、今のところのワクチンの確保分は３５％ということですけれども、その部分は順調に入ってくると考えていいのでしょうか。診療所の分のワクチンの確保の状態というのはどうなっているのか、教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現時点で国から通知があるのは、８月分の今のご説明のところまでです。今後、８月分以降は現在未定という形でお答えはしますが、国は日本全国に発出するというところまでは通知が出ているとご理解いただければと思います。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"集団接種会場から、それから１２０か所のクリニックからということで、かなりの体制が取られたわけです。その辺のところは、７月と同じだけ入ってくるといっても、それが分かってから８月分の予約を取るという形になっていくのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、これに加えて、今後、８月分の予約枠、一部絞っている部分がありますので、絞っている部分をさらに上乗せできるかどうか。９月以降の予約枠をどこまで開放できるかどうかというのは、現時点では慎重に進めていかなければいけないと考えております。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"７月末までに高齢者全員のワクチン接種が終えられるということで、７月末までに終える見通しというのはどんな状況なのかも伺いたいと思います。区としては、今申し上げたような方に対しての、集団接種会場での接種が困難な方に対しての接種に関して体制を取るというところではいかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"７月末に終わる見込みについては、試算上は、７月末までに高齢者の人数分の枠は開放しております。中には一部いるようですので、そういった方に関しては、７月を多少またいでしまう可能性も否定はできないかと思います。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"６０歳から６４歳の方というのが、７月２日から予約受付がされているわけですけれども、こういう年代別に区切っていくわけですよね。まず７月２日から始まって、予約などがスムーズにいっているのか、その点についても説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"所管との調整につきましては、早めに進められるように引き続き努力してまいります。コールセンターにつきましても、１回ではつながらないかもしれませんが、以前に比べたらかなりかかりやすかったという報告も聞いております。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"次々といろいろ大変ですけれども、これからも様々な対応でスムーズにいきますように、よろしくお願いしたいと思います。本当にお疲れさまですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"６４歳以下の方々で、まだ来ないと随分お問い合わせがありましたので。すみません、お願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今の点についてお答えいたします。２日から３日で到着するというお話がありましたので、ぜひお願いしますということで、調整させていただいたところです。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"意見","question":"投票所入場整理券については、またちょっと事情が違うのかもしれませんけれども。その辺りの郵便局との交渉は、やっていただけると思いますけれども、よりしっかりとお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"せお委員","kind":"質問","question":"２点ほど。１回目と２回目の接種の予約、２回目の予約などが違う場所になっている場合というのは、説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"集団接種会場で１回目の予約を取って接種が終わりますと、その場で待機時間中に２回目のご案内をするというスキームになってあります。","id":"exchange-039"},{"speaker":"せお委員","kind":"質問・要望","question":"１回目がモデルナで、２回目がファイザーのものを打ってしまったということがあったようですので、その辺は対策を練っていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、今、区のホームページでは、どうぞ予約をどんどんしてくださいと。ホームページ等で丁寧に区民へのアナウンスをしていただきたいとは思うのですが、以上、何点かお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"それからもっと人数を増やすための予約枠の開放がどこまでできるかというのが、今後、急ぎ検討しなければいけない課題になってまいります。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問・要望","question":"もう対応していただきたいということで、ご要望されていると思いますし、私たちも私たちの立場でしっかり要望していきたいと。どうしてもお断りせざるを得ないということで、それに越したことはないと思いますので、そちらは改めて要望します。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後の枠の開放の前倒しですが、現時点では考えておりません。もしかしたらどこかでストップをかけなければいけないことも検討しないといけない状態になるかもしれませんで、今現在、計算している真っ最中です。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"高齢者施設や障害者施設、障害者のグループホームなども含めて、それから、あと在宅の要介護度の高い方の接種というのは、現状、どんな状況になっているのか、説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"高齢者施設の接種については、時期的にもうほぼ終わる頃になります。それから在宅についても、順次、できるところから、今、スタートしています。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこの体制についても教えていただきたいのと、それからグループホームの職員の方も一緒に接種を受けられているともお聞きしたのですけれども、障害者の施設はどういう方針でどこまでいっているのかというあたりも説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"従事者についてどこまで進んでいるかというのは、１００％かどうかというのは、こちらでは。基本的に余りワクチンで対応するということになっていますので、全ての方が打ち終わっているかどうかというのは、若干不明な部分はあります。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけお聞きしたいのですけれども、集団接種会場と１２０か所の個別接種会場があると思うのですが、残が出ますよね。６回分ずつというのか、例えば、１日２とか３とか残りが出たときは、どういう対応をしているのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"３時から３時半ぐらいの時間に、職員をその会場に派遣して、余らないように打つという流れになっております。個別接種クリニックから連絡をしてもいい保育関係の施設、順次ご連絡いただいて、余らないように打ってくださいというお願いをしています。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"意見","question":"今言った４時頃に連絡を入れて、すごくいいことだと私は思っているのだけど、それはそれでもいいということですよねとの意見を述べました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"あくまでも集団接種会場については区のほうでという形でやってはおりますが、個別接種のクリニックにつきましては、クリニックの先生のご判断で動いていただく分は往々にしてあるかと思いますので、結構かと思います。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3602#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":52701,"voices":138}},{"id":"r03-20210707-8","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"建設委員会","time":"午前１０時００分～午後 ２時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、こうしたことには批判が上がっていますので、その賛否が分かるようなアンケートをやるべきではないかということを伺いたいと思います。重要な点だと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"パブリックコメントなども実施してまいりますので、そうしたところで環境のところもしっかり検討していきたいと、お声を聞いていただきたいです。当然ながら環境の視点も、改定のマスタープランの中ではしっかり検討していきたいと考えています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ウェブのことは、そうしたほうが回答率は上がってくるのではないかということで伺いましたので、もしご答弁があったらお答えほしいと求めました。各地で再開発が行われていくところで、住民からもやめてほしいという声が次々に上がってきているところです。","respondent":"鈴木都市計画課長","answer":"ご自宅がウェブにも対応できる環境にあるかどうかということもあると思いますので、基本は郵送回収という形で考えていきたいところです。基本的にメールアドレスなどは分からない状態ですので、住民基本台帳から抽出を行いますので、そうするとなかなかちょっと難しいのかなと。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"質疑時間ですとかが短くなったりしますので、やはり十分に時間と回数を保障していくべきだということを求めたいと思いますが、いかがでしょうか。区のほうでも８つの目標をつくっていますけれども、そうした幅広い分野にわたってきますので、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"それから、分科会をという話ですが、前回策定したときは分科会を２つほど、防災と都市構造的なことで立ち上げて検討してまいりました。今回は２０年間の計画期間の中間の改定というところですので、今のところ、分科会という形を立ち上げて検討を進めるという考えはございません。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"質問項目の中にコロナ禍でどう変化したかということもありますので、ぜひ、分科会を設置するなど深く議論をしていくべきだと思います。このアンケートを行った結果というのは、どこで報告になるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今のところ、７月から始めて１か月で実施して、その結果の整理ですとかもありますが、基本的には１回目の１０月で、アンケートの結果についてはご提示をしていきたいと、予定としては考えてあります。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"１つ聞き忘れました。学識経験者というのは、何人入られてどういう分野の方なのか、伺います。","respondent":"鈴木都市計画課長","answer":"学識経験者の人数、並びにお声がけをする方々については、今まさに検討しているところです。分野的には、当然都市計画ですとか、まちづくりですとか、そうしたところを専門とされている大学の教授の方にお願いしようと考えています。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"例えば、品川区長期基本構想とは何ですかと。私たちは聞いて当たり前になっていますけれど、マスタープランって何ですかということだと思うのです。","respondent":"鈴木都市計画課長","answer":"事業者のほうはプロポーザルで実施し、パシフィックコンサルタンツ株式会社というところが、受注して契約しています。用語の説明ですが、ところどころには説明をつけて作成しているのですが、今いただいたご指摘は今後しっかり対応していけるように。","id":"exchange-006"},{"speaker":"西本委員","kind":"提案","question":"だから、この事業はどうですかなどと聞くと、賛否を問う形になってしまう。なので、そこら辺を踏まえて、委員会に提案をしていただきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-02","title":"小山三丁目第１地区および小山三丁目第２地区再開発事業事業者による近隣説明会の開催","agenda":"小山三丁目第１地区および小山三丁目第２地区再開発事業事業者による近隣説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"令和３年度中に都市計画手続きを進めていくということでしたが、冬とか、そういうことがあったら伺いたいと思います。対象範囲としては敷地境界から約２９０ｍの範囲ということになっておりますが、チラシはいつ配ったのか、そういったことを伺いたいと思います。","respondent":"多並都市開発課長","answer":"小山三丁目第１地区につきましては、予定しています、それで何回かに分けて開催するという考え方です。今のところ予定されているのは、１２月頃に地域の方々に都市計画案の説明をするような場を設け、今予定されているところです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり大きな１４５ｍの超高層ビルが建つということですから、これはもう広く周知をしてほしいと求めました。の参加率ですとか、どういった方が参加をされているのか、人数なども伺いたいと思います。","respondent":"多並都市開発課長","answer":"準備組合に参加いただいている方は４４.５名、参加率が７５％となっています。委任状というのでしょうか、出されている場合ありますので、その時々によって参加率は違うというふうに認識しています。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"そうした方の意見もしっかりと反映できるようにしていくべきだと思いますけれども、いかがでしょうか。今回の小山三丁目の第１、第２地区の総事業費と補助金の額、伺いたいと思います。","respondent":"多並都市開発課長","answer":"昨日も第１地区のほうの総会があって、いろいろなご意見があったのは承知しています。これは組合施工になりますから組合のほうで検討していくことになりますけれども、現時点は両地区とも算定中と聞いているところです。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"１棟目が出来上がって、どれだけ埋まっているかも分かれば教えていただきたいのですけれども、どのように考えていらっしゃるのか伺いたいと思います。空いたままになってしまうと、このまちを維持していけるのかということもありますので、そこのお考えも伺いたいと思います。","respondent":"多並都市開発課長","answer":"第２地区につきましては、Ｂ－１棟が約６１０戸、Ｂ－２棟が約３８０戸を、現時点は予定しているということで聞いてあります。今回の開発については２地区進めるということでもありますので、また各地区の組合とよく連携しながら、今後も進めていきたいと思っているところです。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"車両を増やすというのはありましたが、ほかにも何か混雑緩和に向けての話し合いをされていることがあったら、伺いたいと思います。それで、Ｂ棟の１と２でこれだけ戸数が違うというのは、どういうことなのかと思ったので、そこも伺いたいと思います。","respondent":"多並都市開発課長","answer":"現在検討されている小山３の１、３の２地区の検討をされる組合だけでなく、連絡会という形で定期的に開催しています。第１地区と第２地区は両方一緒に検討しているところもありましたから、両地区で合わせながら、今後具体的に検討していくことになりますけれども。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"Ｂ－１と２で住戸数が６１０戸と３８０戸ということで、どういうことなのかと伺ったので、ご答弁ほしいと求めました。パルム商店街、武蔵小山商店街のほうにも続いていくのか、今後の計画を伺いたいと思います。","respondent":"多並都市開発課長","answer":"今後の予定ですけれども、今後どのような形で進めていくのがいいかということで、地元の方とお話しさせていただいています。継続的に、より活性化が今後進むようにということで、区も一緒に検討してまいりたいと思っているところです。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"まちづくりとしても、特に林立してくると考えていくのが難しくなると思いますので、こうした超高層再開発のまちづくりはやめるべきだと思います。最後に、地権者、権利者の方で残る方というのはどれだけいるのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"今後の進め方ですけれども、都市計画決定は今年度と、予定ということでお話ししました。今後よく地元の方とお話しさせていただきながら、そこについてはっきりしていくと、そういう段階に今後なっていくというふうに捉えているところです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"本当にここの地域は、これで何棟目ですか。そのためにも、今進めようとされているところの住民たちの思いがどうなのかというところが気になるのですけれど、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"地元説明会を開いて、２００人を超えるような方々にご参加いただいて、ご意見をいただいています。そこはよく丁寧にご説明することが重要だと思っていますので、そういう形で今後も、区としてもよく支援してまいりたいと思っているところです。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"ずっとここに住んでいたいのに、この街並みも歴史があるものですから、愛着を持っておられる方もたくさんいらっしゃると思うのです。このまちはどういうまちを望んでいたのでしょうかみたいな状況になってきてしまうので、今やるべきこと、不安だけが先に立って。","respondent":"多並都市開発課長","answer":"この開発による変化ということで、例えば混雑の点でいえば、先ほどご説明したように東急電鉄との調整をさせていただいています。学校については通学区域が変わるですとか、後地小学校の改築に合わせた対応ですとか、様々な対応をしていただいているところがあります。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、町会との関係とか、やはり初めからそういうものは意識づけをしていただきたいなと。住んでいる方が違うということも往々にしてあることなので、それは配慮して組合のほうとも調整を図ってほしいと求めましたが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"もう一つ、この地区の連絡会を先ほど定期的に開いているとお話ししましたけれども、その中でもやはり町会のお話がございました。今進めた、終わった方々がちゃんと連携しながら進めていこうと、よりよい形になるようにさせていただきたいと思っているところです。","id":"exchange-017"},{"speaker":"大沢副委員長","kind":"質問","question":"あるイベントというのは１週間かけて７月４日に終わったもので、非常に近隣の方、あるいは商店街の方、迷惑されているのです。これは警察のほうになってしまうのでしょうけれども、そういう規制というか、何かかけることはできないのか尋ねました。","respondent":"多並都市開発課長","answer":"今回の第１地区でも、それ以外の目的で使われる方々が、この開発の広場と連携できるようにするのが一番かなと思います。警察との連携については、防災まちづくり部ともよく連携しながら、ちょっと考えていきたいと考えています。","id":"exchange-018"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"やはりまちづくりですから、そういう副産物についてもいろいろと考慮に入れながら、まちづくりを進めていただきたいと思うのです。答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"東五反田二丁目北地区に関する都市計画案","agenda":"東五反田二丁目北地区に関する都市計画案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そうしたお知らせを、こうした説明会もやっていくべきだと思いますが、いかがでしょうか。２月に開発計画の説明会が実施されたということでしたけれども、ここではどのような意見が出たのか、伺えればと思います。","respondent":"多並都市開発課長","answer":"この件で言えば２月には事業者の方、要するにこの事業を進める方が、周知で地域の方へ説明会を開くと。その他の意見ということで、建物の工事に当たっては近隣への十分な説明をしてほしいですとか、そういうご意見があったということで認識しています。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"３００％から５２０％になったということですが、今までと同じなのかどうか、そこもお答えほしいと求めました。高さの最高限度についてはここに書かれていませんが、Ａ地区とＢ地区の違いといいますか、なぜ書かれていないのかを伺いたいと思います。","respondent":"多並都市開発課長","answer":"高さについては１００ｍがもともとで、これは先ほどのと変わらないということです。Ｂ地区で総合設計で予定しているところを追認する形で、あえてその計画については設定しないという取扱いにしていると、そういうことです。","id":"exchange-021"}]},{"id":"topic-04","title":"その他の(1)所管質問","agenda":"その他の(1)所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この個々の選択の自由とはどういう意味か。選択できないと思いますが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"今、平成２６年に市街地再開発準備組合が設立し、これまで再開発に関する検討が進められてきております。現在、準備組合の中で、現居住者の生活再建に配慮した事業スキームとなるよう検討されているところと聞いております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、残る選択というのはできないことになると思うのです。その選択の自由というのが実際にはないのではないかということでお聞きしましたので、その答弁をしてほしいと求めました。","respondent":"多並都市開発課長","answer":"８割がいいかということもありますけれども、やはり多くの方はご賛同いただいているという説明も受けているところです。それをご検討いただきたいということで、それを皆さんでお話しいただきたいというのが、区の考えです。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"８割がこの計画を理解しているということでしたが、２割の人は納得してないわけですよね。区としては皆さんで話し合ってという話ですが、残りたいという人がちゃんと残れる案にしていくことが必要だと思いますけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"区が考えるというより、準備組合の方がご自由に、どういうプランにしていくのか考えていらっしゃっている途中というふうに認識していますから。形にしていくかというのが、このまちづくりの肝かと思いますので、そういう考えで区としても思っているところです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"意見","question":"話し合いということですが、その方向でもうほぼ進んでいるわけですよね。区としても、この話し合いを目指して設計していく、そういったことが必要だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-05","title":"に戻りまして、(4)区内で初めて確認された「クビアカツヤカミキリ」","agenda":"に戻りまして、(4)区内で初めて確認された「クビアカツヤカミキリ」","exchanges":[{"speaker":"塚本委員","kind":"確認","question":"発見が６月１７日で、区からいろいろ発信されて、私のところにもそういうものがあると届いて、確認した覚えがありますけれども、それ以降区内で区民等から、発見等の通報等はありましたか尋ねました。","respondent":"河内環境課長","answer":"こちら、説明が足りずに申し訳ございませんでした。２２日には、それ以降は、特に発見などの情報は寄せられていない状況です。","id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"では、当面、何か拡大している雰囲気というのは今のところつかんでいないのかと思うのですけれども、これは日本の中で今、結構被害が出ている地域とかはあるのか尋ねました。","respondent":"河内環境課長","answer":"今後も、そういったものを目標にしながら、しっかりとした対策を継続していきたいと考えているところです。もう一息ですので、しっかりと対応を進めてまいりたいです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"確認","question":"先ほど少し説明がありましたけれども、以前に確認された足立区、江東区でのその後の被害というのはどうだったのか伺いたいのと、広域的、継続的な警戒が必要だということなのですけれど、なぜ必要なのか、その理由を伺いたいと思います。","respondent":"河内環境課長","answer":"当時、やはり広域的な取組で情報共有しながらやりませんと、特に目黒川沿いの桜など地続きでつながっているところもあります。そういったところも踏まえまして、しっかりとした対応を進めるべく、広域的な声かけもしながら取り組んでいるところです。","id":"exchange-028"}]},{"id":"topic-06","title":"第１１次品川区交通安全計画（素案）","agenda":"第１１次品川区交通安全計画（素案）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これまでの第１０次品川区交通安全計画の課題と、今後の対策を伺いたいと思います。そういうことも関係しているのかなと思ったのですが、コロナ禍のもとでの関係性といいますか、もしありましたら伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"１点目、第１０次期間中における事故の状況等について、ご説明します。２９年、今説明をさせていただきましたような自転車の事故がだんだんと増えていったというところが、主な原因であるというふうには考えてあります。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"大体１００ページの冊子ですから、そのパブリックコメントに当たってぜひ説明会を実施していただきたいと思うのですが、いかがでしょうか。２６号線は都道ですか、ぜひ設置を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"そのときに必ず信号機の現示サイクル等につきましては検討がなされるものと思いますけれども、安全と円滑が大前提ですので、そちらを踏まえた対応を。パブリックコメントに関する説明会の実施の関係ですけれども、現在のところ考えてございません。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"それから、この６つの重点の６、「新しい生活様式」への対応ということで、２つほど書いてあるのですが、よく分からないのです。オンラインを使った交通安全教育ということが、「新しい生活様式」への対応なのかと思ってしまったのですが、その辺も説明を求めました。","respondent":"川口交通安全担当課長","answer":"例えば歩道の通行区分が、巡行する左側しか通行できないというような法改正はあったのですが、大きな法改正はございませんでした。２点目の「新しい生活様式」への対応ということですけれども、これは恐れ入りますが、別紙２の４１ページをお開きいただければと思います。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、教育というと１番とかぶってしまうのではないかとかと思っているので、何かほかにやるということがあればご紹介いただきたいです。やはり注視していかないと、事故が非常に多くなっていく可能性があると思っているのですが、その辺はいかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"実施事業者と区側の担当者で定期的な会議が行われておりますので、事故の発生状況等を情報共有しながら、対策をこれから進めていくです。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"非常に利用価値のある仕組みではありますが、安全性を考えたときにはやはり注意して見ていかないと、大きな事故になってしまう可能性があります。事前に準備を進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"自転車の交通安全というところについて少しお伺いしたいのですけれど、これまでのご説明の中で、自転車の事故が増えていますと。そういったことも自転車活用推進計画と絡めてやっていかないといけないのかなと思うのですが、その点についてお考えをお聞きしたいと思います。","respondent":"川口交通安全担当課長","answer":"信号無視ということで、これは自転車の通行環境の整備とは直接関係ない、一つ見えるところではないかと考えています。今回の第１１次計画につきましては、そちらについてはしっかりとした、区としての整合性を図っていきたいと考えております。","id":"exchange-034"},{"speaker":"芹澤委員","kind":"質問・要望","question":"自転車のヘルメットの考え方というのは、勉強不足で恐縮ですが、そもそも何歳ぐらいまでつけるものなのでしょうか。このヘルメットをつけるように普及啓発と言いながらも、この基準というのがよく分からない部分もありまして、その２点を説明するよう求めました。","respondent":"川口交通安全担当課長","answer":"第６３条にあるのですけれども、また看護する責任のある方々はヘルメットをかぶらせるようにしなければならないというふうに書いてあります。区としても、ヘルメットに関する利用の普及啓発、情報発信に努めているところではあります。","id":"exchange-035"}]},{"id":"topic-07","title":"大井坂下公園改修工事","agenda":"大井坂下公園改修工事","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の改修でその喫煙所はどうなるのか、なくすのか、伺いたいと思います。すみません、不勉強で申し訳ないのですが、コミュニケーションサインというのはどういうものなのか、ご説明いただけますか。","respondent":"高梨公園課長","answer":"１点目のご質問の喫煙所ですが、新型コロナウイルス感染症拡大防止の対応のため、昨年４月から、現在の喫煙所は使用を休止している状況です。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"これは子どもたちのアイデアを活用したということなのですけれど、どういう議論からこういう形にしたのか、お聞きしたいと思います。切れとは言いませんが、少し枝を切るとか、明るいイメージが欲しいと思う公園の一つかなと思っているのですが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"そちらの対応といたしまして、明るく、今回の整備をしてまいりたいと考えています。防犯上の措置といったことにもつながりますので、明るく、皆さん安心してお使いいただける公園となるのではないかと考えているところです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"せっかくつくられるわけですから、本来、健常者と配慮の必要な方々が一緒に遊べるというのが大きな目標だと思うのです。見通しのいい形にしてもらいたいと思うのですが、１番目のほうだけ、ご答弁をお願いします。","respondent":"高梨公園課長","answer":"ただ、大丈夫なのかといったところは、ユニバーサルデザインに配慮した使える遊具といった形で整備してまいりたいと考えております。日々の巡回点検、管理のほうも抜かりなく、しっかりとやっていきたいと思ってあります。","id":"exchange-038"}]},{"id":"topic-08","title":"マイガーデン西五反田の利用者募集および利用開始","agenda":"マイガーデン西五反田の利用者募集および利用開始","exchanges":[{"speaker":"西本委員","kind":"質問","question":"それで抽選に漏れると、皆さんがっかりされるのです。なので、増えることはとてもありがたいと思っているのですが、今後、何かこういう形で整備していくという計画はあるのか尋ねました。","respondent":"高梨公園課長","answer":"希望される方々それぞれに行き渡る量の農園が準備できると一番いいと考えているところですが、土地の少ない品川区においては、確保が難しい状況です。現在のところ、西五反田に続くマイガーデンの予定地は計画されてございません。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"学校の屋上菜園の活用ということでお願いしたことがあって、それは今どうなっているか、山中小学校とかで一応やっていただいたのですけれど。とても皆さん喜ばれるのではないかと思うので、それもちょっと研究していただきたいと思っているのですが、そういう考え方はいかがか尋ねました。","respondent":"高梨公園課長、藤田防災まちづくり部長","answer":"できるだけ菜園ができるところが増えていく方向で検討できればいいなと思ってありますが、下から上に持って上がらなければならないということで。緑化についてもそうですし、菜園についても可能性があるものと考えておりますので… 今までもマイガーデンについて、屋上等の展開というのは検討してきたのですが、なかなか施設の管理上の課題が多くあります。","id":"exchange-040"},{"speaker":"西本委員","kind":"提案","question":"そこで、学校の屋上というのを提案して、土などは改良されていて、本当に薄くても作物が育成できるというものもあるのですね。可能なところを見て、やはりマイガーデンはいい制度だと思っているので、それを広げていただくように研究をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"芹澤委員","kind":"質問・要望","question":"所管が若干違ったらおっしゃっていただきたいのですけれども、三年ぐらい前に議会の質問であって、それはどうなったか分かりますか。","respondent":"高梨公園課長、稲田土木管理課長","answer":"花であるとかプランターでの活用といったことについては、一定の可能性があると、東京都の所管事務所から聞いているところです。実際に具体的な場所と中身を東京都とお話が進められると… 都道の２９号線の用地をテラス営業の手法を使いながら、小さなスペースですが、そういうのができているのは私も確認したりしました。いろいろな形で、先ほど高梨課長も言いましたけれども、研究しているという状況があるようです。","id":"exchange-042"}]},{"id":"topic-09","title":"下水道管老朽化対策事業（再構築事業）","agenda":"下水道管老朽化対策事業（再構築事業）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今回はこの東五反田なのですけれども、品川区全体でどのぐらいの老朽化の進み具合というか、計画というか、そういうものはどういうふうに考えられているのか尋ねました。","respondent":"栗原河川下水道課長","answer":"品川区内の第１期再構築エリアにつきましては、目黒川の北側が該当いたしまして、こちらの事業を東京都下水道局と連携して実施しております。進捗につきましては、おおむねそちらのエリアの３割程度が完了したという状況です。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ずれるかもしれませんが、品川区全体に対する老朽化対策というのは、何か計画とかはあるのか。これは東京都の受託になると思うのですけれど、品川区はどういうふうに考えられているのか尋ねました。","respondent":"栗原河川下水道課長","answer":"先ほど述べましたように第１期再構築エリア、目黒川の北側は、令和１１年度までに東京都下水道局と連携して実施していく予定です。南側のエリアにつきましては第２期再構築エリアということで、令和１２年度以降に実施していく予定と東京都下水道局から聞いております。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"東京都が全て決めるのですか、全体的に下水道のリニューアルといいますか、対策というのは何かとられているのでしょうか。そのときに品川区内の下水道については大分進んでいますというふうに聞いたのですけれど、どういう状況なのか尋ねました。","respondent":"栗原河川下水道課長","answer":"品川区は東京都から下水道事業を受託して進めているということもございまして、かなりスピードアップを図って対策を実施してきているというのが現状でございまして、進んでいるというご認識は正しいご認識かと考えています。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問・要望","question":"管きょ更生工法というのを確認させていただきたいのですけれど、かつてより排水能力が上がるという捉え方でいいのでしょうか。今５０ｍｍ対応というのを東京都は目標にやっていますけれども、そういうところに関係してくる話なのか、確認したいと求めました。","respondent":"栗原河川下水道課長","answer":"１時間５０ｍｍの降雨に耐えられるような管の大きさかどうかのチェックを行いまして、更生工法でも耐えられる場合は更生工法で実施いたしまして。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4326#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":51092,"voices":139}},{"id":"r03-20210707-9","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"文教委員会","time":"午前１０時００分～午後 ０時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)学校改築の進捗","agenda":"はじめに、(1)学校改築の進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この利用方法について伺いたいのと、今後の新築校舎には大体入れていくという方向なのか、伺いたいと思います。小学校の学級編成も全学年３５人になっていくわけですけれども、１枚目の資料で提示された学校で言うとどこになるのか、伺いたいと思います。","respondent":"有馬庶務課長","answer":"３５人学級への対応ですけれども、浜川中学校につきましては、いわゆる３５人学級にという話を受けて計画をしたものではありません。これから設計をしていくということですので、そういったことは加味して進めていくことができるというふうに考えているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"あるいは２０人程度学級、２０人程度の学級になるような学級規模にすることも、私は必要だと考えているのですね。恐らくこうなるだろうという、こういう流れを踏まえるべきだと思うのですけれども、いかがか尋ねました。","respondent":"有馬庶務課長","answer":"ただ一方で、限られた敷地の中で、どういった建物を建てていくかということも、あわせて検討していきたいと考えています。品川区の学校では、有効な校舎も建てていきたいというふうに考えておりますので、そこは慎重にいろいろ検討して進めていきたいと考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"法がそうなればということなのですけれども、それだとやはり遅いと思うのですよね。教室に４０人詰め込んだら、それは１人当たりの日常的に過ごすスペースがものすごく狭くなるので、ぜひそれは強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"今質問するべきかどうか分からないのですけれども、その辺がどうなっているのかということと、今の段階で考えられているのか説明を求めました。","respondent":"小林学校施設担当課長","answer":"それと、雨水ならびに太陽光パネル、これにつきましては、エコスクールというものがありますので、それを視野に入れて検討を進めてまいります。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうなのでしょう。あったのでしたら、ぜひ継続をお願いしたいのですが、いかがか尋ねました。","respondent":"小林学校施設担当課長","answer":"一般的に１立米であるとか、これは１トンぐらいの、住宅に主に使うところが多いです。２０トンから３０トン、それは地下のピットに入れて、雨水槽ということで設けるのが一般的です。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"学校改築の考え方についてお聞きしたいのですけれども、１年に１回ずつ学校改築が計画として繰り広げられていくのですけれども、それを教えていただけますか。","respondent":"有馬庶務課長","answer":"改築の進め方、考え方ですけれども、この３つを大きな柱として改築する学校を選定している次第です。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"３５人学級になれば、戸越公園の駅前が開発だという話になってくると、そういうところには今度また人が集まってきますよね。そういったものと、要は教育委員会との連携というのですか、そういったものというのはしっかりとれているのか尋ねました。","respondent":"有馬庶務課長","answer":"何戸なのかというようなことの情報を、学務課と一緒にもらって、それを計画に生かしていくというようなことで取り組んでいるところです。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"スケジュールで８月に着工となっているのですけれども、屋根とかそういうのはないと思うのですけれども、坂上側に確かマンションがあるのですよね。この辺のプールが見える状況なのかどうかという、配慮されたつくりになっているのか、その辺を改めて説明を求めました。","respondent":"小林学校施設担当課長","answer":"いろいろな検討の中で、その中で、この敷地についてはこのような配置が一番ベストといった考え方で計画はしたものです。目隠し的なものを設置できるならばそういうふうなものを作るとか、フェンスを作るだとか、そういうことを考慮してやってまいります。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"トレンドというか、私たちが通っていたときは学校のアイコンというのはでこぼこで、凸型と言うのでしょうか。このあたりについての方向性、大きい部分かと思いますけれども、何かご答弁できる範囲があれば教えてほしいと求めました。","respondent":"有馬庶務課長","answer":"我々も認識しているところではありますけれども、こうして急激に人口が上がってくるとそれに対応しなければいけないということなので、今あります。できれば計画を出せればいいのでしょうけれども、まだ人口の動きが激しいものですから、なかなか難しいと考えております。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"ですから、自分たちが、今の子どもたちがいるときには無理かもしれないけれどもというのは必ず枕詞で皆さんつくのですよね。伺う中で、要望ですけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"確認","question":"だけど、もう少し交流がしやすいような配置ということにすべきではないかと思うのですが、何か特別なお考えがあってのことなのでしょうか。そこだけ確認したいと求めました。","respondent":"小林学校施設担当課長、矢部教育総合支援センター長","answer":"各部署からご意見をいただいて、総合的に平面計画をいたしました。特別支援学級もそれぞれの子どもさんの程度とか、いろいろな考え方ができますので、このような配置計画にしたところです。 教員の考え方もありますので、あまり高い階ではなく、これは２階になっていますかね。交流しやすい場所で配置して、さらに少し静かなところで学習できるというような、間をとったような計画になっていると思います。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"いろいろなお考えがあるということは分かりました。やはり社会に出たら一緒に暮らすのですから、ぜひ重く見て、学校の設計もしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"令和４年度新入学者の受入枠","agenda":"令和４年度新入学者の受入枠","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"学校施設やハード上の制約もあるのか伺います。私としては、３５人ということの学級量の選択を想定して受入枠というのを作ったほうがいいのではないかと思うのですけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"学級数の設定の考え方です。例えば、３０人ですとか３５人と小さく設定しますと、法律どおり設定しているものです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"少人数学級実現を妨げている要素というのは、やはり減らすべきなのではないかと思うのですけれども、いかがでしょうか。こういう受入枠というのを示すというよりも、そういったところをしっかりと注力すべきなのではないかと思うのですけれども、あわせて伺います。","respondent":"勝亦学務課長","answer":"ここについては検討できるものは研究していきたいと考えております。学事制度審議会等々でご意見をいただきながら変更してきた経緯もありますので、調査研究はしていく必要もあるかと考えております。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりぜひ、労力と時間と工夫、それを費やしていただきたいなというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"例えば中学校だったら２年生、３年生になったときに、転出というのが傾向としてあるのかというところを伺えればと思います。お願いします。","respondent":"勝亦学務課長","answer":"転入の中には様々な学年の方が入ってまいりますので、そこの数字を見込んだ上で受入れをするような形で、実数としては入ってきている状況です。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"余りそこを詳しくは把握されていないということなのでしょうか。それ以外の一般的な、状況の中で大体傾向としては、推移で言うと１年間に入ってくるのが大体このぐらいなどというデータはどうなのか尋ねました。","respondent":"有馬庶務課長","answer":"５年生が２,４８１人だったのが、２,４９３人だったというようなことになっておりまして、そういう傾向があるというふうに自分は捉えているところです。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。なぜ確認しているかと言ったら、では５人ではなくて、そのあたりは少し精緻にご検討いただければなというところを要望として申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"その他のうち、(1)所管質問","agenda":"その他のうち、(1)所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"「ワクチン、大規模検査、学校連携観戦プログラムへの参加中止を求めるというご質問があったと思います。区としてのお考えを求めた質問だったと思うのですけれども、改めて、品川区の教育委員会としてどのようにお考えか伺いたいと思います。","respondent":"工藤指導課長","answer":"これまでも学校連携観戦につきましては、私どもは感染症また熱中症対策等を講じながら準備計画を進めていたところです。その詳細について、さらに都教育委員会に照会・確認を行っているところでございまして、現在検討をしています。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"昨日来たということですか。学校の先生の負荷を現場ではどの程度考えているかとか、そういうことを考えた上で結論をお出しになるというふうに考えてよろしいのか尋ねました。","respondent":"工藤指導課長","answer":"これまでも様々な、例えば学校からは校長会等も通じながら、様々な学校の考え方も集約、聞いているところです。安全・安心に行うというのが前提ですので、それらを含めまして、現在検討を行っているです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"学校連携観戦事業に係る乗車券手配委託の制限付き一般競争入札が求められていて、間もなく決まる、７月９日までが入札期間というふうになっています。例えば中止となったときには、それを中止することができるような仕様にされているのかどうか、その辺についても確認したいと求めました。","respondent":"工藤指導課長","answer":"その上で、私どもは検討を進めているところです。進めながら、今、昨日いただいた情報を基に検討しているというのに含まれるというところです。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つ、校長会を通してということですけれども、なるべく現場の直の先生方のお声も聞いてほしいと求めました。ただ、その仕様の中身については所管がきちんと決めていくということですので、そのことについて伺いました。","respondent":"工藤指導課長","answer":"それを進めている中では、様々な検討を今進めている中で、そういったことも含めながら調整も勘案しているところではあります。それが検討の中にも入っているというところです。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"こういう契約のことなども考えて、なるべく早い時期に、区としてもうこれは中止というふうに決定してほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"子どもの観戦を中止してほしいという区民の声は、現在何件ぐらい届いているのか伺いたいと思います。観戦の是非について意見を聞いたのか、聞いたとしたらどのような意見が挙がったのか、それぞれ伺いたいと思います。","respondent":"工藤指導課長","answer":"この実施に関してのところですが、今回の連携観戦プログラムですが、特にこの品川区の中でも積み重ねてまいりました。それにつきましては、繰り返しですが、今検討を進めているです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"そういった声も聞いたので伺いますが、そういう話もしている人がいたのですけれども、事実はどうなのでしょうか。その辺のルールがどうなっているのか伺いたいと思います。","respondent":"工藤指導課長","answer":"あわせまして、予定している人数ですが、区立学校、幼稚園の５歳児も含めまして、約２万２,０００人を予定しているところです。今私どもが検討している中では、実際に使用駅も確定したことでの詳細を、今またさらに照会をかけながら検討しています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"通勤ラッシュの時間帯に移動してしまうような午前中の観戦というのがあるのかどうか、その辺を後で確認させてください。それと、併せて伺いたいのは、ここでは公共交通機関を使用した学外学習活動などの考え方はどのように位置づけられているのか伺いたいと思います。","respondent":"工藤指導課長","answer":"こちらも含めて、今検討の事項に入っているところです。７月１１日まで措置期間となっておりますが、それがその期間にかかる場合には、あくまでもガイドラインに従ってというふうに考えているところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"確認","question":"これが、確認なのですけれども、五輪期間まで延長継続された場合は、学校連携観戦は中止するという考えでよろしいのか伺いたいと思います。出席停止と欠席というのは何が違うのかなというのが分からなかったので、それも併せて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、今の時点で、やはり私は、早い時期に決断をすべきだと思います。改めて品川区教育委員会として、中止に向けて必要な手続きをするよう求めますけれども、最後にいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"区立児童相談所開設に向けた進捗状況","agenda":"区立児童相談所開設に向けた進捗状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これは６月２日の検討委員会の議論を経て作成されたものなのか、当日検討委員会に出された資料なのかというのが分からなかったので、お伺いします。３つ目は、これが児童相談所の設置でどういうふうに変わっていくか、充実していくのかというのもお聞かせほしいと求めました。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"３つ目の、要保護児童対策地域協議会の意見に関する真意という、補足の説明のところですけれども、すみません。こちら、児童相談所と子ども家庭支援センターの役割分担をしてケース対応を行ってまいりますので、そういった進行管理の面。 ３層目としまして個別ケース会議として協議会ケース会議ということで実施をしています。２点目にございました今後の運営の形態等々についてですけれども、どういった形がいいのかというのは、これから考えてまいりたいと考えております。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"疲弊のケースの度合いに応じた配慮というのも必要ではないかと思うのですけれども、その辺は今どのようにお考えなのか伺いたいと思います。３つ目は、この運営計画検討委員会が非公開という、委員会にはこういった形で報告があるのですが、その理由は何かというのを伺いたいと思います。","respondent":"山下子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"私からは、１点目の建物の関係についてお答えいたします。子ども家庭支援センター、設置・運営をしているのですけれども、新庁舎も含め移転をするような形での考え方をしております。 ２点目以降の質問にお答えいたします。子ども家庭支援センターに限らず、庁内関係部署でのジョブローテーションが必要と考えておりまして、現在協議を行っているところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは、児童相談所の担当児童福祉司ということになると考えてよろしいのか、伺いたいと思います。その点において、児童相談所と子ども家庭支援センターはどのような役割を果たしていくのか、改めてそちらについてのお考えを伺いたいと思います。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"児童相談所と子ども家庭支援センター、そういった曖昧にならないような仕組みというのを検討していかなければならないと考えているところです。育児相談、子育て相談といった寄り添い型支援のほうと役割分担をしながら… 子ども家庭支援センターが要保護児童対策調整機関ということで、品川区子ども家庭支援センターであるのかというのは、しっかりと把握をしています。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"１人で抱え込まなくていいのですよという、そういう環境というのは、実はすごく大事かなと思っていまして。子どもをどう見るかというところに大人の理解というのがすごく大事だと思うので、その辺も併せて、ぜひ頑張っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"松本委員","kind":"質問","question":"この運営計画検討委員会が非公開のところなのですけれども、やはりこれは公開はしていくべきだと私は考えています。児童相談所をこれから作るということについて、やはりそれはおかしいのではないかと思うのですが、そこについてもう一度ご答弁をお願いします。","respondent":"加島児童相談所移管担当課長","answer":"それから、議会になるべくそのままお出しするような形をとりまして、委員会としての公正性・透明性を保っていきたいと考えているところです。","id":"exchange-033"},{"speaker":"松本委員","kind":"意見","question":"議事録の部分は公開すべきだと思いますし、当委員会に対する公開だけではなくて、きちんと品川区のホームページ上もこういう会議が行われていると。","respondent":"加島児童相談所移管担当課長","answer":"２点目からのお答えになるかもしれませんが、現在、有識者会議につきましては、確かに委員ご指摘のとおり、ホームページ等には掲載しておりません。そこのところの扱いについては、今後、委員長とも相談が必要と考えております。","id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"委員長および委員５名ということなのですけれども、これはやはり、どういう人たちが検討したのかというところは重要になってくると思っています。どういう方たちを選任しているのかというところはきちんと公開されたほうがいいのではないかと思いますが、その点はいかがか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"弁護士につきましては、こちらは他区のほうで子どもの権利擁護に関わっていらっしゃる弁護士の方に委員の就任をお願いしたところです。お名前等、この委員会を通じて区立児童相談所設置・運営計画を完成していくに当たり、そこも含めて委員長と相談をしてまいりたいと思います。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問・要望","question":"他区の状況と合わせて、そのあたりの、やはり説明責任の在り方というのは考えてほしいと求めました。ちなみになのですが、この６月２日に行われた会議ですけれども、会議の開催時間、どのくらい時間が使われたのかというところもお願いいたします。","respondent":"加島児童相談所移管担当課長","answer":"会議の開催時間について、６月２日は１５時から始めまして、１時間半強ほどご意見をいただいたところです。","id":"exchange-036"},{"speaker":"松本委員","kind":"質問・要望","question":"最後は本当に要望で。このあたりの情報というのは公開していただきたいと考えていますので、引き続き、在り方を考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区の場合で伺いましたので、ぜひ進めていただきたいのですが、そこをきちんと位置づけていただけるといいかなと思います。これからということであるならば、ぜひそういうことをここで深く議論していただきたいと思うのですけれども、その辺についていかがか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"各機関がそれぞれ、自分たちが当事者なのだということを認識してもらう、その必要性があるというご意見をいただいたところです。意見表明支援の件につきましても、今現在、国が詳細の検討を行っていると聞いておりますので。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"一応、意見だけ言わせていただきたいのですけれども、やはり会議の公開というのは進められるべきかなというふうに思います。最後は意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"松澤委員","kind":"質問","question":"２層性というか、私も勉強会などに行かせてもらうと、お聞きしています。そういった中で、やらないということはないでしょうけれども、どういった部分でそういう連携評価をいうのを図っていくのかというのを説明するよう求めました。","respondent":"加島児童相談所移管担当課長","answer":"先行区のほうでは、児童相談所と子ども家庭支援センターが併存している区が世田谷区です。世田谷区のほうでは、両機関の共通の認識といたしまして、ケースが狭間に落ちることのないような体制を今後検討していきたいと考えています。","id":"exchange-040"},{"speaker":"松澤委員","kind":"質問","question":"東京都がやっている中で、そういう情報が全くつながらなくなったり、要は都と区の連携というのですか。そういった部分に関して、これも大切ですけれども、東京都との連携という部分においてはまたどういう感じでやっていくかというのを説明するよう求めました。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"我が区においても、その取組につきましては実施に向けて検討が必要と考えているものです。どういうアプローチができるかというのを考えていく、そのためにも、きちんと情報は漏らさずに引継ぎをしていくことが重要だと考えております。 やはりそういった役割は、介入的な立ち位置として、児童相談所が担わなければならないところがあります。その保護者の方々を支援するという役割がありますので、私どもとしましては、一体型ではなく併存型での運営を検討しています。","id":"exchange-041"},{"speaker":"松澤委員","kind":"質問","question":"実は、またその関係性を一から作っていかなければいけないというのは、特別区の中では大きな課題となるのではないかと思っています。職員の異動の周期、そういった部分も少し長く見るということも検討の１つなのかなと思っているのですけれども、その辺はどうか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"通知等により、児童福祉司においてはスーパーバイザーは経験年数５年以上、こちらはカウンセリング等の経験年数１０年程度と言われているところです。そういった道を両立させていくようなことも、今後、人事部門と協議していかなければならないと考えております。","id":"exchange-042"},{"speaker":"つる委員","kind":"提案","question":"そういったところも伺いながら、また提案をさせていただいて、こういう進捗を教えていただきました。令和６年になりますけれども、また体制になっていくのかというのを、概要で結構ですので改めて説明を求めました。","respondent":"加島児童相談所移管担当課長","answer":"保護者支援、区として主体的に一貫した支援が可能となるというのが、まず１つ大きなところだと考えています。緊急対応の前段階から、子どもと家庭に支援が届くよう、児童虐待の防止・早期発見をより強化していけると考えております。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"この別紙２の図もありますけれども、子ども家庭支援センターの役割分担と言いましょうか、連携の在り方というのですか。このあたりというのはどういうイメージを今後持って進めていくのか説明を求めました。","respondent":"加島児童相談所移管担当課長","answer":"虐待対応というのがメインで言われることが多いですけれども、非行ですとか障害ですとか、子どもに関するあらゆる相談に対応していくべき部署です。","id":"exchange-044"},{"speaker":"つる委員","kind":"提案","question":"別紙１でもあるのですけれども、安藤委員のところですか、やはり経験と疲弊は併存すると思うのですよね。５年かけて、今どういう力点でやっているのか、説明を求めました。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"第１回は他区の一時保護所の課長さんに来ていただきまして、児童相談所における一時保護所との連携についてといった講義もしてもらいました。確保が難しいところですけれども… そういった観点から、区としまして、児童相談体制の窓口を強化する意味で、昨年度、令和２年４月より子ども家庭支援センターを設置したところです。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう育成についても、開設した後、そこをぜひ重点的にやってほしいと求めました。悪いかという、この子ども家庭支援センターも含めてなのでしょうけれども、そういう愛称みたいなものをつけていく考えというのはどうか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"地域の住民の方に愛着といいますか、親しみを持って呼んでいただけるという点では非常に重要な考えだと考えております。はあとポートという愛称をつけておりますので、そういった試みについても、今後区のほうで研究してまいりたいというふうに考えております。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5038#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":45033,"voices":128}},{"id":"r03-20210707-5","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"総務委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"このコロナは大変なことですから、あるいは心構えを持つ、そういう態度で補正予算を区としても全力でつくっていかなければいけないと思うのです。ワクチンだけでコロナを抑え込めるわけではないですから、それを保護していくということも、依然としてやっていかなければならない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"おくの委員","kind":"意見","question":"１つは、７月２日が予約開始日ということになっているのですけれども、その予約開始日になっても接種券が到着していなかったという声を聞きました。それで……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それで、その迅速な接種というところで、十分なことができたのかというところ、その点を伺いたいと思います。あるいは、介護・障害者施設の新規入所者に限定した、６月に２回やるとか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"今こそ強く国に対しても求めるべきだし、支援金のようなものを考えてしかるべきだと思うのですけれども、考えなかったのでしょうか。４点目、コロナを封じ込めていかなければいけないのだという戦略目標を持つべきだと思うのですけれども、いかが考えていらっしゃるのか尋ねました。","respondent":"黒田財政課長","answer":"２点目の、必要な検査を必要な時期にできるというところで、対応しています。３点目の、商業・ものづくり課のほうでも様々対応を行っておりますが、区にできることについては対応していきたいと思ってあります。","id":"exchange-004"},{"speaker":"おくの委員","kind":"意見","question":"その郵送にかかる日数を計算しないで予約開始日を設定したというところに、不備があったのではないかという区民のお問合せだったのです。要するに、細かいことになりますが、６月２９日に……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"それで、４点目、コロナを封じ込めるという戦略目標を持った上で決めるべきではないかと私は思っているのですが、その点はいかがでしょうか。その点に、答えるよう求めました。","respondent":"古巻総務課長","answer":"ワクチン接種関係、７月から２名の職員を異動で追加しておりますし、また兼務発令で３名の職員を兼任させております。そういった意味で、コロナ対策についてはしっかりと進めていると認識しております。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"どういった議論があって、今後の委員会運営の上で少し検討していただきたいということを、要望したいと思います。その増設というのは、やはり予約のための増設という、それだけの機能ということで間違いないのか、確認したいと求めました。","respondent":"黒田財政課長","answer":"１００回線大丈夫ということで、コールセンターで対応できる内容については、かなり対応できるのではないかなと考えているところです。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"でも全体的なことを考えたら打ったほうがいいのも分かるのだけれども、どうしたらいいのだろうと、そういった相談も来るのです。そういうのもこのコールセンターで受けられるのか、それはまた別なのかというところをお知らせいただきたいのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、この中に、また今も少しずつされていますが、相談窓口を周知するようなポスターの掲示とかというのは、含まれていないのでしょうか。そこの確認をさせていただきたいのと、要望として、それだと自分がどこに当たるのかが分からない。","respondent":"黒田財政課長","answer":"いわゆるＳＯＳカードの配布等を含めまして継続的な事業で行っておりますので、今回の補正予算では、経費として計上させていただいているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望でとどめます。具体的になってしまうと答えられないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"そのバナーでということですが、この事業の契約先というか、この方たちはこれまでの実績とかがあって、そのバナーによって、これまで子どもたちや自死を考えていた方たちとつながって、ケアというか、次につなげることができたという、そういう実績があるのかというところの確認はできますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"１０月までこれはお示しをされていて、今回も１０分の１０が出ているのだけれども、１０分の１０出してくれるものなのか。その辺はどういうやり取りがあって、どういう考え方の下で、こういうお金がこういう対処になっているのかという考え方を聞きたい。","respondent":"黒田財政課長","answer":"１０分の１０になるということですので、国庫が具体的にどのように配分されるのかというのは、今後のことになろうかと思います。もしいわゆる特定財源がないとすると、その場合については、必要な事業は一般財源を取り崩して行うというような考え方で予算編成をしています。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"ここまでやって、これ以上行ってしまったらとかでも、何か手を当てられることがあったら手を当ててほしいと思います。使うべきところというのは一般財源の活用も考えた上で、この難局を乗り切っていただきたいということは、要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"結局全世界でこのワクチン接種を６割、７割の人が受けるまでは、対応をよろしくお願いしたいと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"たけうち副委員長","kind":"質問","question":"もう１０年ぐらいになるのではないかなと思うのですけれども、そうすると、１０年だと２００万円ですよね。この方に限らず、長年たしか同じ金額をずっとやっていただいているような気がするので、そういうことに対する考えが何かあれば説明を求めました。","respondent":"齋藤選挙管理委員会事務局長","answer":"２０万円を８年間にわたって、多年にわたって頂いております。表彰につきましては、１００万円を超えると功労の表彰をするという基準がありますので、昨年度表彰させていただいたところです。","id":"exchange-015"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"ぜひ大事にしていただいて、しっかり対応していただければなと思います。要望だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"おくの委員","kind":"意見","question":"それから十分な補償、あるいは生活支援という点についてのコロナ対策の内容が、非常に不十分なものになっているという点に表れていると思います。しかし、それぞれの事業自体は必要なものだと思いますので、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-02","title":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(8)令和３年７月４日執行東京都議会議員選挙の結果","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(8)令和３年７月４日執行東京都議会議員選挙の結果","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"感染された方が郵便等で投票を行ったということですが、そこを具体的に教えていただきたいと思いまして、感染者にどうやって郵便……。具体的な投票方法を説明するよう求めました。","respondent":"齋藤選挙管理委員会事務局長","answer":"感染されている方は、私どもで１５１人ということで、その期間に投票できそうな方が１５１人ということは、保健所から確認しております。ホテル、ご自宅に投票用紙が届きましたら、それを選管に送っていただきます。","id":"exchange-018"},{"speaker":"田中委員","kind":"確認","question":"投函に行くということですか。そこのところを確認します。","respondent":"齋藤選挙管理委員会事務局長","answer":"そこが課題の１つでございまして、総務省からは、家族、または友人・知人にお願いして、自分は投函しないでくれというご案内を入れております。友人・知人にも感染させたくないし、知られたくないというお気持ちもあって、少し投票率がよくなかったのではないかと考えております。","id":"exchange-019"}]},{"id":"topic-03","title":"伊藤学園屋内運動場空調設備設置その他機械設備工事請負契約","agenda":"伊藤学園屋内運動場空調設備設置その他機械設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"その費用対効果ですか、やはりメンテナンスが定期的に必要で、その費用も結構かかると聞いております。普通教室３３教室を更新するとありますが、これを導入するからこちらも交換器を更新するということなのでしょうか、説明を求めました。","respondent":"小林施設整備課長","answer":"その辺のところかと考えていますけれども、既存の受変電設備でそのエアコンを動かすことができるかどうか、そういうところも関わってまいります。所管から話を聞く中では、不具合の例も数件聞いているところですので、今回、更新するに至ったという経過です。","id":"exchange-020"},{"speaker":"須貝委員","kind":"確認","question":"取りあえず、いざというときに使えなければどうにもならないので、こちらを導入したということですよね。その辺の確認だけお願いします。","respondent":"小林施設整備課長","answer":"何でしょう、効率的に暖房を動かすことができるのは、ガス式のほうが有利と言われております。一概に費用だけ考えた中では、ガスの方がランニングコストが非常にかかるかということは、少しいろいろと考えはあるかなと思ってあります。","id":"exchange-021"}]},{"id":"topic-04","title":"品川学園屋内運動場空調機設置機械設備工事請負契約","agenda":"品川学園屋内運動場空調機設置機械設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ほかの学校で、もう既にヒートポンプ式ではないものを設置してしまっていると思うのですが、その辺はどうなのですか。それとも、そちらもやはり近々に……、近々というかこれから、設置したのですが、変えていくという方向性なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"須貝委員","kind":"確認","question":"今まで、いろいろな学校の体育館云々でつけているではないですか。それだけ確認していただくよう求めました。","respondent":"小林施設整備課長","answer":"私の知る限りでは、ヒートポンプ式が入っているところです。","id":"exchange-023"},{"speaker":"田中委員","kind":"意見","question":"答えられる範囲でいいのですが、工期が９月３０日とあるのは、「まで」なのかというところと、あと、子どもたちへの影響というのがどうなのかといったところ、これをお知らせいただけますかとの意見を述べました。","respondent":"小林施設整備課長","answer":"恐らく工期の設定につきましては、９月３０日が、これは検査を含めての期間かと思いますので、そういった設定になっているかと思います。９月の中旬頃までどうしてもかかってしまうという話ですので、学校等と調整をして、この工期にしているというところは聞いているところです。","id":"exchange-024"}]},{"id":"topic-05","title":"順番を変更して(6)に参ります。(6)大原小学校外壁改修その他工事請負契約","agenda":"順番を変更して(6)に参ります。(6)大原小学校外壁改修その他工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"これもまた工期が９月３０日ということで、そこの確認と、あと、やはり子どもたちへの影響の部分を少し教えてください。答えられる範囲で構いません。","respondent":"小林施設整備課長","answer":"外部足場を設置して外壁を塗ったり屋上の防水をやったりする、授業が始まるときには、外部足場はなくなっている状況と聞いております。その期間、運営するということを聞いておりまして、運営に大きな影響はないと聞いているところです。","id":"exchange-025"}]},{"id":"topic-06","title":"台場小学校空調設備改修工事請負契約","agenda":"台場小学校空調設備改修工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"すみません、台場小学校も同じく、工期と、あと子どもたちへの影響の部分についてだけ、確認させてください。答えられる範囲で。","respondent":"小林施設整備課長","answer":"こちらも今までと同様でございまして、９月１７日はあくまで検査が含まれる期間です。学校運営に関わる教室の部分につきましては、夏休み工事期間中に行うと聞いております。","id":"exchange-026"},{"speaker":"田中委員","kind":"確認","question":"３７ページを見たときに、工事しないところもあるということで、そこをすまいるスクールの子どもたちは利用するという考え方でいいのか。熱中症になったりしないかということとかを心配していまして、そうではないと思うので、そこら辺の確認したいと求めました。","respondent":"小林施設整備課長","answer":"こちらの台場小学校の空調方式につきましては、今回、工事を行う部分と、いわゆる普通教室の部分が別の系統と聞いておりますので、すまいるスクールをどこでやるかということは把握しておりませんが、エアコンが効く部屋は、工事中であってもあると認識しております。","id":"exchange-027"},{"speaker":"たけうち副委員長","kind":"意見","question":"このフード付ガラリ改修工事、防音型となっているのですが、分かればで結構ですが、いわゆる近隣から少し声がとか、何かそういうのがあってやっているのか、それとも逆に、外からの音が気になるのでやっているのかとか、何か分かればとの意見を述べました。","respondent":"小林施設整備課長","answer":"特に近隣の皆様から何か苦情があるという話を聞いているところではございませんが、メインは外からの音だとは聞いております。","id":"exchange-028"}]},{"id":"topic-07","title":"続きまして、再度順番を変更して(5)です。(5)豊葉の杜学園・二葉すこやか園校庭整備工事請負契約","agenda":"続きまして、再度順番を変更して(5)です。(5)豊葉の杜学園・二葉すこやか園校庭整備工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"きちんと考えられた上での契約だったのかというところが１点と、そういったものも改良された人工芝の契約なのかという部分を、確認したいと求めました。","respondent":"小林施設整備課長","answer":"非常に課題を持っているですので、やはりそういったメーカーさんの動向等を情報収集しながら、適宜適切に必要な材料を発注の中に入れているです。ですので、今回の発注についても、同様なことかと考えております。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"区として、やはりこれからも人工芝化をしていく方針なのかどうかというところ、そこのところをもし教えていただけたら。も進めていくメリットというのはどうなのだろうという部分と、少し疑問に思うところもあるので、お知らせほしいと求めました。","respondent":"渡辺委員長、小林施設整備課長","answer":"多分学校のことを想定されていると思います。それはそれぞれ所管がありますので、それを踏まえて、施設整備課長で答えられる範囲で。 その所管の考えに基づいて我々は工事発注をしていますが、人工芝化を進めているというところが、様々な施設で進められていると認識しております。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"そこは調べたのでしょうか。その辺について少しご見解と、この会社の実績の有無というのを、もし分かれば説明を求めました。","respondent":"東野経理課長","answer":"類似工事実績５０％以上ということで、予定価格の５０％以上ということで募集をしておりますので、それなりの実績があった会社ということになります。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけなのですが、何かそういうふうに努力しているところが、逆に報われなくなるような状況……。何か検討されるようならば、私は、できるようならばしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"１点だけなのですが、価格が９,０００万円以上だからこれが出てくるのだけれども、そうではなくても日頃から動いているのか。どういうふうに更新していくのだみたいなのがある程度決まっていて、動いていっているものなのかだけ、説明を求めました。","respondent":"小林施設整備課長","answer":"比較的新しくても、水はけが悪ければ先に改修しなければいけない施設も出てくるというところは、聞くところです。地域の方が使うこともありますので、そちらの劣化の状況を見ながら、それに応じた改修を進めていると考えております。","id":"exchange-033"}]},{"id":"topic-08","title":"品川区東五反田五丁目付近再構築その２工事請負契約","agenda":"品川区東五反田五丁目付近再構築その２工事請負契約","exchanges":[{"speaker":"田中委員","kind":"質問","question":"３社あるうちの２社が辞退ということですが、辞退理由が、この辞退されたタイミングというのはいつ頃になって……。偶然なのかもしれないですけれども、その何かタイミング的なものとか、どういう経緯だったのかというところを教えてほしいと求めました。","respondent":"東野経理課長","answer":"こちらの工事につきましては、制限付き一般競争入札ですので、まずはこちらの入札にお申込みをしていただくというようなことが、手順としています。入札金額を入れている会社と、辞退届という形で出された会社とが、同じタイミングであったという形になります。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2204#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":24916,"voices":120}},{"id":"r03-20210708-14","meetingId":"r03-cm07","date":"2021年7月8日","dateIso":"2021-07-08","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"まだちょっと伺っていないことがあって、もし分かれば教えていただきたいのですが、どうしてこういうふうな形になったのか。なぜこういうふうに、今、品川区役所がなっているのか、もしそのあたりをわかる方がいらっしゃれば教えていただきたいのですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、ちょっとそういうところが失われるのかなというのがまず１点、その点を申し上げたいと思います。これは答弁を求めてもあれなので、一応意見として申し述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"川崎市の基本計画を見ると、川崎市の場合は５０m2掛ける６０人いらっしゃるということで、３,０００m2。もし把握されているのであれば、今、議会の面積というのは足りているのか、足りていないのか、わかれば説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"生きていないのかわかりませんけれども、そういうのもあればぜひお示しをいただきたいなと、１つの議論の材料としていただきたいなと思っています。それが表示されるような、そういったものもわかりやすく利便性の関係からも必要ではないのかなと思うので、一応意見として言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"そして、１３ページですか、世田谷区の側面図がありますけれども、議会機能が上層階のほうに設けられております。以上、要望というか、感想といいますか、一応意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"確認なのですけれども、そんなに議会のほうにはお越しにならないから上層階にしていると、こういう意味でよろしかったのですか。別に高みから見ているとか、そういう意味ではなくて、そういう意味というふうに理解しているのですけれども、ちょっとそこだけ確認したいと求めました。","respondent":"濱中庁舎計画担当課長","answer":"低層階には区民協働・交流であったり、テナントであったり、そして窓口が集中していく。そういった設計の視点からもおそらく上層階のほうを選ばれた区議会、また自治体のほうが多いのかなというふうな印象を持っているところです。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"それから、発電力というのですか、災害対策時にしっかり対応できるような整備というのが必要なのではないかと思うのです。その２点をお伺いしたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"区民の安全・安心を支える庁舎としていくことが防災機能として重要なことだと認識しております。災害時の対応としまして、例えば、非常時には災害対策本部の会議室に切り替わって使えるような形に設計をしている渋谷区の事例もあります。","id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"しっかりご検討していただけるというご答弁だったと思いますので、期待をするではないですけれども、ある意味最新鋭というか、なるほどと言えるような形にしていっていきたいなというふうに私も思っておりますので、今後ともよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"芹澤委員","kind":"提案","question":"３点お伺いします。６ページの豊島区のところで、どういった内容なのかが、もしわかれば教えていただきたいのが１点との意見を述べました。","respondent":"濱中庁舎計画担当課長","answer":"もちろんコストバランス等もありますので、そういった面も含めて環境に配慮した庁舎を検討していきたいと考えています。可動式ではないですけれども、部屋の設計が柔軟に変えられるようなことも想定できるかなというところを、今後検討していきたいと考えています。","id":"exchange-009"},{"speaker":"西村委員","kind":"質問","question":"いろいろな区の状況を教えていただき、すごくわかりやすいのですが、品川区でもご検討いただいているかどうかお伺いしたいのです。２つ目の職員派遣型窓口というものもとても興味深くて、３つ目の庁舎に来ることができない方へのテレビモニターなども、尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"基本計画に向けてどういった窓口がよいのかというものを、他自治体の先進事例を見ながら今後検討していきたいと考えています。今どういうふうな窓口に、どんなものが来ているのか、その結果を踏まえて区民の皆様に使いやすい窓口を計画していきたいと考えています。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"品川区の現状とか課題とか、そういったところに対応した機能だったりというのを何か検討されていることがありましたら教えていただきたいということ。２点お願いします。","respondent":"濱中庁舎計画担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"せお委員","kind":"質問","question":"水辺がありますので、そういったところをちょっとアピールしていくとか、そういったものも考えていただけるといいなとは思っています。豊島区のほうは、これを品川区でやられるとちょっとなと思ったので、何かご意見があるのかなと思ってお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから中小企業センターだって、どこの段階でどう入れ込むのかとか、入れ込まないとか、判断するのか、あるではないですか。必ずそういうことも頭の中には入るのでしょうから、それはどこの段階でそういうことを判断しなくてはいけないのかというところも教えていただきたい。","respondent":"榎本総務部長、濱中庁舎計画担当課長","answer":"そういった意味で、第二庁舎、中小企業センターに分かれている庁舎機能については、なるべく１か所にまとめて全部やっていきたいという考え方です。いずれ建物というのは耐用年数が来ますので… ではこういった形にしていきましょうというコンセプトを出していただいて、最後に実施設計で詳しい配置ですとか、そういったものが決まっていくです。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"議会だって法務局はなくならないでくれと毎回要望を出したりしていた時期もあるではないですか。税務署について分かるのか分からないのか、ちょっとそこは分からないけれども、そういうのは大体分かると理解してしまっていいのか尋ねました。","respondent":"榎本総務部長","answer":"それから、税務署については、今ちょっと協議はしていますけれども、なかなか難しいかなというのが今の段階の進捗状況です。そういった意味では、ちょっと難しいかなと思っていますけれども、それも基本構想の段階できちんと素案の中に盛り込んでいきたいと思っています。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしても上層階になるのだろうな、吹き抜けがあるし、希望を言えば多分上層階しか取れないのだろうなと思うけれども。そういう理解でいいのか尋ねました。","respondent":"榎本総務部長","answer":"そういう理解で結構です。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"今、光熱費も含めて免除されていたりとかというところも併せてどのように検討されているのか、もしわかれば教えていただきたい。屋上をどうやって使っていくかというところもあるのかなと思うので、これを見ると目の前に広場ができたりというところで、説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大倉委員","kind":"意見","question":"そういったスペースみたいなものがあってもいいのかなと思ったので、ぜひそういうことも併せていろいろ検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"環境問題や防災の拠点ということは、リードしていくべきところでもあると思いますので、そういったところは進めていただきたいというふうに思います。もし、ご答弁がありましたらお願いいたします。","respondent":"榎本総務部長、濱中庁舎計画担当課長","answer":"この土地をどう活用するかという検討から始まっております。この土地を有効活用して区のためにどう使うかという形でずっと検討してきておりますので。次回、そういった形でやるときには音響等の設備をしっかり拡充して、傍聴の方が聞き取りやすいような環境を整備していきたいと考えています。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"確認","question":"例えば、食堂というとバックヤードがすごく広くなってしまうから、すごく広いスペースが必要になるではないですか。カフェとコンビニだったらスペースが要らないではないか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"コンビニを入れたほうがいいということであれば、他自治体の事例とかも含めて、これぐらいの規模であろうということを基本計画の中にしっかりと入れ込む必要があるかと考えています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"今、こちらでも深くいろいろなことを取り上げて議論していっていいのですか。３回あるのですが、どのようなお考えで進めていかれるのか、どこまで議論していいのかというのを教えていただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/444693?Template=document&Id=6112#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":28441,"voices":53}},{"id":"r03-20210709-19","meetingId":"r03-cm07","date":"2021年7月9日","dateIso":"2021-07-09","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"それから原因部分を分析するときに一応念頭に置いているのは、対策をどうするかということと両にらみで原因部分を見ていくことになると思うのです。その趣旨をご説明願えればと思いますとの意見を述べました。","respondent":"河内環境課長","answer":"それから、建物ですが、設備は例えば１５年程度だとか、建物そのものについては３０年程度だとか、一定に寿命が来ます。そういった観点で選んだものです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"６番は家庭の省エネ家電への買替えについてとなっていますけれども、でも、建物の中でも家庭部門に限られているわけですよね。原因において抽出した建物というカテゴリーがあまり生かされていないのではないかというふうにも思ったのですけれども、いかがか尋ねました。","respondent":"河内環境課長","answer":"ＣＯ２削減と申しますのは、それに付随するものも含めましてしっかり推進しませんと、なかなか目標達成はおぼつかないような状況と理解しております。そういった意味で、多様な施策を用いながらＣＯ２の削減に向けてという点で、こういった例示をさせていただいたという点です。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"ＺＥＢについては、原因との関係、どういう位置づけで考えられているのでしょうか。私にとっては、そこら辺の位置づけ、要するにＣＯ２排出との関係の位置づけをもう少しご説明願えればと思うのですが。","respondent":"河内環境課長","answer":"今までＣＯ２削減の努力、ポンプ１台とってみても、いろいろ重ねてきたわけです。その集合体として全体を見て、ＣＯ２の削減に向けて有効なツールであることがご理解いただけるのではないかと考えております。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"電気代ですか、これがやっぱりちょっと上がってしまうものなのかどうなのかというところ、そういうところを使っているのか。この４段階のＺＥＢがある中で、完璧な１００％を目指せとは言いませんけれども、そういうお考えなのかどうか。","respondent":"河内環境課長","answer":"大都市圏におきましては、私どもの区施設が唯一というところの認識です。大型の５００ｌ以上のものの方が消費電力が少ないとか、都などが行っております支援情報も併せまして発信したいという考えでいるところです。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"そこを教えてもらいたいということと、もう７６％ぐらい、あとで教えてください。一定程度、何か国からそういうものが出てくるのかと思ったのですけれども、その辺の動きがあれば説明を求めました。","respondent":"河内環境課長","answer":"今後の把握に努めたいですが、一定ボリュームも把握していますので、そういった目標に向けまして進めていきたいと考えています。それから、ＺＥＢの説明で、紛らわしくて申し訳ございませんでした。","id":"exchange-005"},{"speaker":"吉田委員","kind":"確認","question":"第二庁舎はなぜ切り替えができたのかと伺ったときに、防災センターとなると、ちょっと違ってきますよね。２０２１年、これは２０１９年の実績ということですが、その辺の評価をぜひ伺いたいというふうに思います。","respondent":"河内環境課長","answer":"それから本庁舎につきましては、現在、改築なども予定されていることから、こういったものを積極的に取り入れたいというものです。講座や説明会などを含めまして、事業者や区民の皆様に対しまして、しっかりとこういった有効策について周知徹底を図りたいです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ごみ発電を１０％以下に抑えるという内容になっているのを確認しておりますが、どういう方向、一応確認させてほしいと求めました。品川区として自治体だけで全部できるとは思わないのですけれども、その辺についての見解があれば伺いたいと思います。","respondent":"河内環境課長","answer":"他の状況も踏まえて、今後、精査していきたいという考えです。そういったものを精査しながら、全体的に正味のＣＯ２削減に向けて、意思の精査をしていくようなところをしたいと考えています。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"２番のこのデータの出し方ですけれども、今議論したいことについて、この委員会での議論がしやすいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"令和２年度も１件だけということですが、これが進まない理由は何なのか伺いたいと思います。区有施設なども、本当に有効なシステムだと思うのですけれども、区としての考え方についてお聞かせほしいと求めました。","respondent":"河内環境課長","answer":"制度自体は変わっておりませんので、そういった方向で今後も周知啓発に向けて力を入れたいというふうに考えております。今後、区有施設におきましても、こういった検討を進めながら、全体のＣＯ２の削減に向けて取組んでまいりたいというふうに考えているところです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"たしかあのとき、５０件を超えたのではないかと思うのですけれども、区が予定していた以上に申請が多かったというときがあったと思うのです。周知徹底と併せて、コスト的にも支援をしていただいて、広がるような取組みにぜひしていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"課長からのご説明を伺ったのですが、要するに、この審議の材料にするためにお願いしたいと思います。","respondent":"河内環境課長","answer":"現状の達成率との見合いで考えますと、社会的に果たすべき役割といたしまして、４０％はまずクリアしていきたいです。皆様のご協力のもと、一丸となって取組んでまいりたい所存ですので、ひとつよろしくお願いいたします。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問","question":"国が２０１３年度比で２６％の目標を掲げているときに、品川区は４０％の削減目標を掲げた、だから国より高い目標を掲げていると。２０１３年度比で４６％の削減目標を掲げたというのが、品川区も、多分これを踏まえて考えていくというような理解でよろしいのか尋ねました。","respondent":"河内環境課長","answer":"おっしゃるとおりです。","id":"exchange-012"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから、再生可能エネルギーを６０％、さらには１００％にしていくことを国に対して求めるよう区に求めているわけです。ですから、もともと国の上をいっていたような計画ですから、その点いかがか尋ねました。","respondent":"河内環境課長","answer":"ＣＯ２の削減に向けまして、そのような結果が用いられますように、基礎自治体としての役割を果たしてまいりたいと考えています。エネルギー政策などにつきましては、自治体としての役割の中でとらまえているものです。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"あるいは環境をよりよいものにしていくということだと思うのです。ＣＯ２を出すような石炭火力発電はもうやめようというような、それは当然ご理解の上だと思うのですけれども、いかがか尋ねました。","respondent":"河内環境課長","answer":"ＣＯ２の削減に向けまして、品川区環境基本計画の中でしっかりと取組みを進めてまいりたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"地方自治体の役割というのは、私の申し上げた福祉の増進だということを地方自治法どおりに解釈して、踏まえた上でやっていただきたいということを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ゼロカーボンシティ宣言を求められていますが、宣言というものも１つの手段ですが、同種の取組みだと思うのです。この辺、別に、多分相違はないと思うので確認のために伺います。","respondent":"河内環境課長","answer":"今、委員がおっしゃられたとおりでございまして、国などの動向も踏まえまして取組みを進めてまいりたいというふうに考えているところです。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"多分、単純なミスだと思うので、これは「令和９年」ということで思っておけばいいかと思います。意見書を求めるとか、例えば品川区だけではなくて２３区全部もしくは東京都内全部にこういうものを出しているのだとか、説明を求めました。","respondent":"河内環境課長","answer":"ＣＯ２削減の取組みですが、現状行っていることの考え方などをベースにしながら、ＣＯ２削減を目標値に向かってやっていきたいです。宣言されている区が９区ほどありますが、そういったところも踏まえまして、今後進めてまいりたいと考えております。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"確認","question":"我々のほうで確認すればよかったのかもしれませんけれども、これからどうなるかは別にしても、ちょっと思いました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"今さらで本当にお恥ずかしいのですけれども、品川区環境基本計画で国より高いＣＯ２削減目標を掲げて、それの実効施策として、区庁舎への再生可能エネルギー導入を進めるという認識に至った、何かそこの時点での議論とか経緯とかを把握していらしたら説明を求めました。","respondent":"河内環境課長","answer":"環境ＩＳＯの取組み時点から、グリーン電力の購入などに向けまして、ＣＯ２排出に向けた取組みなどを進めてきたところです。そういったところから再生可能エネルギーに向けた取組みも進んだというふうに推察しています。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区として、今年度、見直しの議論だというふうに伺っております。一般質問でもいたしましたが、改めて今の環境基本計画のＣＯ２削減を再生可能エネルギーの推進で進めるというお考えについて、確認したいと求めました。","respondent":"河内環境課長","answer":"ＣＯ２の削減におきまして、再生可能エネルギーの利用というのは大きなポイントだというふうに認識しています。４０％という高い目標に向かいまして、そういったところも踏まえまして、再生可能エネルギーについてもしっかり進めてまいりたいです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"意見","question":"分かりました。品川区の見解としては、そういう方向であるということで理解をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今は第５次エネルギー基本計画、今度は、この国の基本計画に品川区がどのような影響を受けるのかというところをお聞かせほしいと求めました。第６次エネルギー基本計画は、どういう会議体でこれが策定されるのかというところが分かったら、教えてほしいと求めました。","respondent":"河内環境課長","answer":"脱石炭といたしまして、現在、火力の約半数が石炭火力ですが、そういったところの低減に向けてというところは情報としてつかんでいるところです。そのほかにつきましては、ＣＯ２の削減に向けて有用なところについては取り入れてまいりたいです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"毎年様々なところで発生するというところでは、全会一致で確認されるという、そういう時代になっているというところがまず前提にあると思うのです。第５次エネルギー基本計画とは政策転換を主眼とした計画とすることというのが第一番目で、どう考えられているか、お聞かせいただけたらと思います。","respondent":"河内環境課長","answer":"国のエネルギー政策ですので、区としてそのような考えを示す予定はございません。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この脱原発というところで、ぜひ一致していきたいというふうに思うのですけれども、この点でご意見を伺えたらと思います。私は出すべきではないかと思うのですけれども、その２点について、ご意見を伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"渡辺委員","kind":"意見","question":"そこの個々の見解というよりも、この請願の審査に集中して、それに沿った形で意見表明をするのが今の役割だと思っています。そうご理解ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"どれだけのエネルギーが必要かという中で、いきなりこの原発を全部止める、石炭エネルギーを全部止めたらどうなるのですか。様々な審議体において真剣に議論していることですから、そのほうが楽かもしれません、気持ちは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だって、９基も再稼働して、さらに再稼働を進めていくという、そういう方向ですから、この地震大国で。原発ほど高コストになるものはないわけですから、これだけの災害を起こしている、ぜひ皆さんと意見を交換し合いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"確認","question":"今、請願の審査をしているので、私は請願の審査を行いたいのですけれども。これは議会ではなくて特別委員会ですから、委員長は、その辺のことを確認しながら運営をお願いしたいと思います。","respondent":"安藤委員長","answer":"私たち議員が設置している委員会であり、委員同士の質疑を進めてもらって、それで進めているところです。","id":"exchange-028"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"再生可能エネルギーに関して意見書を求めると書いてあるので、原発を廃止しろというような意見書ではないような気がするのですが、いかがでしょうか。委員長のお考えを伺いたいです。","respondent":"安藤委員長","answer":"お尋ねなのでお答えしますけれども、請願項目を見れば、意見書を提出してくださいと。","id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いずれにしても、先ほど意見は申し上げましたので、もうこれ以上、うちの会派は議論をしたいと思っていませんので、結論を出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、それを国に対して求めてほしいというところでは、品川区は再生可能エネルギーでＣＯ２削減を目指しているわけです。原発は止めるにしても時間がかかるというのがそもそものリスクですから、意見としては、議論の俎上に上げるために紹介議員にならせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"渡辺委員","kind":"意見","question":"これに関しては国のエネルギー政策である点が１つ。よって、不採択という考えですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。今、国で検討するということになっておりますので、我々のほうでそれを先んじる考えはないかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"不採択でお願いします。それをしっかりとしていただくように要望して、この件に関しては不採択で、もう既にやっていることですからということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"おくの委員","kind":"意見","question":"こういうエネルギー政策を根本的に転換していく戦略をとることによって、脱炭素政策が具体的に実現していくのだと思います。採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"これはとても評価しているところですけれども、こういう意見書を出せるのは、先進的に頑張っている自治体だからこそできることではないでしょうか。ぜひ、このような意見書を提出する資格があるし、提出するべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問","question":"２番、３番については、これが高く見込まれること。方向性が見られるということで、そういった発展的に考えて、前向きに捉えての不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"たけうち委員","kind":"質問","question":"理由については、先ほども述べたとおり、これは全て、今、品川区がやっており、これからも強化するということになっております。出てきたもの全てを採択というわけにいかないなという、そういう理由も含めて不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"おくの委員","kind":"意見","question":"同様に区でも宣言を出すことは非常に高い意味を持つと思います。採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"吉田委員","kind":"意見","question":"ゼロカーボンシティ宣言をして、さらにその姿勢を示して、区民にも啓発を進める必要があるというふうに思っています。ということで採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]},{"id":"topic-03","title":"もったいないレシピコンテストの開催","agenda":"もったいないレシピコンテストの開催","exchanges":[{"speaker":"湯澤委員","kind":"意見","question":"そのうちの４６％が家庭から出ている、そして国民１人当たり、１日茶わん１杯分をロスしているというふうに消費者庁でもうたっているかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"経費が１５２万円というふうになっております。もう少し内訳とか、今、お手元で分かるようでしたら説明を求めました。","respondent":"河内環境課長","answer":"委員会の運営経費が大部分を占めておりまして、詳しい資料が手元にないものですから、主に委員会の開催経費が占めるものです。副賞については、表記のとおりですので、それほど経費はかかっていない状況です。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"環境活動を、一般的な活動をしていらっしゃる方なのかなというふうに思っていて、それが誤解だったらごめんなさい。環境の視点とはまたちょっと違う人があってもいいのではないかというふうに思ったのですけれども、その辺については、いかがか尋ねました。","respondent":"河内環境課長","answer":"様々な立場の方が含まれておりまして、以前、フードドライブなどをご経験された方も中には含まれておるような状況です。主婦の目線や学生の目線、いろいろな目線を持ちまして、こういったものの評価を進めていくという予定です。","id":"exchange-043"},{"speaker":"吉田委員","kind":"意見","question":"この自分たちがやった活動がどうつながるかというところを、ただおいしく食べるだけではなくて、さらにいいかなというふうに思いました。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"松澤委員","kind":"質問","question":"周知のことで１つ質問なのですけれども、区民への周知の中でＳＮＳ等とありますけれども、これは要は、インスタで発信するとか、フェイスブックであるとか、具体的に発信することなのか尋ねました。","respondent":"河内環境課長","answer":"区のホームページはもとより、ツイッターなどでも発信させていただきまして、紙しかご覧になれない世代以外の方にも、こういったところに触れていただきますように、しっかり啓発をしていきたいというふうに考えているところです。","id":"exchange-045"},{"speaker":"こんの委員","kind":"確認","question":"これは食をしていますけれども、レシピを応募してもらうという、こういう取組みというのを過去やっていたかどうかという基本的なところの確認と。２回、３回と繰り返していく中で、取組みなども併せて説明を求めました。","respondent":"河内環境課長","answer":"レシピコンテストのような取組みですが、これが初となるものです。ＣＯ２は発生するわけですので、今後、継続に向けて考えを進めていきたいというようなところです。","id":"exchange-046"},{"speaker":"こんの委員","kind":"質問","question":"当然お考えになっていると思いますけれども、これに関しては、今は何も連携はないのでしょうか。あったら説明を求めました。","respondent":"河内環境課長","answer":"ＣＯ２問題についてフォーカスしていますが、二次的なところでそういったところも非常に大事なものというふうに認識しておりますので、今後進めてまいりたいというふうに考えているところです。","id":"exchange-047"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、学校に対しては、お手紙というか、学校に通知、今はそこら辺のところぐらいですか。その辺はいかがか尋ねました。","respondent":"河内環境課長","answer":"チラシなどの配布も学校側のほうにやっているところですので、今後、特別なものは何かというのは検討しながら進めてまいります。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"だから、何かそういうことでもったいないことになっているものが結構あると思うのです。さりげなく啓発とかを進めていただけたらいいと思うのですが、その辺について、いかがか尋ねました。","respondent":"河内環境課長","answer":"表現が不適切で申し訳ございませんでした。委員のおっしゃるとおりでございまして、そのような考えを基に、食に無駄がないように進めてまいりたいというところが考え方の本質的なところです。","id":"exchange-049"}]},{"id":"topic-04","title":"品川区災害時受援計画の策定","agenda":"品川区災害時受援計画の策定","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"通信の途絶等により都知事に対する要請ができない場合に、区の災害対策本部長から自衛隊に通知をする。そういった場合に練馬の第１師団のほうから派遣されるというところで、１９ページに、この場所を決めたその理由を教えてもらえますか尋ねました。","respondent":"山本防災課長","answer":"活動拠点場所の指定ですけれども、こちらは東京都が区内何か所かの指定をしてございまして、品川区に関して言うと、こちらの大井ふ頭中央海浜公園というところで、東京都が指定をしているものです。","id":"exchange-050"},{"speaker":"小芝委員","kind":"確認","question":"２本かかっていて、西側のほうに入っていって活動を展開されるということを想定されているのかどうか、確認をお願いします。","respondent":"山本防災課長","answer":"実際の活用方法は、災害が起こって、その被害状況等に応じて少し変わってくるのかなというふうに思っているのですけれども、今、委員がおっしゃったとおりの方法が基本的なところになるというふうに考えてあります。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"いつの時点だったか、東京都のボランティアとかを受け入れる体制がちゃんとできていないというような指摘を受けて、どうしたらいいのだろうかと。その辺を受ける側としても、それについては、どの辺に表現されているのか教えてほしいと求めました。","respondent":"山本防災課長","answer":"受援の部分に関する考え方ですが、国や都、それから自治体からの応援の受援に関する計画になっているところです。その辺りについて記載をしていく計画になっていますので、個人としての扱いは、この計画上記載をしていないところです。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"私は、その方たちの思いに応えることにもなると思いますし、その辺のことについては考えておいたほうがいいのではないかというふうに思います。そういう東京都との連携も含めて、もし何か今、進行形でも考えておられることがあったら伺いたいと思います。","respondent":"山本防災課長","answer":"今年の１月、社会福祉協議会と災害時ボランティアセンターの設置運営に関する協定を結んでおりまして、それから調整を行う形になってあります。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"かえって、中には結果としてちょっと迷惑に感じてしまったり、そういうこともあるというふうには伺っております。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"たけうち委員","kind":"質問","question":"一番最後のページの第４章３番のタイムラインの表の中で、いわゆる要請がなくても駆けつけるみたいなイメージだったような気がするのですけれども、その辺のご説明を説明するよう求めました。","respondent":"平原防災体制整備担当課長","answer":"物的受援のところの国からのプッシュ型支援ですけれども、これまでの大きな災害で、一方的に持ってくるというものがプッシュ型支援でございまして。","id":"exchange-055"},{"speaker":"たけうち委員","kind":"質問","question":"こういうところも、ここに計画を立てられているので、しっかりそこも事前にいろいろと考えていらっしゃるのだなということが１つありました。年に２回とか、数年に１回とか、お互いのやり取りみたいものはされているのか尋ねました。","respondent":"山本防災課長","answer":"見直し等も行いながら、検討会等を開けるように、いろいろ検討していきたいというふうに思ってあります。","id":"exchange-056"},{"speaker":"たけうち委員","kind":"質問・要望","question":"お互いさまなわけですけれども、そういう関係のところは、やっぱり日頃からさらに大事にしていただきたいなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"第５章の受援計画の実効性の確保というところをお聞きしたいと思います。具体的にどういう訓練をするのか、そこら辺を教えていただきたいのと、その辺を説明するよう求めました。","respondent":"山本防災課長","answer":"実効性の確保について、研修また訓練というところですが、これから具体的に考えていきたいというふうには思ってあります。本部、どういったルートで、どういった量を輸送していくかというような仮想をつくってから訓練等を行っていきたいというふうには考えてあります。","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"頻度としてどれぐらいなのかというところもご答弁ほしいと求めましたけれども、より実効性のあるというところの確保の訓練はどうしたものがいいのかも考えていっていただければ、お願いします。","respondent":"平原防災体制整備担当課長","answer":"私から、現在考えております物資の受援の今後の訓練といいましょうか、練度の向上につきまして、ご説明します。その団体にお伝えすることができるのか、そういう共通認識ができました段階で、実際にこういった場でやるのですよということを分かってもらう。","id":"exchange-059"}]},{"id":"topic-05","title":"新防災ラジオ","agenda":"新防災ラジオ","exchanges":[{"speaker":"松澤委員","kind":"確認","question":"１個だけ確認させてください。１年に１回でも、そういう受信の訓練というか、テストというのはやったりするのか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"現在考えているところでは、月に一度程度、日付を決めまして放送するということを考えてあります。そちらの内容につきましては、何らかの言葉を入れて、ちゃんとつながっていますということが分かるような状況にしたいというふうに思っております。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"今のご質問に関連するのですけれども、そのことも併せて周知されるのでしょうか。ぜひ回収していただきたいなと思うのですけれども、その辺については、いかがか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"まず１つ目には、まだ使える家電製品というところで、ご活用いただければというふうに考えてあります。品川区が定める小型家電の廃棄方法に従いまして、各家庭で廃棄していただければというふうに考えているところです。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"広報しながわとか、そういうところを使われるということですけれども、そもそもお知らせが個別に行くわけですから。ぜひその辺まで配慮をしていただけたらと思いますが、それについてもしお考えがあれば伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"その辺のところを決めていきたいなと思いますが、まず考え方といたしましては、使えるものはぜひ使ってくださいというようなところでご紹介させていただければというふうに思っているところです。","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問・要望","question":"総務委員会でも申し上げたのですが、前回の配布は、高齢者、障害者、住民税非課税世帯の方が２,０００円で、一般の方が４,０００円だと伺いました。お伺いいたします。","respondent":"平原防災体制整備担当課長","answer":"あっ旋販売自体が令和４年度ということもありますので、今の現状では、特段まだ検討が進んでいるものではございません。次年度予算というところの枠組みで検討が進められる形になるのですけれども、そちらのほうの検討を進めてまいりたいというふうに思ってあります。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこのところを考えていただいて、無償ということも、よくよく考えてほしいと求めました。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"たけうち委員","kind":"確認","question":"総務委員会でもあったので確認ですけれども、区の防災行政無線のものとか、いろいろ流れてきますよね。ああいうもので同じものが流れてくるのは、何が流れてくるのか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"もう１つは、いずれも緊急放送を対象としておりまして、そういったものが流れるような形になっております。なお、スマートフォンにつきましては、先ほど言いましたとおり、令和２年度から緊急放送を中心に、テキスト配信をさせていただいているところです。","id":"exchange-065"},{"speaker":"たけうち委員","kind":"確認","question":"なくても文字で確認できると、２台では、その辺が分かれば説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"スマートフォン１つで、ラジオもスマートフォンで聞くことができますので、そういったところがまず主流になるのかなと思います。２台というのはなかなか難しいところですが、令和４年度の販売のところで早急に取りまとめて、また検討を進めてまいりたいと思います。","id":"exchange-066"},{"speaker":"たけうち委員","kind":"意見","question":"スマートフォンでも同じ情報を聞けるのかとなる方がいてもあれなので、必要な方に回らないといけないので、その辺の周知も併せてお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/822771?Template=document&Id=6598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":48427,"voices":170}},{"id":"r03-20210713-10","meetingId":"r03-cm07","date":"2021年7月13日","dateIso":"2021-07-13","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"令和３年第２回定例会","agenda":"令和３年第２回定例会","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"日程第１０、第４０号議案の品川区手話言語条例の採決方法のことについてでありますが、起立採決を提案したいと考えています。起立採決を提案させてほしいと求めましたけれども、皆さんのご意見をお伺いできたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"提案","question":"ご提案ということなので真摯に受け止めたいのですが、課題があるという点で、頭からの否定というよりは、難しさがあるというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"大沢委員","kind":"意見","question":"今、渡辺委員のご発言のように、課題が大きい問題だと感じます。委員長がさっきおっしゃったように、最終的には議長のご判断、そこら辺の課題を十分に加味しながら、議長の判断を仰ぎたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"意見","question":"先ほどもあったとおり、合理的配慮ということで手話通訳なども入れていらっしゃる。何か違う部分で捉えられる、そういう課題も出てくるといけないと思いますので、今までどおりでいいのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"中塚委員の提案は、すごくいいことだというふうにまず思いました。今、きちんとお伝えもできるということならば、やはり従来の方法で進めるということでいいのではないかと私も思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"皆さんのご理解が得られればということで提案させていただきました。採決も含めて、多くの方が普通どおり簡易採決ということでありますので、それはそれで受け止めさせてほしいと求めました。","respondent":"本多議長","answer":"中塚委員の提案の趣旨、あと、皆さんからそれぞれ意見をいただき、本当にいい議論だったと思います。やはり原則どおりかと、あとは、今回も簡易採決で進めさせていただきたいと思います。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":13557,"voices":67}},{"id":"r03-20210729-10","meetingId":"r03-cm07","date":"2021年7月29日","dateIso":"2021-07-29","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"の１、新庁舎整備基本構想における議会機能に関する意見","agenda":"の１、新庁舎整備基本構想における議会機能に関する意見","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"先般も述べたように、今の議長のご提案に、賛成ということで進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"緊急事態宣言を発令して住民に対しては外出自粛を求めながら、この矛盾が感染拡大をさらに広げており、オリンピックよりも命が大事だと考えています。併せて、各区議会議員に求められているので、品川区議会として協力をするというものではないということだけは指摘します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"泊るところが一緒、練習する部屋に応援メッセージのフラッグを掲示したいと書いてあるのですが、一枚で足りるのですか。今までは競技別でやってきたのですけれども、２つの競技になっているのですけれども、各１枚という意味なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"例えば２つに分けても構わないですし、同じ場所に泊まるとか、それを見て皆様が頑張ろうということであれば一つでも構わないと思うのですけれども、いかようにもしますよという意味で質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5422#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":3419,"voices":22}},{"id":"r03-20210818-6","meetingId":"r03-cm08","date":"2021年8月18日","dateIso":"2021-08-18","committee":"区民委員会","time":"午後 １時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"令和３年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"令和３年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"成果の確認の仕方なのですけれども、審査方法の7)番ですかね、状態などが示されているかというところで質問します。3)番のところに当たるのかなと思うのですけれども、指標ですとか状態などというところが示されているかどうかというところだけ確認したいと求めました。","respondent":"川島地域活動課長","answer":"こちらは区のほうのアドバイスというか、説明の中でもちょっとかみ合わないようなところが多くて、なかなかこういうところもあるというのが実際です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"この助成が終わった後のそれぞれの活動の状況というのは、区としてはどんなふうに把握されているのか。助成が終わった後の取組へのフォローはどういう仕組みがあるのか、どういう状況にあるのか、状況をご説明いただけたらと思います。","respondent":"川島地域活動課長","answer":"一応１つは、これも２年に１回改訂するということなのですが、活動しているかというようなところもある程度追っていけるのかなというような形で考えてあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"当初の制度設計と多少変わったところはあるのだけれども、趣旨としては、基金を活用して資金助成をしていこうということで、地域の中で引き続き様々な団体が熱意を持って取組を広げていますので、制度の周知や丁寧な説明をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"くにば委員","kind":"質問・要望","question":"過去に助成対象となった事業について、結局事業収支が助成金がなくなってしまったらマイナスのようでしたらこの助成制度はいかがなものかなと。そういった事業があったら教えていただきたいのと、その辺どのようにしているか、そちらをお伺いしたいです。","respondent":"川島地域活動課長","answer":"伴走的な支援という形で、それから、資金のことにつきましても幅広くアドバイスをいただいているというような形です。こちらの団体の力を借りまして、引き続き支援というか、後支えをしていければというふうに考えてあります。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"それとも、その手前の段階で、多くの団体のほうから今年申請をしようかどうか考えているけれどもという形でご相談はなさっていると思うのです。全ての方々に、事業を実施できると思いますみたいな形で、全てのご相談者の方にアドバイスをしているのかお伺いしたいです。","respondent":"川島地域活動課長","answer":"しながわすまいるネットのほうで活動の紹介をしたりだとか、それから、イベントの告知などのお手伝いをしています。そういった中で様々な活動の支援ができればというふうに思っているのですが、今おっしゃったとおり、実際の活動の中でどうしていくかということを。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"８月１７日現在までに１,４７７件の発行があるというご説明でしたけれども、目的と言ったらいいのでしょうか、どういう傾向にあるのか。それとも、目的を聞くことなく発行事務をやられているのか、そこをちょっとご説明いただけますか尋ねました。","respondent":"久保田地域振興部長","answer":"目的を書けというようなことは、ちょっと今申請書が手元にないのですけれども、たしか海外渡航するということが前提で発行しているというものです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"なぜ聞いたのかというと、かといって、そういうときにこういうワクチンパスポートというのはどういう状況なのかなと思って伺いました。だからといって、どういう傾向にもあるかなというふうにもちょっと気になったところでありますので、質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問","question":"ご説明ありがとうございました。国が定められている１８の国と地域だけなのかというところと、また、ちょっとお伺いしたいと思います。","respondent":"久保田地域振興部長","answer":"そういう関係で１８か国です。この１８か国に限らず、フランスですとか、そういう方にも海外渡航の予定があるということを前提にお渡しをさせていただいているというものです。","id":"exchange-008"},{"speaker":"新妻副委員長","kind":"確認","question":"柔軟な対応をされているということが確認できました。海外に行くという前提があって、パスポートがあって、いずれ海外に行くのでということであれば申請は受けていただけるということでよろしいですね。","respondent":"久保田地域振興部長","answer":"申請書には海外渡航の予定日等を記載していますので、一応海外に渡航する予定があるということが前提です。すごい何年も先の将来に行くとかいいますとまた別の話になるのでしょうけれども、一応今の時点で予定がある方を対象に発行させていただいています。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"１点だけお伺いしますが、（３）の手数料・送料なのですが、何で無料になっているか、その根拠を教えていただけますか。","respondent":"久保田地域振興部長","answer":"これは国のほうが発行する国のほうの事業ですが、実際発行は各市区町村が担ってやっております。国のほうでこれにつきましては無料というようなことを決めてありますので、品川区におきましても無料で発行しているというものです。","id":"exchange-010"}]},{"id":"topic-02","title":"東京２０２０オリンピック・パラリンピック関連事業等","agenda":"東京２０２０オリンピック・パラリンピック関連事業等","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ご承知のとおり、東京都内の感染者は５,０００人を超え、今週末はさらにそれを上回るのではないかと言われております。お伺いしたいのは、オリンピックの開催が感染爆発の要因だと区は思うのか、その点について伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"開かなかった場合、有観客だった場合、無観客だった場合との比較というのはなかなか難しいことだなというふうに認識しております。以上です。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"それは専門家の方も指摘していることだし、国民の多くの方が実感をしていることだと思います。やはり今の危機的状況をまず共有するには、今からでもパラリンピックは中止をと品川区側から発信するべきだと思うし、最後にいかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その限られた条件の中で自分たちができることをやっていくことができたねというような共通認識を持てたかなというふうにオリンピックに関しては思っ…３密を作らないだとか、安全・安心を守りながら、その応援は限られた形の中でやっていくというふうに思っているところです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"それはしっかり目を向けるべきだと思います。人の命を奪っていい、そんなイベントは決してあってはならないと思いますので、今後とも意見を交わしていきたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問・要望","question":"１点だけ確認したいのですけれども、こちら同じ日程で同じ会場で開催される予定だったキャナルフェスは中止になりました。キャナルフェスは中止になったけれども、キャナルアートモーメント品川は開催するということになった理由をお教えいただきたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"人流をコントロールといいますか、管理するのがなかなか難しいところがありますので、中止にしたのではないかなというふうに認識しています。配信のみということになりますので、それは安全性は担保できるのかなというふうに認識しております。","id":"exchange-014"},{"speaker":"くにば委員","kind":"質問","question":"１点だけ、最初にこのイベント、１,７００人規模ですか、現地で、観客を入れる予定だったのが、今現在は４００名規模に縮小予定である。４００人規模でも実際会場に人を入れて開催をしたほうがいい、そういった立場なのか、いずれなのかを説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"５０％以下ということになりますと、８００人ぐらいかなというところなのですけれども、最初から入場は４３０人前後の予定で組んでいます。","id":"exchange-015"},{"speaker":"くにば委員","kind":"意見","question":"片や、キャナルフェスは中止を決めた。人流抑制ということを念頭に置いて、ぜひとも区として調整をする中で、お立場をとっていただければという意見で終わらせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"今後スポーツデビュープログラムで実施を考えているのはどういった競技なのかというのを教えていただきたいのが１つ目と、もしくは、もしくは。そういった方も補欠という形で申込みを受けてみるというのはいかがなものかというふうにお伺いしたいのですけれども、ご見解を説明するよう求めました。","respondent":"中元スポーツ推進課長","answer":"実はこの事業、令和２年度に実施を当初予定していた事業です。もし下回った場合につきましては、委員おっしゃったようなご意見のほうを検討させていただければと思います。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"一応、ふだん託児のスペースはあるけれども、こういった区のイベントで託児サービスが設けられるときだけ使っているというふうに伺いました。安心して参加される方が子どもさんを預けられるかどうか、有資格者かどうかという部分についてご答弁をお願いします。","respondent":"中元スポーツ推進課長","answer":"こちらの東品川文化センターのほうを場所として予定をしておりますが、ご紹介等いただいて、お１人ずつちょっと交渉させていただこうと思っているところです。","id":"exchange-018"},{"speaker":"くにば委員","kind":"意見","question":"そういった託児というのが利用できるという、それによって本当に参加される方の幅が広がると思います。イベント等を区内で行うときには、例えば、区の事業としてどんどん広めていっていただければなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"くにば委員","kind":"質問","question":"行政の担当者の方にいろいろお話を伺う、そういったものがとても重要で、重要なことのため開催している部分もあると思います。いろいろお話を伺ったり、何かお考えというか、そういった検討というのはされているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（真）委員長","kind":"提案","question":"逆に委員会個別にやるという形も、ちょっと今その段階では、私としては考えておりません。１つの提案として議長にお話を伝えることはあると思いますけれども、一応確認はした上で、正式なお答えはまた改めてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2906#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":20552,"voices":66}}]);
